insert into guides (id, content) values ('e36-big-brake-kit', '{"id": "e36-big-brake-kit", "title": "Big brake upgrade", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same kits fit other E36 six-cylinders but with different parts", "category": "Brakes", "kind": "upgrade", "heroId": "e36-bbk-hero", "heroCap": "Three upgrade routes: E46 M3 CSL brakes bolted to the E36, a 6-piston ECS kit, or a Brembo/StopTech kit for track use.", "glance": {"timeFirst": "5–8 hr", "timeRepeat": "3–4 hr", "difficulty": 3, "cost": "$800–5,000+", "risk": "Wheel clearance · brake bias moving forward · air in the lines", "why": "The stock M3 brakes are fine on the street. A bigger kit helps with fade on track. The moderate route is the CSL swap, which Turner says is a bolt-on with lots of pad choices.", "note": "Turner suggests a more aggressive rear pad to balance bias, or an engineered kit rather than a retrofit, for serious track driving."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Fit it when fade or heat limits your track days"], "earliest": "Pads fading late in a session", "detail": "For street use the factory brakes are usually enough.", "factors": ["Track use", "Heavier wheels and tires"], "inspect": ["Check wheel clearance before ordering"], "confidence": {"level": "single", "n": 1, "note": "No lifespan data needed."}}, "should": {"yesIf": ["You track the car and the stock brakes fade", "You''ve added power or grip", "You want a firmer pedal at the limit"], "codes": [], "notes": ["Check your wheels clear the new calipers before buying."], "confidence": {"level": "medium", "n": 2, "note": "Turner''s guidance on the upgrade routes."}}, "variants": {"questions": [{"question": "Which route?", "hint": "Cost and complexity rise as you go down the list.", "options": [{"id": "csl", "label": "E46 M3 CSL front brakes", "when": "Bolt-on, 30 mm larger rotors"}, {"id": "ecs6", "label": "ECS 6-piston front kit", "when": "325 × 25 mm rotors"}, {"id": "race", "label": "Brembo GT or StopTech", "when": "Track-focused, engineered kits", "brand": true}]}]}, "parts": [{"tier": "aftermarket", "name": "E46 M3 CSL front brake kit (ECS two-piece rotors)", "price": "$900–1,800", "note": "Turner says the CSL brakes fit the E36 M3 and the rotors are about 30 mm larger. Any E36 M3 or E46 M3 pad works.", "only": ["csl"]}, {"tier": "aftermarket", "name": "ECS 6-piston front big brake kit", "pn": "325×25", "price": "$1,500–2,500", "note": "6-piston calipers from the E82/E88/E9X, 325×25 mm 2-piece rotors, brackets, braided lines and hardware.", "only": ["ecs6"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-Parts/c-565-bmw-big-brake-kits/m-1241-packaged-by-turner?Nrpp=48"}]}, {"tier": "aftermarket", "name": "Brembo GT or StopTech kit", "price": "$2,500–5,000", "note": "Engineered for the chassis. StopTech''s C42 rear ring is 298 × 20.6 mm.", "only": ["race"]}, {"tier": "oe", "name": "Braided lines, fluid and pads", "price": "$100–300", "note": "Most kits include lines. Add a high-temperature fluid."}], "aftermarket": [{"name": "Turner CSL swap", "note": "The moderate upgrade: lower up-front and consumable costs than a Brembo or StopTech kit.", "price": "See Turner", "signal": "Lowest-cost step up"}, {"name": "ECS 6-piston kit", "note": "Uses BMW Performance calipers.", "price": "See Turner"}, {"name": "StopTech C42", "note": "Race kit with replaceable friction rings.", "price": "See BimmerWorld", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Brakes/Big-Brake-Kit-Brake-Rotors/StopTech-C42-298mm-Bi-Slotted-Rear-Aerorotor-Ring.html"}]}], "tools": [{"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Torque wrench", "note": "Per the kit sheet", "price": "$60–100"}, {"name": "Flare-nut wrench and bleeder", "note": "For the new lines", "price": "$30"}], "before": ["Check wheel clearance with the maker.", "Plan a full bleed and bedding-in session.", "Decide on pads and fluid before you start."], "steps": [{"title": "Check clearance before you start", "caution": true, "blocks": [{"t": "chart", "title": "Front rotor diameter", "unit": "mm", "baseline": "Stock M3", "bars": [{"label": "Stock M3", "v": 315}, {"label": "ECS 6-piston", "v": 325}, {"label": "E46 CSL (about)", "v": 345}], "source": "Clickable Automotive, Turner (CSL rotors about 30 mm larger than stock)", "c": {"level": "single", "n": 1, "note": "CSL figure derived from Turner''s 30 mm larger claim."}}, {"t": "text", "b": "Confirm your wheels clear the new calipers. Turner notes some kits need spacers with OEM M3 wheels."}, {"t": "ill", "id": "e36-bbk-hero", "cap": "Stock 315 mm against the larger rotors."}]}, {"title": "Remove the stock brakes", "blocks": [{"t": "text", "b": "Lift the car, take the wheels off, and remove the caliper, carrier and rotor, as in the Pads and rotors guide."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Fit the new brackets and rotors", "blocks": [{"t": "text", "b": "Follow the kit''s sheet for the order and torque values. Don''t mix parts from different kits."}, {"t": "note", "b": "Use the kit''s own sheet. As one example, Essex''s E36 M3 6-piston front kit asks for 11 ft-lb on the pad retention bolts and 150 in-lb on the bleed screws, and it bleeds in the usual right rear, left rear, right front, left front order."}]}, {"title": "Connect the lines and bleed", "caution": true, "blocks": [{"t": "text", "b": "Fit the new lines, then bleed all four corners, following the Fluid flush guide."}, {"t": "warn", "b": "Brakes are a safety system. If you aren''t confident, have a shop do it, and pump the pedal firm before you drive."}]}, {"title": "Bed the pads in", "blocks": [{"t": "text", "b": "Bed in the new pads and rotors as the maker says, then check the bias and clearance on a drive."}]}], "alsoReplace": [{"name": "Rear pads and brake fluid", "why": "Turner recommends balancing the bias with a more aggressive rear pad."}, {"name": "Wheels or spacers", "why": "If clearance is tight."}], "check": {"tab": "Do you need it?", "title": "Is it worth it?", "illId": "e36-bbk-hero", "illCap": "Match the upgrade to the use.", "rows": [{"see": "Street driving only", "means": "Stock brakes plus good pads are enough.", "do": "Skip the kit."}, {"see": "Occasional track days with fade", "means": "A step up helps.", "do": "CSL swap."}, {"see": "Regular track use", "means": "Serious heat.", "do": "Brembo or StopTech."}], "c": {"level": "medium", "n": 2, "note": "Turner''s upgrade guidance."}}, "aftercare": ["Bed the pads in carefully.", "Re-check fittings and fluid level after the first drive."], "disagreements": [{"topic": "Retrofit or engineered kit", "pos": "Turner recommends an engineered kit (StopTech or Brembo) over a retrofit for serious track use.", "call": "CSL swap for budget; engineered kit for serious track use."}], "sources": ["Turner Motorsport — big brake kits for the E36 (CSL swap, ECS 6-piston, Brembo GT, bias note)", "BimmerWorld — StopTech C42 rear ring", "No verified installation torques found"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-brake-fluid-lines', '{"id": "e36-brake-fluid-lines", "title": "Brake fluid flush & stainless lines", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same process on other E36s; lines are model-specific", "category": "Brakes", "kind": "repair", "heroId": "e36-flush-hero", "heroCap": "A flush replaces the fluid in all four corners. Stainless lines replace the rubber hoses that swell under hard braking, and they need a full bleed afterwards.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$30–300", "risk": "Air in the lines · brake fluid on paint · rounding a line fitting", "why": "Fluid absorbs water, which lowers its boiling point and corrodes the system. A flush is cheap insurance. Adding stainless lines at the same time gets you a firmer pedal for the cost of the lines.", "note": "Turner says one liter is typically enough for a flush. ATE Typ 200 is the fluid its kit uses."}, "lifespan": {"title": "When to expect it", "headline": ["Fluid: every one to two years is the usual advice", "Lines: replace when cracked, swollen or if you want a firmer pedal"], "earliest": "A spongy pedal, dark fluid or a track day coming up", "detail": "Fluid change intervals vary by maker. Check your manual.", "factors": ["Age", "Humidity", "Track use"], "inspect": ["Check fluid color in the reservoir", "Look for cracked or bulging hoses"], "confidence": {"level": "single", "n": 1, "note": "General guidance; check the BMW schedule."}}, "should": {"yesIf": ["The fluid is dark or more than two years old", "The pedal feels soft", "You''re preparing for track use", "You want a firmer pedal and are changing hoses anyway"], "codes": [], "notes": ["Brake fluid strips paint. Keep rags and water ready."], "confidence": {"level": "medium", "n": 2, "note": "Turner and owner threads agree."}}, "variants": {"questions": [{"question": "Flush only, or stainless lines too?", "hint": "Lines are a bolt-on swap with a full bleed afterwards.", "options": [{"id": "flushonly", "label": "Flush only", "when": "Fresh fluid in the original lines", "oeOnly": true}, {"id": "withlines", "label": "Flush + stainless lines", "when": "New braided lines at all four corners"}]}]}, "parts": [{"tier": "oe", "name": "ATE Typ 200 DOT 4 brake fluid, 1 liter", "price": "$20–30", "note": "Turner''s flush kit uses it. One liter typically covers a full flush."}, {"tier": "aftermarket", "name": "Pressure bleeder and catch bottle kit", "pn": "Turner Level 3 flush kit", "price": "$80–150", "note": "Schwaben pressure bleeder, catch bottles and wrench. Optional.", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-Parts/c-2-bmw-brakes?N=1z141xt"}]}, {"tier": "aftermarket", "name": "Goodridge G-Stop stainless line set", "price": "$150–250", "note": "Replaces all four rubber lines. DOT approved, TUV approved, bolt-on, stainless braid over PTFE.", "only": ["withlines"], "links": [{"store": "AutoTecknic", "url": "https://autotecknic.com/products/goodridge-e36-m3-stainless-steel-brake-line-set"}]}, {"tier": "aftermarket", "name": "Crush washers or new banjo bolts", "price": "$5–15", "note": "Replace with new lines if the kit doesn''t include them.", "only": ["withlines"]}], "aftermarket": [{"name": "Goodridge G-Stop lines", "note": "Direct replacement for the OEM rubber lines. Pressure-tested to 3,000 psi.", "price": "See retailer", "signal": "TUV approved", "only": ["flushonly"], "links": [{"store": "AutoTecknic", "url": "https://autotecknic.com/products/goodridge-e36-m3-stainless-steel-brake-line-set"}]}, {"name": "ECS Exact Fit braided lines", "note": "Vinyl-coated, DOT-approved. Confirm M3 fitment.", "price": "See ECS", "only": ["flushonly"]}], "tools": [{"name": "Flare-nut wrench for the line fittings", "note": "Stops the fittings from rounding", "price": "$10–20"}, {"name": "Bleeder wrench and clear hose", "note": "Or a pressure bleeder", "price": "$10–60"}, {"name": "Catch bottle and rags", "note": "", "price": "$5"}, {"name": "Jack and four jack stands", "note": "", "price": "$150+"}], "before": ["Have an assistant, or a pressure bleeder.", "Keep fluid off the paint.", "For lines, expect to lose fluid when you open the fittings.", "Don''t let the reservoir run dry."], "steps": [{"title": "Lift the car and take the wheels off", "blocks": [{"t": "text", "b": "Loosen the wheels on the ground, then raise the car on stands and remove all four wheels."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Swap the stainless lines (lines option)", "caution": true, "blocks": [{"t": "text", "b": "Use a flare-nut wrench to loosen each line at the hard line and at the caliper. Fit the new line, with new crush washers on the banjo fittings, and snug the fittings."}, {"t": "text", "b": "Check each line for twisting and make sure it doesn''t touch the tire or suspension at full lock."}, {"t": "ill", "id": "e36-flush-hero", "cap": "Four lines, four bleeders. New lines mean a full bleed."}], "only": ["withlines"]}, {"title": "Fill the reservoir and start the bleed", "blocks": [{"t": "text", "b": "Fill the reservoir with fresh DOT 4. Bleed in this order, farthest from the master cylinder first: right rear, left rear, right front, left front. Pelican''s staff and E36 M3 write-ups give the same order."}, {"t": "note", "b": "Bleed screws are 7 mm at the front and 9 mm at the rear on the E36, per Doug''s Domain. A manual car''s clutch shares the reservoir. Bleed the clutch slave before you do the fronts."}, {"t": "note", "b": "An owner thread says that with ABS the order of the two rears doesn''t matter. Follow the order above anyway."}]}, {"title": "Bleed each corner until the fluid runs clean", "blocks": [{"t": "text", "b": "Open the bleeder, press the pedal slowly, close the bleeder before the pedal comes up and repeat until fresh fluid, with no bubbles, comes out. Keep the reservoir topped up."}, {"t": "text", "b": "The system holds about a liter. One E36 M3 write-up says to have 1.5–2 liters on hand. Turner says a typical flush needs one liter."}, {"t": "text", "b": "Pressure bleeder: keep it to about 20 psi, per the same M3 write-up, and check for leaks first. Never let the reservoir run dry."}]}, {"title": "Check the pedal and fluid level", "caution": true, "blocks": [{"t": "text", "b": "Pump the pedal. It should be firm and not sink. Fix any leaks before you drive."}, {"t": "warn", "b": "Brakes are a safety system. If you aren''t confident, have a shop do it, and pump the pedal firm before you drive."}]}], "alsoReplace": [{"name": "Brake pads and rotors", "why": "The calipers are already apart or close to it."}, {"name": "Clutch fluid", "why": "The clutch hydraulics share the reservoir on manual cars. Check that yours does before assuming it is covered."}], "check": {"tab": "Spongy pedal?", "title": "Is it air or old fluid?", "illId": "e36-flush-hero", "illCap": "A soft pedal has a few causes.", "rows": [{"see": "Soft pedal after a flush", "means": "Air in the system.", "do": "Bleed again."}, {"see": "Pedal sinks slowly", "means": "Leak or failing master cylinder.", "do": "Inspect fittings, hoses and the master cylinder."}, {"see": "Dark fluid", "means": "Old, wet fluid.", "do": "Flush."}], "c": {"level": "medium", "n": 2, "note": "Standard bleed diagnostics."}}, "aftercare": ["Check the reservoir level the next day.", "Re-check fittings for weeping after a few drives.", "Wipe up any spills from the paint right away."], "disagreements": [{"topic": "DOT 3 or DOT 4", "pos": "An owner thread says DOT 4 has a higher boiling point and is the better choice.", "call": "Use DOT 4 (ATE Typ 200 or a similar fluid)."}, {"topic": "Pressure bleed or two-person", "pos": "Pressure bleeding is quicker and tidier. The two-person pump works too.", "call": "A pressure bleeder if you''ll flush regularly."}], "sources": ["Turner Motorsport — brake fluid flush kit and liter-per-flush note", "AutoTecknic — Goodridge G-Stop E36 M3 line set", "ECS — Exact Fit braided lines", "Pelican Parts — E30/E36 brake bleeding (RR, LR, RF, LF; reservoir about 2 quarts)", "Doug''s Domain — E36 brake fluid flush (7 mm front and 9 mm rear bleed screws, standard DOT 4 is fine on the E36)", "M3 Mad Russian — M3 brake and clutch bleeding (system about 1 liter, 20 psi)", "Owner thread on fluid choice (DOT 4 over DOT 3)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-brake-pads-rotors', '{"id": "e36-brake-pads-rotors", "title": "Brake pads & rotors", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "1995 M3 uses the same size rotors; non-M E36 brakes are smaller and different", "category": "Brakes", "kind": "repair", "heroId": "e36-brake-hero", "heroCap": "Single-piston floating calipers, a carrier bolted to the knuckle, a vented 315 mm front rotor and a 312 mm rear. Only the front-left and rear-right pads carry a wear sensor.", "glance": {"timeFirst": "1.5–3 hr per axle", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$150–700 per axle", "risk": "Missing the wear sensor · reinstalling a guide bolt dry · rotor locator bolt left out", "why": "ShiftBMW calls pad changes on the E36 M3 a great first project. Pads and rotors are wear items. Do them as a set per axle, and pick OE-style for quiet or a performance pad for more bite.", "note": "Calipers are single-piston. The M3 has two wear sensors: front left and rear right."}, "lifespan": {"title": "When to expect it", "headline": ["Pads: roughly every 30,000 km (about 19,000 mi) as a general rule", "Rotors: usually every second pad set, or when worn, scored or warped"], "earliest": "Squeal, a grinding noise, shimmy under braking or the BRAKE light from the wear sensor", "detail": "That interval is a general figure from a parts retailer, not an E36-specific one. Driving style matters far more.", "factors": ["Hard driving", "Track use", "Short trips", "Sticking guide pins"], "inspect": ["Look at pad thickness through the wheel", "Check rotor edges for a lip and the surface for scoring"], "confidence": {"level": "single", "n": 1, "note": "Retailer''s generic interval; no E36 M3 figure published."}}, "should": {"yesIf": ["Pads are near the wear limit or the sensor light is on", "The car shudders under braking", "Rotors are scored, lipped or below minimum thickness", "You want a stronger street pad"], "codes": [], "notes": ["Replace pads whenever you replace rotors. Replace both sides of an axle together."], "confidence": {"level": "medium", "n": 3, "note": "ShiftBMW, Zimmermann and Turner agree."}}, "variants": {"questions": [{"question": "Which axle?", "hint": "Front and rear are near-identical jobs with different parts.", "options": [{"id": "bfront", "label": "Front", "when": "315 mm vented rotors"}, {"id": "brear", "label": "Rear", "when": "312 mm rotors, parking brake inside the hat"}]}, {"question": "OE-style or performance?", "hint": "Performance pads bite harder and make more dust. OE-style are quiet and ABS-friendly.", "options": [{"id": "boe", "label": "OE-style", "when": "Zimmermann, Textar, Meyle", "oeOnly": true}, {"id": "bperf", "label": "Performance street", "when": "Hawk HPS 5.0, Pagid, coated or floating rotors"}]}]}, "parts": [{"tier": "oe", "name": "Front rotors (pair)", "pn": "34112227171 (L) · 34112227172 (R) · Zimmermann 150.1290.20 / 150.1291.20", "price": "$150–280", "note": "315 × 28 mm, anti-corrosion coating on the Zimmermann.", "only": ["bfront"]}, {"tier": "oe", "name": "Rear rotors (pair)", "pn": "34212227177 (L) · 34212227178 (R) · Zimmermann 150.1292.20 / 150.1293.20", "price": "$120–220", "note": "312 × 20 mm.", "only": ["brear"]}, {"tier": "oe", "name": "Pad set", "pn": "Zimmermann 20968.195.2 (M3) · rear BMW 34211157334", "price": "$40–90 per axle", "note": "Confirm the axle on any pad number before ordering.", "only": ["boe"]}, {"tier": "oe", "name": "Rear pad wear sensor (right rear only)", "pn": "34351181342", "price": "$8–20", "note": "ShiftBMW lists it for the passenger side. The driver-side rear has none.", "only": ["brear"]}, {"tier": "aftermarket", "name": "Turner Street Enthusiast brake package", "pn": "E36M3TSEBPKT", "price": "$500–800", "note": "Pagid coated rotors, Hawk HPS 5.0 pads, sensors, rotor screws, ATE Typ 200 fluid and Plastilube. Both axles.", "only": ["bperf"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-1258-bmw-build-your-own-brake-service-kit?Nrpp=48"}]}, {"tier": "aftermarket", "name": "Zimmermann floating 2-piece front rotors", "pn": "34112227737 (L) · 34112227738 (R) · Z 150.3417.75 / 150.3418.75", "price": "$350–600", "note": "Almost a kilo lighter per side than the one-piece, per one supplier. Front only.", "only": ["bperf+bfront"]}, {"tier": "oe", "name": "Rotor locator screws, clips and anti-squeal paste", "price": "$10–25", "note": "Replace the clips; use paste on the pad backs only."}], "aftermarket": [{"name": "Hawk HPS 5.0 street pads", "note": "More bite and heat resistance than stock with less dust, and ABS-compatible, per Turner.", "price": "See Turner", "signal": "In Turner''s street kit", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-1258-bmw-build-your-own-brake-service-kit?Nrpp=48"}]}, {"name": "Pagid premium coated rotors", "note": "Coated rotors resist surface rust.", "price": "See Turner"}, {"name": "Zimmermann floating front rotors", "note": "Two-piece, less unsprung weight and better heat dissipation.", "price": "See retailer", "only": ["bfront"]}], "tools": [{"name": "Piston retraction tool or an 8 in C-clamp", "note": "A C-clamp works on these single-piston calipers", "price": "$10–25"}, {"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Torque wrench", "note": "16, 30 and 67 Nm", "price": "$40–70"}, {"name": "Needle-nose pliers", "note": "For the wear sensor", "price": "$8"}, {"name": "Brake cleaner and a wire brush", "note": "", "price": "$10"}], "before": ["Buy the sensor if your pad set doesn''t include it.", "Do both sides of one axle in one sitting.", "Loosen the wheel bolts on the ground first.", "Lay out clean parts and a rag. Keep brake grease off the pad faces and rotors."], "steps": [{"title": "Lift the car and take the wheel off", "blocks": [{"t": "text", "b": "Loosen the wheel bolts, chock the other axle, jack the car and put it on stands. Take the wheel off."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}, {"t": "warn", "b": "Brakes are a safety system. If you aren''t confident, have a shop do it, and pump the pedal firm before you drive."}]}, {"title": "Remove the wear sensor (front left or rear right)", "blocks": [{"t": "text", "b": "Only the front-left and rear-right pads have a sensor. Pull its ceramic end out of the worn pad with needle-nose pliers and unclip its wire."}, {"t": "ill", "id": "e36-brake-hero", "cap": "One sensor per axle: front left and rear right."}]}, {"title": "Take off the caliper and pads", "blocks": [{"t": "text", "b": "Remove the guide bolts, swing or lift the caliper off and slide the old pads out. Hang the caliper from the spring with wire so it doesn''t hang on the hose."}, {"t": "warn", "b": "Never let the caliper hang by its brake hose."}]}, {"title": "Compress the piston", "blocks": [{"t": "text", "b": "Leave the reservoir cap loose so air can escape. Using a clamp, press the piston back carefully with the old inner pad as a spacer."}, {"t": "note", "b": "ShiftBMW suggests removing some fluid from the reservoir first if it is full."}]}, {"title": "Change the rotor (if replacing)", "blocks": [{"t": "text", "b": "Remove the two carrier bolts, take off the carrier and the old rotor, and remove the locator screw. Clean the hub face, fit the new rotor, locator screw and carrier."}, {"t": "torque", "label": "Rotor locator bolt", "nm": 16, "c": {"level": "high", "n": 3, "note": "ShiftBMW, the Bentley list (12 ft-lb) and bimmerdiy all give 16 Nm."}, "note": "M3 rotor screw"}, {"t": "torque", "label": "Caliper carrier bolts (front)", "nm": 110, "c": {"level": "high", "n": 2, "note": "The Bentley list and Garagistic both give 81 ft-lb for the caliper to the steering arm."}, "note": "81 ft-lb", "only": ["bfront"]}, {"t": "torque", "label": "Caliper carrier bolts (rear)", "nm": 67, "c": {"level": "high", "n": 3, "note": "ShiftBMW (67 Nm) and the Bentley list (50 ft-lb) agree."}, "note": "50 ft-lb", "only": ["brear"]}]}, {"title": "Fit new pads and the caliper", "caution": true, "blocks": [{"t": "text", "b": "Clean the carrier slides, fit the new pad set with anti-squeal paste on the backs only, clip the sensor in on the correct side and refit the caliper."}, {"t": "torque", "label": "Caliper guide bolts", "nm": 30, "c": {"level": "high", "n": 3, "note": "ShiftBMW, the Bentley list and m3post all give 22 ft-lb."}, "note": "22 ft-lb"}]}, {"title": "Wheel, pedal, bed-in", "blocks": [{"t": "text", "b": "Put the wheel on and lower the car to the ground."}, {"t": "torque", "label": "Wheel bolts", "nm": 100, "c": {"level": "medium", "n": 2, "note": "Bentley E36 list gives 74 ft-lb (about 100 Nm). Some wheel makers specify differently, so follow yours if it does."}, "note": "star pattern, car on the ground"}, {"t": "text", "b": "Before you drive, pump the brake pedal until it is firm. Then bed the new pads in as the maker says, with a series of moderate stops from speed and no hard stops until they''re warm."}]}], "alsoReplace": [{"name": "Brake fluid flush", "why": "Fluid should be changed regularly. The calipers are open now. See the Fluid flush guide."}, {"name": "Parking brake shoes (rear)", "why": "They sit inside the rear rotor hat. Check them any time you change rear rotors."}, {"name": "Stainless brake lines", "why": "A firmer pedal with new pads."}], "check": {"tab": "Worn out?", "title": "Pads, rotors or something else?", "illId": "e36-brake-hero", "illCap": "Where the noise and shake come from.", "rows": [{"see": "Squeal that stops when you press the pedal", "means": "Pad wear sensor or dry pads.", "do": "Check pad thickness."}, {"see": "Grinding", "means": "Metal on metal.", "do": "Stop driving and replace pads and rotors."}, {"see": "Shudder at speed under braking", "means": "Warped or uneven rotors.", "do": "Replace the rotors with pads."}, {"see": "Pulls to one side", "means": "Sticking guide pins or a hose.", "do": "Clean and lubricate the pins; inspect the hose."}], "c": {"level": "medium", "n": 2, "note": "Common symptoms and fixes."}}, "aftercare": ["Re-check the wheel bolts after 50 miles.", "Bed the pads in per the maker''s instructions.", "Check the fluid level after a day.", "Listen for noises after the first few stops."], "disagreements": [{"topic": "Performance pads on a street M3", "pos": "Turner''s HPS 5.0 kit promises more bite with less dust. Harder track pads squeal and wear rotors faster.", "call": "A street-sport pad like HPS 5.0 is the sensible upgrade. Save race compounds for track use."}, {"topic": "Resurface or replace rotors", "pos": "Resurfacing saves money if the rotor has material left.", "call": "At these prices, replace them with the pads."}], "sources": ["Turner Motorsport — E36 M3 brake kit, Zimmermann floating rotors", "Clickable Automotive — OE and Zimmermann M3 rotor part numbers and sizes", "m3post — guide bolt torque, caliper DIY", "Winparts — Zimmermann M3 pad set; AUTODOC — generic 30,000 km pad interval", "ShiftBMW — E36 M3 front and rear pad and rotor write-ups (guide bolts, rotor screw, rear carrier, sensor locations, part numbers)", "Bentley E36 list as posted on Club Cobra (front caliper to steering arm 81 ft-lb, rear caliper to trailing arm 50 ft-lb, wheel 74 ft-lb)", "Garagistic — E36 bolt torque guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-parking-brake-shoes', '{"id": "e36-parking-brake-shoes", "title": "Parking brake shoes", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Shoe kits also fit the Z3 M; other E36s use a different set", "category": "Brakes", "kind": "repair", "heroId": "e36-park-hero", "heroCap": "The parking brake is a small drum brake inside the hat of each rear rotor. The shoes sit on the inside of the rotor hat, separate from the pads.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$60–200", "risk": "Springs flying off · a lever that won''t hold · forgetting to adjust", "why": "Turner says the parking brake shoes should be inspected and replaced like any other friction surface, and that you should look at them whenever you change rear rotors. They are cheap, but the springs are fiddly.", "note": "Turner recommends replacing the shoe expander with the shoes, or every four years."}, "lifespan": {"title": "When to expect it", "headline": ["Inspect at every rear brake service", "Replace when worn, glazed or the handbrake won''t hold"], "earliest": "A handbrake that needs many clicks or won''t hold on a slope", "detail": "Wear and seized adjusters are the usual problems.", "factors": ["Rust", "Rarely used handbrake", "Wet climates"], "inspect": ["Look at the shoes any time the rear rotors are off"], "confidence": {"level": "single", "n": 1, "note": "Turner''s guidance only."}}, "should": {"yesIf": ["The handbrake lever needs a lot of travel or won''t hold", "You''re replacing the rear rotors and the shoes look worn", "Shoes are glazed or contaminated"], "codes": [], "notes": ["Replacing both sides together is standard."], "confidence": {"level": "single", "n": 1, "note": "Turner''s page."}}, "parts": [{"tier": "oe", "name": "Parking brake shoe set (4 shoes, springs and pins)", "pn": "Febi 34416761289", "price": "$59.99", "note": "Fits E36 M3, Z3 M and E36 non-M. Replaces left and right.", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-Parts/c-1254-bmw-parking-brake-shoes"}]}, {"tier": "oe", "name": "Parking brake adjusting screw", "price": "$10–20", "note": "Located at the top of the shoes. Replace if it is seized."}, {"tier": "oe", "name": "Shoe expander (actuator)", "price": "$20–50", "note": "Turner recommends replacing it with the shoes or every four years."}, {"tier": "oe", "name": "Spring kit and retaining pin", "price": "$10–20", "note": "If your shoe set doesn''t include them."}], "aftermarket": [{"name": "Turner performance parking brake actuator", "note": "A better lever ratio (4:1 instead of 3:1 per Turner) for more clamp load. Check E36 fitment.", "price": "See Turner"}], "tools": [{"name": "Brake spring pliers", "note": "Makes the springs manageable", "price": "$15"}, {"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Brake cleaner and a wire brush", "note": "", "price": "$10"}, {"name": "Torque wrench", "note": "For the carrier bolts", "price": "$40–70"}], "before": ["Do this with the rear rotors off.", "Take photos of the spring layout before you disturb anything.", "Replace both sides."], "steps": [{"title": "Lift the rear and take the rotor off", "blocks": [{"t": "text", "b": "Chock the front wheels, lift the rear and put the car on stands. Remove the wheel, the caliper, the carrier and the rotor, as in the Pads and rotors guide."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}, {"t": "warn", "b": "Brakes are a safety system. If you aren''t confident, have a shop do it, and pump the pedal firm before you drive."}]}, {"title": "Photograph the shoe layout", "blocks": [{"t": "text", "b": "Take a clear photo of the shoes, springs and adjuster before you take anything off. Put the photo next to you."}, {"t": "ill", "id": "e36-park-hero", "cap": "Two shoes, two springs, an adjuster at the top and an expander at the bottom."}]}, {"title": "Remove the old shoes and clean", "blocks": [{"t": "text", "b": "Unhook the springs and take out the shoes and the retaining pin. Clean the backing plate and the hat with brake cleaner."}]}, {"title": "Fit the new shoes", "caution": true, "blocks": [{"t": "text", "b": "Fit the expander, springs and pin as photographed. Back the adjusting screw right off before fitting the rotor so the shoes clear."}]}, {"title": "Refit the rotor and adjust", "blocks": [{"t": "text", "b": "Fit the rotor, carrier and caliper. The shoes adjust through a small sprocket you can reach through one of the wheel-bolt holes in the rotor."}, {"t": "text", "b": "Turn the rotor until you see the sprocket through a bolt hole, then turn it with a screwdriver until the shoes lock the rotor. Then back it off until the wheel turns freely. Pelican says on the right side you turn the sprocket toward the front of the car to tighten, and on the left side toward the rear."}, {"t": "note", "b": "If the wheel drags after you release the lever, the shoes are over-adjusted. Back the sprocket off. If the lever rises more than about 4–5 clicks, the shoes need adjusting."}]}, {"title": "Test", "blocks": [{"t": "text", "b": "Check the lever holds firmly, the wheels don''t drag when released, and test on a gentle slope."}]}], "alsoReplace": [{"name": "Rear rotors and pads", "why": "The rotors are already off."}, {"name": "Handbrake cable", "why": "If the lever has too much slack even after adjustment."}], "check": {"tab": "Does it hold?", "title": "Handbrake check", "illId": "e36-park-hero", "illCap": "Test it on a gentle slope.", "rows": [{"see": "Lever pulls high with little hold", "means": "Worn shoes or loose adjustment.", "do": "Adjust or replace the shoes."}, {"see": "Rear wheel drags", "means": "Over-adjusted or a seized cable.", "do": "Back it off and check the cable."}, {"see": "Won''t release", "means": "Seized cable or expander.", "do": "Replace it."}], "c": {"level": "medium", "n": 2, "note": "Standard handbrake diagnostics."}}, "aftercare": ["Recheck after a week of driving.", "Use the handbrake regularly so it doesn''t seize."], "disagreements": [{"topic": "Replace the expander with the shoes", "pos": "Turner says replace it with the shoes or every four years. Many owners reuse it.", "call": "Replace it when it''s stiff or the lever is slack."}], "sources": ["Turner Motorsport — E36 M3 parking brake shoes, expander and actuator", "Pelican Parts — E30/E36 e-brake adjustment (sprocket through the lug hole, direction, over-adjust symptom)", "bimmerdiy — E36 brake pad and rotor job (4–5 click check)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-chassis-reinforcement', '{"id": "e36-chassis-reinforcement", "title": "Chassis reinforcement: what the M3 has, what to add", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The 1996–99 M3 differs from other E36s; the non-M reinforcement kit isn''t needed unless cracking is present", "category": "Bushings & mounts", "kind": "upgrade", "heroId": "e36-reinf-hero", "heroCap": "Most E36 reinforcement is welded. The M3 already has factory plates in the rear subframe area. Owners add plates at the trailing arm pockets, the sway bar tabs and the shock towers.", "glance": {"timeFirst": "Inspection 1 hr", "timeRepeat": "—", "difficulty": 4, "cost": "$0–1,000+", "risk": "Cracks hidden under dirt · welding near the fuel tank", "why": "E36s crack in a few predictable places. This guide tells you what the M3 already has, where to look, and what to ask a fabricator for. Most of it isn''t a bolt-on job.", "note": "This is an inspection and planning guide. The one bolt-on part is the rear shock mount reinforcement, which has its own guide."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Inspect at least yearly on a driven car"], "earliest": "Cracks appear with age, lowering, stiffer parts and hard driving", "detail": "Stiffer bars, solid mounts and track use all load the same few spots.", "factors": ["Stiffer sway bars", "Solid mounts", "Lowering", "Track use"], "inspect": ["Check rear subframe plates, RTAB pockets, sway bar tabs and shock towers"], "confidence": {"level": "medium", "n": 3, "note": "Turner, ECS and our own earlier research agree on the weak spots."}}, "should": {"yesIf": ["You''re fitting stiffer bars, solid mounts or coilovers", "You track the car", "You see rust lines or cracks at any of the listed spots"], "codes": [], "notes": ["M3s from 1996–99 already have the rear subframe plates (BMW 41002256495/6 and 41112256497/8, per our earlier research). The non-M kit isn''t needed unless the subframe is already cracked."], "confidence": {"level": "single", "n": 1, "note": "Part numbers from one earlier research pass; verify before ordering."}}, "parts": [{"tier": "oe", "name": "Rear shock mount reinforcement plates", "price": "$40–100", "note": "Bolt-on. See the RSM guide."}, {"tier": "aftermarket", "name": "RTAB pocket plates", "price": "Fabricator labor", "note": "Welded in. Ask a fabricator."}, {"tier": "aftermarket", "name": "Rear sway bar tab plates", "price": "Fabricator labor", "note": "Welded in. See the rear sway bar guide."}, {"tier": "aftermarket", "name": "Front subframe motor-mount reinforcement", "price": "$50–150", "note": "Plates or large washers. Turner strongly recommends this with solid motor mounts."}], "aftermarket": [{"name": "Turner subframe reinforcement kits", "note": "Recommended with solid motor mounts.", "price": "See Turner"}], "tools": [{"name": "Flashlight and inspection mirror", "note": "", "price": "$10"}, {"name": "Jack stands", "note": "", "price": "$150+"}, {"name": "Welder or a fabricator", "note": "For anything beyond the shock mount plates", "price": "Shop labor"}], "before": ["Get the car on stands and clean the areas first.", "Photograph anything suspicious before you touch it.", "Decide what you''ll do yourself and what to hand to a shop."], "steps": [{"title": "Know what the M3 already has", "blocks": [{"t": "text", "b": "The 1996–99 M3 comes with rear subframe reinforcement plates from the factory. Don''t buy a non-M kit unless the subframe is cracked."}, {"t": "ill", "id": "e36-reinf-hero", "cap": "Four areas to inspect: rear shock towers, sway bar tabs, trailing arm pockets, front motor-mount area."}]}, {"title": "Inspect the four spots", "caution": true, "blocks": [{"t": "text", "b": "With a flashlight and mirror, look at the rear shock towers, the rear sway bar tabs, the trailing arm pockets and the front subframe motor-mount area. Look for rust lines, cracks and bent metal."}]}, {"title": "Do the bolt-on part", "blocks": [{"t": "text", "b": "Fit reinforcement plates to the rear shock towers (see the RSM guide) and, if you''re going solid mounts, add front plates or washers."}, {"t": "note", "b": "For bolt-on pieces: a front subframe X-brace is 31 ft-lb (about 42 Nm) and the rear strut brace nuts are 18.4 ft-lb, per Garagistic''s E36 guide."}]}, {"title": "Hand the welding to a fabricator", "caution": true, "blocks": [{"t": "warn", "b": "The fuel tank and lines sit above the rear subframe. Anyone welding there must protect them."}, {"t": "text", "b": "Ask for plates on any cracked area, the trailing arm pockets, and the sway bar tabs. Bring the car with the work you want done written down."}]}], "alsoReplace": [{"name": "Rear shock mounts", "why": "Part of the same weak area."}, {"name": "Rear sway bar bushings and links", "why": "The tabs carry them."}], "check": {"tab": "Cracks to find", "title": "What a crack looks like", "illId": "e36-reinf-hero", "illCap": "Rust lines are the first sign.", "rows": [{"see": "Rust line at a shock tower hole", "means": "Tower crack.", "do": "Weld and plate it."}, {"see": "Crack at a sway bar tab weld", "means": "Tab failure.", "do": "Weld and plate before fitting a bar."}, {"see": "Bent or torn trailing arm pocket", "means": "Pocket failure.", "do": "Fabricator plate."}], "c": {"level": "medium", "n": 2, "note": "Typical E36 failure points."}}, "aftercare": ["Re-inspect after the first track day or hard drive.", "Re-inspect yearly."], "disagreements": [{"topic": "Reinforce a street car preemptively", "pos": "Some fabricators plate every E36. Others say inspect and fix only what cracks.", "call": "Inspect first. Plate if you''re adding stiffer parts or tracking."}], "sources": ["Turner Motorsport — solid mounts and subframe reinforcement notes", "ECS and Turner — rear shock mount reinforcement plates", "Our earlier E36 catalog research — M3 factory rear subframe plates and part numbers (verify before ordering)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-engine-trans-mounts', '{"id": "e36-engine-trans-mounts", "title": "Engine & transmission mounts", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Turner''s mount kits fit E36, E46, Z3 and Z4 six-cylinder cars", "category": "Bushings & mounts", "kind": "repair", "heroId": "e36-mounts-hero", "heroCap": "Two engine mounts bolt to the front subframe and one transmission mount sits under the gearbox. Match the material front and back.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$120–600", "risk": "Mismatched mount material · cracking the subframe with solid mounts", "why": "Rubber mounts compress and tear. Turner says not to overlook them as a regular replacement item (about every 50,000 miles). Replacing them tightens up the drivetrain; going stiffer costs you vibration.", "note": "Turner''s rule: use the same material front and rear. Poly engine mounts go with poly trans mounts, solid with solid."}, "lifespan": {"title": "When to expect it", "headline": ["Turner suggests about every 50,000 miles", "Retailer advice, not a factory figure"], "earliest": "Clunks when shifting or on and off throttle, or the engine rocking at idle", "detail": "Worn mounts let the engine move, which strains hoses and the exhaust.", "factors": ["Age", "Heat", "Hard launches"], "inspect": ["Look for torn or collapsed rubber", "Have someone rev while you watch the engine move"], "confidence": {"level": "single", "n": 1, "note": "Turner''s page is the only interval given."}}, "should": {"yesIf": ["The engine rocks or clunks when you shift or lift off", "Mount rubber is torn or sagging", "You want crisper shifts and accept more vibration"], "codes": [], "notes": ["Solid mounts need a reinforced subframe motor-mount area per Turner."], "confidence": {"level": "medium", "n": 2, "note": "Turner and owner write-ups agree."}}, "variants": {"questions": [{"question": "Which mounts?", "hint": "Pick by how you use the car. Keep engine and transmission mounts the same material.", "options": [{"id": "mrubber", "label": "Factory rubber", "when": "OE style", "oeOnly": true}, {"id": "mpoly", "label": "Polyurethane", "when": "Street and occasional track, small NVH cost"}, {"id": "msolid", "label": "Solid aluminum", "when": "Track only, strong vibration", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Engine mounts and transmission mount", "price": "$120–300", "note": "OE rubber set. Replace as a set.", "only": ["mrubber"]}, {"tier": "aftermarket", "name": "Turner polyurethane engine mount set", "pn": "003293TMS02", "price": "See Turner", "note": "Pair with a polyurethane transmission mount (for example 002705ECS02A, PTM-BT, 034-509-0064KT).", "only": ["mpoly"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-533-bmw-drivetrain-mounts-and-upgrades/m-1016-turner-motorsport"}]}, {"tier": "aftermarket", "name": "Turner solid aluminum motor and transmission mount kit", "pn": "TDR9980001", "price": "See Turner", "note": "Engine sits 5 mm lower and the transmission 1 mm lower than stock. Turner strongly recommends the subframe reinforcement kit with it.", "only": ["msolid"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-536-bmw-drivetrain-mount-kits/m-1016-turner-motorsport"}]}], "aftermarket": [{"name": "Turner polyurethane engine mounts", "note": "A balance of OEM comfort and solid response per Turner.", "price": "See Turner"}, {"name": "Turner solid aluminum kit", "note": "Zero deflection, smoother shifts, much more vibration.", "price": "See Turner"}], "tools": [{"name": "Jack and four jack stands", "note": "Plus an engine support or a second jack with a wood block", "price": "$200+"}, {"name": "Socket set, torque wrench", "note": "", "price": "$80"}], "before": ["Pick one material for all mounts.", "Check the front subframe motor-mount area for cracks first.", "Support the engine securely before unbolting any mount."], "chapters": [{"id": "engine", "title": "Engine mounts", "blurb": "Two mounts bolt the engine to the front subframe."}, {"id": "trans", "title": "Transmission mount", "blurb": "One mount under the gearbox."}], "steps": [{"chapter": "engine", "title": "Support the engine", "caution": true, "blocks": [{"t": "text", "b": "Lift the car onto stands and support the engine from below with a jack and a block of wood under the oil pan, or an engine support bar."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}, {"t": "ill", "id": "e36-mounts-hero", "cap": "Two engine mounts at the front, one transmission mount at the rear."}]}, {"chapter": "engine", "title": "Replace the engine mounts", "blocks": [{"t": "text", "b": "Unbolt each mount from the engine bracket and the subframe, lift the engine slightly and swap the mount. Do one side at a time."}, {"t": "note", "b": "Garagistic''s E36 guide gives the mount bushing bolt by material: polyurethane 12–15 ft-lb (16–20 Nm), aluminum 20–25 ft-lb (27–34 Nm), OEM rubber about 30 ft-lb (41 Nm). Use the figure for the material you''re fitting."}]}, {"chapter": "trans", "title": "Support the gearbox and swap the mount", "blocks": [{"t": "text", "b": "Support the transmission, unbolt the crossmember and swap the transmission mount. Refit and tighten."}, {"t": "note", "b": "Transmission mount: Garagistic gives 9–12 ft-lb (12–16 Nm) with threadlocker for polyurethane, Delrin or aluminum, and about 16 ft-lb (22 Nm) for OEM rubber. The transmission brace is 31 ft-lb (42 Nm)."}]}, {"chapter": "trans", "title": "Lower the car and check", "blocks": [{"t": "text", "b": "Lower the engine onto the mounts and tighten everything with the car at rest. Take a short drive and listen for new vibrations."}]}], "alsoReplace": [{"name": "Dogbone or subframe reinforcement", "why": "Solid mounts load the subframe. Reinforce the motor-mount section."}, {"name": "Rear subframe and diff bushings", "why": "If you''re stiffening the drivetrain, do the whole set."}], "check": {"tab": "Worn mount?", "title": "Spot a failing mount", "illId": "e36-mounts-hero", "illCap": "Watch the engine move.", "rows": [{"see": "Engine rocks when you rev with the brake on", "means": "Worn mount.", "do": "Replace the set."}, {"see": "Clunk on shifts", "means": "Worn transmission mount.", "do": "Check it and the engine mounts."}, {"see": "Torn rubber", "means": "Failed mount.", "do": "Replace."}], "c": {"level": "medium", "n": 2, "note": "Standard mount checks."}}, "aftercare": ["Check for new vibrations.", "Re-check the bolts after 100 miles."], "disagreements": [{"topic": "How often to replace", "pos": "Turner suggests every 50,000 miles. Many owners go longer if nothing is torn.", "call": "Inspect often and replace when the rubber looks bad."}], "sources": ["Turner Motorsport — E36 M3 motor mounts, drivetrain mounts and kits (50,000-mile advice, material matching)", "Garagistic — E36 bolt torque guide (mount bolt torque by material, transmission brace 31 ft-lb)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-fcab', '{"id": "e36-fcab", "title": "Front control arm bushings (FCAB)", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same press-in bushing family on other E36s, but the M3 uses offset bushings from the factory", "category": "Bushings & mounts", "kind": "repair", "heroId": "e36-fcab-hero", "heroCap": "The bushing at the rear of each control arm locates it to the frame rail. The M3''s is offset to add caster. Rubber, polyurethane and Delrin all fit the same hole.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$60–260", "risk": "Pressing in an offset bushing the wrong way round · skipping the alignment", "why": "Worn control arm bushings make the front end wander and brake-shimmy. Replacing them is the cheapest way to tighten the E36''s steering feel, and the offset M3 bushing is what gives the car its caster.", "note": "Press-in bushings are the hard part. Pre-pressed bracket kits save time if you''d rather not press them yourself."}, "lifespan": {"title": "When to expect it", "headline": ["Rubber bushings wear out with age and mileage", "No published interval"], "earliest": "Wander at speed, a clunk under braking or shimmy", "detail": "Soft rubber lets the arm shift under braking, which changes caster and camber. Poly and Delrin hold position better but pass more noise.", "factors": ["Age", "Hard braking", "Lowering"], "inspect": ["Pry the arm at the bushing and watch for movement", "Look for cracked rubber"], "confidence": {"level": "single", "n": 1, "note": "Retailer and owner descriptions only."}}, "should": {"yesIf": ["The steering wanders or the car shimmies under braking", "Bushing rubber is split or squashed", "You''re replacing control arms anyway", "You want a firmer, more precise front end"], "codes": [], "notes": ["Offset bushings put the pivot slightly off-centre to add caster. Fit them the right way or the geometry changes."], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld, Turner and owner threads agree."}}, "variants": {"questions": [{"question": "Which bushing?", "hint": "All press into the same arm. Firmer means more feedback and more noise.", "options": [{"id": "fcrubber", "label": "Factory offset rubber", "when": "OE style, quiet, easiest on the car", "oeOnly": true}, {"id": "fcpoly", "label": "Polyurethane", "when": "Powerflex, Garagistic and others. A firmer street choice"}, {"id": "fcdelrin", "label": "Delrin / monoball", "when": "Track use. Noisy and harsh on the street", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Genuine offset control arm bushings (pair)", "pn": "31129064875", "price": "$40–100", "note": "The offset rubber bushing that adds caster. Part number from our earlier research, single source.", "only": ["fcrubber"]}, {"tier": "aftermarket", "name": "Polyurethane control arm bushings", "pn": "Powerflex · Garagistic (80A/95A) · Turner", "price": "$60–150", "note": "Confirm they are the offset type for the M3.", "only": ["fcpoly"]}, {"tier": "aftermarket", "name": "Delrin offset bushings in low-profile housings", "pn": "BimmerWorld TrackCAB", "price": "$100–260", "note": "Sold in a package with Meyle HD arms for $259.99. Track use only.", "only": ["fcdelrin"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Front-Control-Arm-Bushing-Package-TrackCAB-E36-M3-96-99.html"}]}], "aftermarket": [{"name": "BimmerWorld TrackCAB", "note": "Meyle HD arms with offset Delrin bushings, as close as possible to the original 96–99 M3 caster. Track use only.", "price": "$259.99", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Front-Control-Arm-Bushing-Package-TrackCAB-E36-M3-96-99.html"}], "only": ["fcpoly", "fcrubber"]}], "tools": [{"name": "Press, or a large vise", "note": "One owner pressed bushings into the arm with a vise. A hammer and wood block is the last resort.", "price": "$60 or shop"}, {"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Torque wrench", "note": "", "price": "$60–100"}], "before": ["Read the old bushing''s offset before you press it out. Mark it.", "Do the control arm job at the same time.", "Book an alignment."], "steps": [{"title": "Take the control arm off the car", "blocks": [{"t": "text", "b": "Follow the control arm removal in the Control arms guide. Lift the car, disconnect the link and strut, separate the ball joint and unbolt the arm."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Note the offset and press the old bushing out", "caution": true, "blocks": [{"t": "text", "b": "Look at which way the bushing''s offset sits relative to the arm and mark it. Press the old bushing out."}, {"t": "ill", "id": "e36-fcab-hero", "cap": "The offset sits toward one side. Mark it before you press it out."}]}, {"title": "Press the new bushing in", "blocks": [{"t": "text", "b": "Press it in with the offset in the same direction as the old one. Use a press or a vise; keep it square so you don''t distort the housing."}, {"t": "note", "b": "One owner reports pressing bushings in with a vise, or in the worst case with a hammer and a block of wood."}]}, {"title": "Refit the arm", "blocks": [{"t": "text", "b": "Refit the arm and bolts finger-tight, then tighten at ride height."}, {"t": "torque", "label": "Arm bushing carrier to body", "nm": 46, "c": {"level": "high", "n": 3, "note": "Bentley list gives 34 ft-lb and Garagistic gives 31–35 ft-lb."}, "note": "34 ft-lb, at ride height"}, {"t": "torque", "label": "Ball joint nut to steering arm", "nm": 65, "c": {"level": "high", "n": 2, "note": "Bentley list gives 48 ft-lb."}, "note": "48 ft-lb"}, {"t": "torque", "label": "Strut to steering arm", "nm": 105, "c": {"level": "high", "n": 3, "note": "78 ft-lb with a new bolt, per the Bentley list."}}]}, {"title": "Alignment", "caution": true, "blocks": [{"t": "text", "b": "Bushings change caster and camber. Book the alignment before you drive far."}]}], "alsoReplace": [{"name": "Control arms or ball joints", "why": "If the arm is off for bushings, check the joint."}, {"name": "Sway bar links", "why": "Same corner and the links are off anyway."}], "check": {"tab": "Worn bushing?", "title": "Spot a worn bushing", "illId": "e36-fcab-hero", "illCap": "Look and pry before you buy.", "rows": [{"see": "Cracked or squashed rubber", "means": "Worn bushing.", "do": "Replace."}, {"see": "Arm moves when pried", "means": "Worn bushing or loose bolt.", "do": "Check the bolt, then the bushing."}, {"see": "Wander but bushings look fine", "means": "Ball joint, tie rod or alignment.", "do": "Check those."}], "c": {"level": "medium", "n": 2, "note": "Standard bushing checks."}}, "aftercare": ["Alignment right away.", "Re-check the bolts after 100 miles.", "Poly or Delrin: listen for new noises."], "disagreements": [{"topic": "Poly or rubber on a street car", "pos": "Poly holds the arm better. Rubber is quieter.", "call": "Rubber for a daily driver. Poly if you want the firmer feel and accept some noise."}], "sources": ["BimmerWorld — TrackCAB package (M3 differences, offset Delrin)", "Turner Motorsport — FCAB and Delrin notes", "e30zone — owner notes on pressing bushings", "Bentley E36 list as posted on Club Cobra (carrier 34 ft-lb, ball joint 48 ft-lb)", "Garagistic — E36 bolt torque guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-rtab', '{"id": "e36-rtab", "title": "Rear trailing arm bushings (RTAB) & limiters", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The same part number fits E36, E46 and Z4", "category": "Bushings & mounts", "kind": "repair", "heroId": "e36-rtab-hero", "heroCap": "The trailing arm bolts to the body through a rubber bushing at its front. When that bushing splits, rear toe changes under load. Limiters stop the arm moving sideways.", "glance": {"timeFirst": "3–6 hr", "timeRepeat": "2 hr", "difficulty": 4, "cost": "$100–400", "risk": "Rear toe shifts under braking and cornering · pressing the new bushing in crooked", "why": "Turner says RTABs wear out faster than any other bushing on the car. Powerflex says to replace them at over 50,000 miles, on a tracked car, or if you drive hard. A failed one can change rear geometry badly enough to cause loss of control near the limit.", "note": "You''ll need a press or a rental tool, and an alignment afterwards."}, "lifespan": {"title": "When to expect it", "headline": ["Powerflex: replace beyond 50,000 miles", "Turner: they wear faster than any other bushing"], "earliest": "Rear wheel looks toed in or out, or the car feels twitchy under braking", "detail": "Retailer advice, not a factory interval. Check them for cracking and for the arm moving.", "factors": ["Mileage", "Hard braking and cornering", "Lowering"], "inspect": ["Look at both bushings for splits", "Pry the trailing arm and watch the bushing"], "confidence": {"level": "medium", "n": 2, "note": "Turner and Powerflex both describe the same wear."}}, "should": {"yesIf": ["The rear steers itself under braking or on bumps", "Bushings are split or squashed", "Over 50,000 miles on the car", "You track or drive hard"], "codes": [], "notes": ["Limiters surround the bushing and stop sideways movement. They''re a cheap add-on that extends bushing life."], "confidence": {"level": "medium", "n": 3, "note": "Turner, Powerflex and ECS agree."}}, "variants": {"questions": [{"question": "Which bushing setup?", "hint": "Pick by use. A street car rarely needs more than OE plus limiters.", "options": [{"id": "rtoe", "label": "OE rubber", "when": "Factory style", "oeOnly": true}, {"id": "rlim", "label": "OE rubber + limiters", "when": "Longer life, same ride", "oeOnly": true}, {"id": "rpoly", "label": "Polyurethane", "when": "Powerflex Track Series, firmer"}, {"id": "rsphere", "label": "Spherical / monoball", "when": "Turner. Track-focused", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Trailing arm bushings (pair)", "pn": "33 32 2 228 153", "price": "$40–100", "note": "OE rubber replacement. Fits E36, E46 and Z4.", "only": ["rtoe", "rlim"]}, {"tier": "aftermarket", "name": "Trailing arm bushing limiters", "pn": "Turner TSU9990001 · ECS Delrin limiters", "price": "$30–70", "note": "Limit side-to-side deflection to extend bushing life.", "only": ["rlim"]}, {"tier": "aftermarket", "name": "Powerflex Track Series RTAB set", "price": "$101.99", "note": "Polyurethane, lifetime warranty. Priced per pair. Tool rental available.", "only": ["rpoly"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Powerflex-E36-E46-Z4-Rear-Trailing-Arm-Bushing-Kit-RTAB.html"}]}, {"tier": "aftermarket", "name": "Turner sealed monoball RTAB (pair)", "price": "See Turner", "note": "Eliminates deflection. Racing classes may require a non-bearing bushing.", "only": ["rsphere"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-824-bmw-rear-control-arm-bushings/m-1016-turner-motorsport"}]}], "aftermarket": [{"name": "Powerflex Track Series RTAB", "note": "Urethane, legal in many racing classes.", "price": "$101.99", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Powerflex-E36-E46-Z4-Rear-Trailing-Arm-Bushing-Kit-RTAB.html"}], "only": ["rtoe", "rlim"]}, {"name": "ECS OE bushings with limiters", "note": "Delrin limiters, wear and noise resistant.", "price": "See ECS", "only": ["rtoe", "rpoly"]}], "tools": [{"name": "RTAB tool kit or a press", "note": "Rental tools exist; some owners do it with and without special tools", "price": "$40–150"}, {"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Torque wrench", "note": "Up to 110 Nm for the arm bolts", "price": "$60–100"}], "before": ["Plan on an alignment immediately afterwards.", "Buy or rent the press tool first.", "Soak the arm bolts the night before."], "steps": [{"title": "Lift the rear and take the wheels off", "blocks": [{"t": "text", "b": "Chock the front wheels, lift the rear and put the car on stands. Remove the wheels."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Support the trailing arm and unbolt it", "caution": true, "blocks": [{"t": "text", "b": "Support the trailing arm with a jack. Undo the bolts holding the trailing arm bracket to the body and take the bracket off."}, {"t": "ill", "id": "e36-rtab-hero", "cap": "The bushing sits in the trailing arm''s front eye. The limiter wraps around it."}, {"t": "note", "b": "Torque references from ECS: trailing arm bracket to body 77 Nm; lower arm to trailing arm eccentric 110 Nm."}]}, {"title": "Press the old bushing out", "blocks": [{"t": "text", "b": "Press out the old bushing with the tool or a press. Clean the eye, check it for damage and fit the new bushing square."}]}, {"title": "Fit the limiters", "blocks": [{"t": "text", "b": "Fit the limiters around the new bushing following their instructions."}], "only": ["rlim"]}, {"title": "Refit and tighten at ride height", "blocks": [{"t": "text", "b": "Refit the arm and bracket finger-tight, lower the car onto its wheels, then tighten the bracket bolts."}, {"t": "torque", "label": "Trailing arm bracket to body", "nm": 77, "c": {"level": "high", "n": 3, "note": "ECS (77 Nm), the Bentley list (57 ft-lb) and Garagistic (57 ft-lb) agree."}, "note": "at ride height"}, {"t": "torque", "label": "Trailing arm to front bracket (RTAB bolt)", "nm": 110, "c": {"level": "high", "n": 2, "note": "The Bentley list and Garagistic both give 81 ft-lb."}, "note": "81 ft-lb, at ride height"}]}, {"title": "Alignment", "caution": true, "blocks": [{"t": "text", "b": "New bushings change rear toe and camber. Book an alignment, and tell the shop what you fitted."}]}], "alsoReplace": [{"name": "Rear control arm bushings", "why": "Another common wear point in the same area."}, {"name": "Adjustable rear arms", "why": "Useful if the car is lowered. See the rear camber guide."}, {"name": "Rear subframe bushings", "why": "A subframe drop is the time. See the chassis reinforcement guide."}], "check": {"tab": "Worn bushing?", "title": "Spot a failing RTAB", "illId": "e36-rtab-hero", "illCap": "Rear toe change is the telltale.", "rows": [{"see": "Rear tires toe in or out when you push the arm", "means": "Worn bushing.", "do": "Replace."}, {"see": "Cracked rubber", "means": "Worn bushing.", "do": "Replace."}, {"see": "Twitchy rear under braking", "means": "Worn RTAB or toe out.", "do": "Check bushings, then alignment."}], "c": {"level": "medium", "n": 2, "note": "Common RTAB symptoms from retailers and owners."}}, "aftercare": ["Alignment immediately.", "Re-check the bracket bolts after 100 miles.", "Check the limiters at the next oil change."], "disagreements": [{"topic": "Poly or rubber with limiters", "pos": "Poly holds geometry and lasts longer. OE plus limiters keeps stock noise levels.", "call": "OE plus limiters for street cars. Poly or monoball for track use."}], "sources": ["Turner Motorsport — RTAB, limiters and monoball bushings", "BimmerWorld — Powerflex RTAB (50,000-mile advice, price)", "ECS — E36 rear suspension torque specifications", "Bentley E36 list as posted on Club Cobra", "Garagistic — E36 bolt torque guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-clutch-flywheel', '{"id": "e36-clutch-flywheel", "title": "Clutch & flywheel", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The same M3 clutch is used in the Euro M3; non-M E36s use a smaller disc", "category": "Drivetrain", "kind": "repair", "heroId": "e36-clutch-hero", "heroCap": "Flywheel, disc, pressure plate and release bearing, with the slave cylinder alongside. The factory flywheel is dual-mass, a known failure point.", "glance": {"timeFirst": "8–14 hr", "timeRepeat": "5–7 hr", "difficulty": 4, "cost": "$500–1,800", "risk": "Dropping the transmission · mismatched flywheel and disc · reusing bolts", "why": "SPEC says the stock M3 clutch isn''t a bad clutch and isn''t under-rated. It wears early when driven hard, and the factory dual-mass flywheel is a known failure point. The job is big, so do it with the right parts for how you drive.", "note": "A lightweight single-mass flywheel makes the car rev faster but rattles and can chatter. Pair it with a clutch disc designed for single-mass use."}, "lifespan": {"title": "When to expect it", "headline": ["Clutches typically last 80–150k miles on a street car", "The dual-mass flywheel can fail sooner"], "earliest": "Slipping under load, a rattle at idle or a high, grabby pedal", "detail": "General figure, not E36-specific. The DMF''s internal rubber dampers wear over time.", "factors": ["Hard launches", "Towing", "More power", "Riding the clutch"], "inspect": ["Feel for slip in a high gear at full throttle", "Listen for rattle at idle"], "confidence": {"level": "single", "n": 1, "note": "General interval; SPEC''s comments on stock durability."}}, "should": {"yesIf": ["The clutch slips or the pedal is heavy or engages high", "The flywheel rattles or the shifter vibrates at idle", "You''re replacing the transmission or guibo anyway"], "codes": [], "notes": ["SPEC says its tuned M3s ran the stock clutch past 300 hp with only an occasional slip. Don''t overbuy on a stock engine."], "confidence": {"level": "medium", "n": 2, "note": "SPEC and Turner agree."}}, "variants": {"questions": [{"question": "What setup?", "hint": "The setup sets the parts list and feel.", "options": [{"id": "coe", "label": "OE-style", "when": "Sachs OEM kit with the dual-mass flywheel", "oeOnly": true}, {"id": "cdmf", "label": "Performance clutch, stock flywheel", "when": "Heavy-duty disc and plate that suit the dual-mass"}, {"id": "csmf", "label": "Lightweight single-mass flywheel", "when": "Faster revs, more noise", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Sachs OEM clutch kit (disc, pressure plate, throw-out bearing)", "price": "$250–450", "note": "Turner lists the Sachs OEM kit for the E36 M3 3.2.", "only": ["coe"]}, {"tier": "oe", "name": "Dual-mass flywheel", "price": "$350–700", "note": "Inspect or replace. The rubber dampers wear out. A used one is a gamble.", "only": ["coe", "cdmf"]}, {"tier": "aftermarket", "name": "SPEC Stage 2 clutch kit", "price": "$450–800", "note": "Carbon-Kevlar disc rated 370 ft-lb with a heavy-duty plate and throw-out bearing. Works with the stock or a single-mass flywheel.", "only": ["cdmf"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/m-637-spec-clutches"}]}, {"tier": "aftermarket", "name": "Single-mass flywheel and clutch kit", "pn": "Turner E34 M5-geometry kit, JB Racing, DXD, ECS, Epytec", "price": "$700–1,500", "note": "The E34 M5 kit includes a flywheel, disc, plate, throw-out and pilot bearings, alignment tool and 8 flywheel + 6 plate bolts. ECS''s flywheel needs shorter bolts, 8× 11227805885.", "only": ["csmf"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-36-bmw-clutch-flywheel/m-1999-enthusiast-built?Nrpp=50"}]}, {"tier": "oe", "name": "Clutch slave cylinder", "price": "$40–120", "note": "Replace with the clutch. It''s inside the bellhousing area."}, {"tier": "oe", "name": "Pilot bearing, flywheel bolts, plate bolts, rear main seal", "price": "$30–100", "note": "New bolts where specified. Replace the rear main seal while it''s exposed."}], "aftermarket": [{"name": "SPEC Stage 2+", "note": "Carbon-Kevlar, 370 ft-lb, designed for stock dual-mass or aluminum single-mass flywheels.", "price": "See Turner", "signal": "S52-specific tuning", "only": ["coe", "cdmf"]}, {"name": "South Bend / JB Racing aluminum flywheel kits", "note": "Light aluminum flywheel with sport Sachs disc and plate.", "price": "See Turner", "only": ["coe", "cdmf"]}, {"name": "ClutchMasters FX series with aluminum flywheel", "note": "Stages from FX100 to FX400.", "price": "See Turner"}, {"name": "Turner clutch and flywheel package", "note": "Stock M3 clutch with a JB aluminum flywheel, slave cylinder and UUC clutch stop.", "price": "See Turner"}], "tools": [{"name": "Transmission jack", "note": "Essential for safely lowering the gearbox", "price": "$60–150 rental"}, {"name": "Clutch alignment tool", "note": "Included in many kits", "price": "$15"}, {"name": "Jack and four jack stands, or a lift", "note": "", "price": "$150+"}, {"name": "Torque wrench", "note": "", "price": "$60–100"}], "before": ["Do this with a lift or a long weekend.", "Replace the slave cylinder, pilot bearing and rear main seal in the same session.", "Decide on the flywheel before you buy the clutch."], "steps": [{"title": "Plan and prepare", "blocks": [{"t": "chart", "title": "Flywheel weight (lb)", "unit": "lb", "baseline": "Factory dual-mass", "bars": [{"label": "Factory dual-mass", "v": 25.3}, {"label": "Single-mass (E34 M5 geometry)", "v": 16.5}], "source": "Turner enthusiast-built kit listing", "c": {"level": "single", "n": 1, "note": "One kit listing; other flywheels vary."}}, {"t": "text", "b": "Disconnect the battery and have the transmission jack ready. Lift the car securely."}, {"t": "ill", "id": "e36-clutch-hero", "cap": "Weights: the factory dual-mass is heavy; single-mass kits are about 9 lb lighter."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Remove the driveshaft, exhaust and transmission", "caution": true, "blocks": [{"t": "text", "b": "Support the exhaust, drop the driveshaft (see the Guibo guide), disconnect the shifter and slave cylinder and unbolt the transmission. Lower it on the jack."}, {"t": "torque", "label": "Slave cylinder nuts", "nm": 22, "c": {"level": "high", "n": 3, "note": "ECS''s E36/E46 flywheel instructions and an E46 clutch guide both give 22 Nm (16 ft-lb)."}, "note": "16 ft-lb, on refit"}, {"t": "note", "b": "On refit: bell housing bolts are M8 22 Nm (16 ft-lb) and M10 42 Nm (31 ft-lb), and the reinforcing cross-brace to the chassis is 42 Nm (32 ft-lb), per ECS."}]}, {"title": "Take the old clutch and flywheel off", "blocks": [{"t": "text", "b": "Remove the pressure plate bolts evenly, then the disc, then the flywheel bolts. Inspect the flywheel face and the crank seal."}]}, {"title": "Fit the flywheel", "blocks": [{"t": "text", "b": "Clean the crank flange. Fit the new flywheel with new bolts per the kit. Keep a single-mass flywheel''s shorter bolts if the kit specifies them."}, {"t": "text", "b": "Single-mass flywheels don''t dampen like the dual-mass. A disc built for single-mass use is recommended.", "only": ["csmf"]}, {"t": "torque", "label": "Flywheel bolts (stock-style)", "nm": 104, "c": {"level": "high", "n": 3, "note": "ECS''s E36/E46 instructions give 104 Nm (77 ft-lb). An owner S52 install used 105 Nm after 25 then 40 Nm in a star pattern."}, "note": "77 ft-lb, new bolts, star pattern, lock the flywheel"}, {"t": "note", "b": "Lightweight kits can differ. ECS''s own instructions mention pre-tightening to 50 Nm and finishing at 120 Nm for their flywheel. Follow your flywheel maker''s sheet if it gives a number."}]}, {"title": "Fit the disc and pressure plate", "caution": true, "blocks": [{"t": "text", "b": "Use the alignment tool to centre the disc, then tighten the pressure plate bolts evenly in a star pattern."}, {"t": "torque", "label": "Pressure plate bolts", "nm": 34, "c": {"level": "high", "n": 3, "note": "ECS gives 34 Nm (25 ft-lb); an E9X thread and another owner thread give the same."}, "note": "25 ft-lb, star pattern"}]}, {"title": "Refit the transmission", "blocks": [{"t": "text", "b": "Replace the pilot bearing and throw-out bearing, lube the splines lightly, raise the transmission and bolt it up. Refit the slave cylinder, shifter, driveshaft and exhaust."}, {"t": "note", "b": "Transmission mount: 16 ft-lb (22 Nm) for OEM rubber, per Garagistic. Driveshaft and guibo bolts: see the Guibo guide."}]}, {"title": "Bleed and test", "blocks": [{"t": "text", "b": "Bleed the clutch hydraulics and check the pedal. Drive gently for the first few hundred miles to bed the disc in."}]}], "alsoReplace": [{"name": "Slave cylinder", "why": "It''s out of reach once the box is back in."}, {"name": "Guibo and center support bearing", "why": "The driveshaft is down."}, {"name": "Transmission mount", "why": "Worn mounts shorten clutch and gearbox life. See the Mounts guide."}, {"name": "Rear main seal", "why": "A leak here ruins a new clutch."}, {"name": "Shifter bushings", "why": "The shifter is disconnected anyway."}], "check": {"tab": "Slip or rattle?", "title": "Is it the clutch or the flywheel?", "illId": "e36-clutch-hero", "illCap": "Symptoms differ.", "rows": [{"see": "Revs rise without speed in a high gear", "means": "Slipping clutch.", "do": "Replace the clutch."}, {"see": "Rattle at idle that stops with the pedal in", "means": "Dual-mass flywheel or release bearing.", "do": "Check the flywheel."}, {"see": "Pedal sinks or won''t release", "means": "Hydraulics.", "do": "Check the slave and master cylinders."}], "c": {"level": "medium", "n": 2, "note": "Typical clutch symptoms."}}, "aftercare": ["Bed the disc in gently.", "Re-check the hydraulics and leaks after a week."], "disagreements": [{"topic": "Keep the dual-mass or go single-mass", "pos": "Turner says a single-mass aluminum flywheel is lighter and revs faster but won''t damp like the dual-mass. SPEC says the DMF is a known failure point.", "call": "Street car: OE-style or SPEC with a good DMF. Track or enthusiast car: single-mass with a matching disc."}], "sources": ["Turner Motorsport — E36 M3 clutch and flywheel packages, E34 M5-geometry kit, ECS flywheel notes", "SPEC Clutches — E36 M3 Stage 2 (370 ft-lb, DMF failure point, stock clutch notes)", "Epytec — S50/S52 lightened flywheel notes on single-mass clutch discs", "ECS — E36/E46 lightweight flywheel installation (flywheel 104 Nm, plate 34 Nm, slave 22 Nm, bell housing M8/M10)", "Brentford Racing — E36 S52 clutch install (flywheel star pattern 25, 40, 105 Nm; DMF about 25 lb vs 14 lb flywheel)", "Garagistic — E36 bolt torque guide (transmission mount)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-differential-upgrade', '{"id": "e36-differential-upgrade", "title": "Differential: LSD, gearing & reinforcement", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "1996–99 M3 uses 3.23 gears; the 1995 M3 used 3.15; non-M E36s used 2.93", "category": "Drivetrain", "kind": "upgrade", "heroId": "e36-diff-hero", "heroCap": "The M3 has a clutch-type limited slip. You can rebuild or replace it, change the gear ratio, and strengthen the mounting.", "glance": {"timeFirst": "Bolt-on 1 hr · swap 5–8 hr", "timeRepeat": "—", "difficulty": 4, "cost": "$100–2,000", "risk": "Shearing the diff mount bolt · wrong flange on non-M diffs · fluid for the wrong type of LSD", "why": "The factory M3 has a limited slip, so this is about making it stronger or changing its character. The cheap upgrades are bushings, a support bracket and a stronger cover. The big ones are a rebuilt or different LSD and shorter gearing.", "note": "Diffsonline requires a core return. A diff built for the M3 uses different output flanges than a non-M one."}, "lifespan": {"title": "When to expect it", "headline": ["LSD clutch packs wear with use", "Mounts and bushings are the usual failure"], "earliest": "Chatter or slip in tight turns, a clunk on throttle changes or a sheared diff mount bolt", "detail": "The factory 2-clutch unit is fine for daily use and moderate street use, per Diffsonline. Heavy track use, or removing the traction control, makes the LSD matter more.", "factors": ["Track use", "ASC deleted", "Clutch kicks"], "inspect": ["Look at the diff mount bolt and cover", "Check for clunks on throttle changes"], "confidence": {"level": "single", "n": 1, "note": "Diffsonline''s description."}}, "should": {"yesIf": ["The diff chatters, clunks or slips in turns", "You''re tracking the car and want more lock", "You want shorter gearing for acceleration", "The diff mount bolt or bushings are worn"], "codes": [], "notes": ["Gear ratio changes are a trade: faster acceleration, higher revs at speed."], "confidence": {"level": "medium", "n": 2, "note": "Diffsonline, Turner and Condor agree."}}, "variants": {"questions": [{"question": "What do you want?", "hint": "Bolt-on strengthening is a simple job; a diff swap is a big one.", "options": [{"id": "dbolt", "label": "Bolt-on strengthening", "when": "Support bracket, bushings, billet cover", "oeOnly": true}, {"id": "drebuild", "label": "Rebuild or upgrade the LSD", "when": "Clutch, 3-clutch, helical or OS Giken"}, {"id": "dgear", "label": "Change the gear ratio", "when": "Shorter final drive"}]}]}, "parts": [{"tier": "aftermarket", "name": "Active Autowerke differential support bracket", "pn": "AA-DSB-E36", "price": "See Turner", "note": "Stops the main diff mounting bolt shearing in hard driving. Under an hour to fit.", "only": ["dbolt"]}, {"tier": "aftermarket", "name": "Polyurethane or UHMW differential bushings", "pn": "Revshift · Condor", "price": "$40–150", "note": "Reduce driveline wind-up. The Condor 14 mm front bushing upgrade needs the casing drilled and tapped to M14×1.5.", "only": ["dbolt"]}, {"tier": "aftermarket", "name": "Turner reinforced billet differential cover (188 mm)", "price": "See Turner", "note": "A stronger cover than the cast aluminum stock one.", "only": ["dbolt"]}, {"tier": "aftermarket", "name": "Diffsonline custom performance differential", "price": "$1,000–2,000 plus core", "note": "Fully rebuilt with seals and bearings. LSD choices include clutch type, 2 or 3 clutch packs, helical and OS Giken, with a gearing choice.", "only": ["drebuild", "dgear"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Driveline-Shifter/Differentials-Accessories/E36-Diffsonline-Custom-Performance-Differential.html"}]}, {"tier": "oe", "name": "Diff fluid and a new drain plug", "price": "$20–100", "note": "See the Fluid guide. A magnetic M22 × 1.5 plug is available.", "only": ["drebuild", "dgear", "dbolt"]}], "aftermarket": [{"name": "Diffsonline custom diffs", "note": "Two LSD families: clutch and helical. The factory M3 unit is a 2-clutch layout.", "price": "See BimmerWorld", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Driveline-Shifter/Differentials-Accessories/E36-Diffsonline-Custom-Performance-Differential.html"}]}, {"name": "Turner, Condor, Active Autowerke, Revshift", "note": "Ring and pinion sets, bushings and support brackets.", "price": "See Turner"}], "tools": [{"name": "Jack and four jack stands, transmission jack", "note": "To support the diff", "price": "$200+"}, {"name": "Torque wrench", "note": "", "price": "$60–100"}, {"name": "Rebuilder or shop", "note": "Ring and pinion work needs a professional", "price": "Shop labor"}], "before": ["Know your ratio: 3.23 (1996–99) or 3.15 (1995).", "Order the M3-specific diff if you need M3 flanges.", "Plan for the core return."], "steps": [{"title": "Decide what you''re doing", "blocks": [{"t": "text", "b": "Strengthening is bolt-on. Rebuilding or changing gearing means dropping the diff and sending it to a specialist."}, {"t": "ill", "id": "e36-diff-hero", "cap": "Diff mount bolt, cover and bushings: the three cheap fixes."}]}, {"title": "Lower the differential", "caution": true, "blocks": [{"t": "text", "b": "Support the diff with a jack, disconnect the driveshaft and axles and unbolt the mounts. See the Guibo guide for the driveshaft."}, {"t": "torque", "label": "Differential carrier to body", "nm": 77, "c": {"level": "high", "n": 3, "note": "The Bentley list, Garagistic and Condor all give 57 ft-lb."}, "note": "57 ft-lb"}, {"t": "note", "b": "Mounts: the front diff mount bolt is 70 ft-lb (95 Nm). The rear and the cover bushings are 57 ft-lb (77 Nm). Axle flange bolts are M8 47 ft-lb (64 Nm) and M10 74 ft-lb (100 Nm) per Garagistic, though one Bentley-derived list gives 62 ft-lb for the M10. Use the figure for your bolt size and check its head marking."}]}, {"title": "Fit the support bracket, bushings or cover", "blocks": [{"t": "text", "b": "Swap the bushings, fit the support bracket and billet cover per their sheets."}], "only": ["dbolt"]}, {"title": "Send the diff for rebuild", "blocks": [{"t": "text", "b": "Return the diff to the specialist with your ratio and LSD choice. Diffsonline''s rebuild includes new seals and bearings, with a core charge refunded on return."}], "only": ["drebuild", "dgear"]}, {"title": "Refit, fill and test", "blocks": [{"t": "text", "b": "Refit the diff, fill with 75W-90 (see the Fluid guide), and drive gently for the first miles."}]}], "alsoReplace": [{"name": "Axle seals and rear wheel bearings", "why": "The axles are out."}, {"name": "Rear subframe and RTAB bushings", "why": "See the Bushings & mounts guides."}, {"name": "Diff fluid", "why": "Always."}], "check": {"tab": "Diff problems", "title": "What''s wrong with the diff?", "illId": "e36-diff-hero", "illCap": "Symptoms by type.", "rows": [{"see": "Clunk on throttle changes", "means": "Diff mount or bushings.", "do": "Check the mount bolt and bushings."}, {"see": "Chatter in tight turns", "means": "Worn LSD clutches or wrong fluid.", "do": "Change fluid; rebuild if it continues."}, {"see": "Inside wheel spins on corner exit", "means": "LSD not locking.", "do": "Rebuild or upgrade."}], "c": {"level": "medium", "n": 2, "note": "Typical diff diagnostics."}}, "aftercare": ["Check for leaks after a few drives.", "Change fluid after break-in on a new diff."], "disagreements": [{"topic": "Clutch or helical LSD", "pos": "Diffsonline lists both. The factory clutch type is fine for street use.", "call": "Clutch type for the street and track. Helical for quiet, maintenance-free operation."}], "sources": ["Diffsonline via BimmerWorld — E36 M3 custom differential (3.15 and 3.23 ratios, clutch vs helical)", "Turner Motorsport — billet differential cover, drain plug", "Active Autowerke — diff support bracket", "Condor, Revshift — diff bushings", "Bentley E36 list as posted on Club Cobra (diff carrier 57 ft-lb, front mount 70 ft-lb)", "Garagistic and Condor — E36 torque guides (diff to subframe 57 ft-lb, front diff bushings 70 ft-lb, rear and cover bushings 57 ft-lb)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-guibo-csb', '{"id": "e36-guibo-csb", "title": "Guibo & center support bearing", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The M3 guibo (26112226527) also fits E46 M3, E34 M5 and Z3 M; non-M E36s use a different one", "category": "Drivetrain", "kind": "repair", "heroId": "e36-guibo-hero", "heroCap": "The guibo is a rubber coupling at the back of the transmission. The center support bearing holds the two-piece driveshaft in the middle. When one fails the others tend to follow.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$80–400", "risk": "Driveshaft balance and alignment · dropping the shaft · reusing a stretched bolt", "why": "Vibration through the floor and a clunk when you get on and off the throttle are the classic E36 driveline complaints. Both parts are rubber and age out. Turner says if one of the guibo, center bearing or u-joints fails the others often follow, so inspect all three.", "note": "The center support carrier has a popular upgrade. Instead of a floppy rubber bushing, split poly bushings clamp the bearing."}, "lifespan": {"title": "When to expect it", "headline": ["No fixed interval", "Rubber ages with heat and torque"], "earliest": "Vibration at speed, a driveline clunk or a growl from the middle of the car", "detail": "Replace when cracked or when there''s play. A guibo that is torn shows cracks and loose rubber around the bolt sleeves.", "factors": ["Age", "Hard launches", "Lowered cars with a changed driveshaft angle"], "inspect": ["Look at the guibo for cracks", "Move the driveshaft by hand and feel for play in the center bearing"], "confidence": {"level": "medium", "n": 2, "note": "Turner and Motoiq both describe the same failure pattern."}}, "should": {"yesIf": ["You feel vibration through the floor at speed", "There''s a clunk on and off throttle", "The guibo is cracked or the center bearing growls", "You''re replacing the clutch or transmission mount"], "codes": [], "notes": ["Do the guibo whenever the driveshaft is down for another job."], "confidence": {"level": "medium", "n": 2, "note": "Turner and Motoiq agree."}}, "variants": {"questions": [{"question": "What are you replacing?", "hint": "Doing both costs little extra once the shaft is down.", "options": [{"id": "gonly", "label": "Guibo only", "when": "Cracked or torn flex disc"}, {"id": "csonly", "label": "Center support bearing only", "when": "Growl or play at mid-shaft"}, {"id": "gboth", "label": "Both", "when": "Recommended while the shaft is out"}]}, {"question": "Standard or upgraded center support?", "hint": "Only matters if you''re doing the center bearing.", "options": [{"id": "csoe", "label": "Standard rubber carrier", "when": "OE-style Febi or Meyle", "oeOnly": true}, {"id": "csup", "label": "Upgraded poly carrier", "when": "ECS or JXB clamp-on bushings"}]}]}, "parts": [{"tier": "oe", "name": "Guibo (flex disc), M3", "pn": "26112226527 (Febi · Meyle)", "price": "$60–110", "note": "For the 1995–99 M3 manual and auto. Replace the guibo bolts and check which numbers your guibo uses.", "only": ["gonly", "gboth"]}, {"tier": "oe", "name": "Center support bearing", "pn": "26121226731 (Febi · Meyle)", "price": "$40–100", "note": "Standard carrier with a rubber mount.", "only": ["csonly+csoe", "gboth+csoe"]}, {"tier": "aftermarket", "name": "ECS driveshaft center support carrier", "pn": "013137LA01KT", "price": "$80–140", "note": "Split polyurethane bushings clamp the existing bearing. Cut around the bearing, remove the factory brace, clamp on the new bushings.", "only": ["csonly+csup", "gboth+csup"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E85/c-262-bmw-driveshafts-guibos-csbs"}]}, {"tier": "aftermarket", "name": "JXB Performance center support upgrade", "price": "See retailer", "note": "Cuts away the stock carrier so bushings clamp down on the driveshaft bearing.", "only": ["csonly+csup", "gboth+csup"]}, {"tier": "oe", "name": "New guibo and driveshaft bolts, nuts", "price": "$15–30", "note": "Use new where the maker specifies.", "only": ["gonly", "gboth"]}], "aftermarket": [{"name": "ECS center support carrier", "note": "A split-poly clamp that stops the bearing from deflecting.", "price": "See ECS", "signal": "Fixes a known weak point"}, {"name": "Meyle HD remanufactured driveshaft", "note": "Rebuilt with new bushings, u-joints and center bearing, balanced, with serviceable u-joints for the future.", "price": "See Turner", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-Parts/c-262-bmw-driveshafts-guibos-csbs/m-703-meyle-hd?Nrpp=50"}]}], "tools": [{"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Transmission jack or a helper", "note": "To support the shaft while it comes down", "price": "$0–80"}, {"name": "Snap-ring pliers", "note": "For the center bearing", "price": "$15"}, {"name": "Torque wrench", "note": "", "price": "$40–70"}], "before": ["Mark the driveshaft halves so they go back in the same position.", "Support the exhaust before moving the heat shield or hangers.", "Buy bolts and nuts with the parts."], "steps": [{"title": "Raise the car and support the exhaust", "blocks": [{"t": "text", "b": "Raise the car on stands. Support the exhaust where it crosses the driveshaft, then take out the parts that block it."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Mark and disconnect the driveshaft", "blocks": [{"t": "text", "b": "Mark both ends of the driveshaft and the guibo so it goes back the same way. Undo the center support carrier bolts and the guibo bolts at the transmission."}, {"t": "ill", "id": "e36-guibo-hero", "cap": "Guibo at the front, center bearing in the middle, rear flange at the differential."}]}, {"title": "Lower the shaft", "caution": true, "blocks": [{"t": "text", "b": "Lower the shaft and drop the rear flange from the differential. The shaft is long and awkward, so support both ends."}, {"t": "note", "b": "Torque depends on which bolts you have. Garagistic''s E36 guide lists the guibo by bolt size and grade: M10 8.8 is 35 ft-lb (47 Nm), M10 10.9 is 47 ft-lb (64 Nm), M12 8.8 is 60 ft-lb (81 Nm), and M12 10.9 is 74 ft-lb (100 Nm). Read the head marking and use the matching number. ECS''s flywheel instructions list 21 Nm (16 ft-lb) for the smaller flex coupler nut on a lighter setup. Guibo nuts and torx bolts are single-use."}, {"t": "note", "b": "Driveshaft to final drive flange with a u-joint: 59 ft-lb (80 Nm) for an M10 ribbed nut, 44 ft-lb (60 Nm) for an M10 compressed nut, per Garagistic."}]}, {"title": "Replace the guibo", "blocks": [{"t": "text", "b": "Fit the new guibo with new bolts, noting the direction of any arrows or markings. Tighten the bolts evenly in a star pattern per the part sheet."}], "only": ["gonly", "gboth"]}, {"title": "Replace the center support bearing", "blocks": [{"t": "text", "b": "Separate the two halves, remove the snap ring and support plate, and slide the old bearing off. Fit the new one, plate and snap ring. Motoiq''s write-up shows the same sequence for the E36."}, {"t": "text", "b": "Upgraded carrier: cut around the existing bearing, remove the factory brace, and clamp on the new bushings and bracket with threadlocker, per the ECS sheet.", "only": ["csup"]}, {"t": "torque", "label": "Center support carrier bolts", "nm": 25, "c": {"level": "single", "n": 2, "note": "Garagistic: pre-load the bearing first, then tighten to 17.4–20.3 ft-lb."}, "note": "17.4–20.3 ft-lb after pre-loading"}, {"t": "note", "b": "Garagistic says to pre-load the bearing before you torque it. The exact pre-load method isn''t in what we found, so follow the instruction sheet that comes with your bearing or carrier."}], "only": ["csonly", "gboth"]}, {"title": "Refit and test", "blocks": [{"t": "text", "b": "Refit the shaft, tighten the center support last, refit the exhaust and drive. The vibration should be gone. Re-check the bolts after 100 miles."}]}], "alsoReplace": [{"name": "Transmission mount", "why": "Worn mounts change driveshaft angle. See the Bushings & mounts guides."}, {"name": "Driveshaft u-joints or a rebuilt shaft", "why": "Factory u-joints aren''t serviceable. A rebuilt shaft allows future replacement."}, {"name": "Clutch", "why": "If the guibo is out, the clutch is easy to reach."}], "check": {"tab": "Which part?", "title": "Where''s the vibration from?", "illId": "e36-guibo-hero", "illCap": "Three parts in one line.", "rows": [{"see": "Vibration at speed that gets worse with load", "means": "Guibo or center bearing.", "do": "Inspect both."}, {"see": "Clunk on and off throttle", "means": "Guibo, u-joint or diff mount.", "do": "Check the guibo and mounts."}, {"see": "Growl from the middle of the car", "means": "Center support bearing.", "do": "Replace it."}], "c": {"level": "medium", "n": 2, "note": "Common driveline diagnoses."}}, "aftercare": ["Re-check the bolts after 100 miles.", "Listen for any new vibration after a few drives."], "disagreements": [{"topic": "Upgraded center support or OE", "pos": "ECS and JXB say the stock rubber carrier lets the bearing deflect. OE is quieter.", "call": "OE for a daily driver that isn''t abused. Upgraded if the car is driven hard or has failed before."}], "sources": ["Turner Motorsport — E36 M3 guibo, center support and driveshaft parts (part numbers, ECS carrier, Meyle HD)", "Motoiq — E36 guibo and center support bearing write-up", "Garagistic — E36 bolt torque guide (guibo bolts by size and grade, center support 17.4–20.3 ft-lb, driveshaft to flange)", "ECS — E36/E46 flywheel instructions (flex coupler 21 Nm, splined collar 10 Nm)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-short-shifter', '{"id": "e36-short-shifter", "title": "Shifter rebuild, short shifter & DSSR", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Kits shared with other E36 six-cylinders; check the DSSR length for your transmission", "category": "Drivetrain", "kind": "upgrade", "heroId": "e36-shift-hero", "heroCap": "The stock shifter has a carrier with rubber bushings, a selector rod and a lever. Each rubber part adds slop. You can restore it, shorten it or replace the carrier.", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$100–600", "risk": "Parts mixed from different transmissions · a lever that rubs the console", "why": "A sloppy shifter is the first thing most E36 M3 owners fix. Stock rubber bushings and plastic inserts wear and the lever goes vague. A rebuild restores it, a short shifter reduces throw, and a DSSR firms up the linkage.", "note": "Turner''s S52 DSSR is 198 mm. A 109 mm DSSR is for the Getrag 420G swap, so don''t mix them up."}, "lifespan": {"title": "When to expect it", "headline": ["Stock bushings wear with age", "Slop appears as a loose, vague lever"], "earliest": "A lever that wobbles or won''t find a gear cleanly", "detail": "Rubber bushings and plastic inserts soften. A rebuild kit replaces them all.", "factors": ["Age", "Heat", "Hard shifting"], "inspect": ["Wiggle the lever with the engine off and feel for play"], "confidence": {"level": "medium", "n": 2, "note": "Turner describes the same wear."}}, "should": {"yesIf": ["The lever wobbles or feels vague", "You want shorter throws", "You''re replacing the clutch or mounts and the linkage is old"], "codes": [], "notes": ["Do the rebuild before buying a short shifter. A short shifter on worn bushings still feels sloppy."], "confidence": {"level": "medium", "n": 2, "note": "Turner''s guidance."}}, "variants": {"questions": [{"question": "What do you want to do?", "hint": "Each step up costs more and gets more precise.", "options": [{"id": "srebuild", "label": "Rebuild only", "when": "New bushings, pins and boot", "oeOnly": true}, {"id": "sshort", "label": "Short shift kit", "when": "About 30% less throw (Turner kit with ZHP knob)"}, {"id": "schassis", "label": "Chassis-mount shifter + DSSR", "when": "Removes the carrier, shortest throw", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Shifter rebuild kit", "pn": "Turner E36 S52 / S50 (09/1994+) kit", "price": "$80–200", "note": "Bushings, pins, boot and hardware. The S50 up to 09/1995 uses a different kit.", "only": ["srebuild"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-524-bmw-shifter-upgrades-and-components/m-1241-packaged-by-turner?Nrpp=50"}]}, {"tier": "aftermarket", "name": "Ultimate shifter rebuild & upgrade kit", "pn": "Turner E36M396USRKT", "price": "$458.60", "note": "DSSR, poly arm bushing, ECS Teflon oval bushings, washers, boot, pins, ball bushing and hardware.", "only": ["sshort", "srebuild"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-5649941-ultimate-shifter-rebuild-upgrade-kit/"}]}, {"tier": "aftermarket", "name": "Turner short shift kit with ZHP knob", "price": "See Turner", "note": "Reduces throw by about 30%, per Turner.", "only": ["sshort"]}, {"tier": "aftermarket", "name": "Turner chassis-mount short throw shifter + DSSR", "price": "See Turner", "note": "Removes the shift carrier and its three bushing positions. Tall rally-style lever (257 mm).", "only": ["schassis"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-34080716-e36-chassis-mount-short-throw-shifter-with-free-dssr-kit-328m3/"}]}, {"tier": "aftermarket", "name": "Turner DSSR (S52, 198 mm)", "price": "See Turner", "note": "Double-shear selector rod, replaces BMW 25111222738.", "only": ["sshort", "schassis"]}], "aftermarket": [{"name": "Turner Double-Adjustable Short Throw Kit", "note": "Height- and throw-adjustable, up to 52% shorter than stock. Sold with the Getrag 420G swap kit.", "price": "See Turner", "only": ["srebuild", "sshort"]}, {"name": "Turner polyurethane shifter arm carrier bushing", "note": "Removes play caused by a failed rubber bushing.", "price": "See Turner"}], "tools": [{"name": "Socket set, trim tools", "note": "To remove the console and boot", "price": "$30"}, {"name": "Pin punch", "note": "For the dowel pins", "price": "$10"}, {"name": "Grease", "note": "For the new bushings", "price": "$5"}], "before": ["Order the right DSSR for your gearbox.", "Take photos before removing the console.", "Have a clean rag for grease."], "steps": [{"title": "Remove the shift knob, boot and console", "blocks": [{"t": "text", "b": "Take off the shift knob, boot and the console trim around the shifter. Take photos of everything."}, {"t": "ill", "id": "e36-shift-hero", "cap": "Lever, carrier, selector rod. Photograph the layout first."}]}, {"title": "Drop the carrier and selector rod", "blocks": [{"t": "text", "b": "From underneath, disconnect the selector rod at the transmission and unbolt the shifter carrier from the floor. Lower it out."}, {"t": "note", "b": "We searched and found no published torque for the shifter carrier or selector rod hardware. It''s small fasteners, so snug them firmly, use threadlocker only where the kit says, and use the kit''s sheet if it gives a figure. A chassis-mount shifter has its own mounting bolts and travel stops that the maker''s guide covers."}]}, {"title": "Replace the bushings, ball and pins", "blocks": [{"t": "text", "b": "Press out the worn bushings and the ball bushing, fit the new pieces and grease them. Fit new dowel and bearing pins as supplied."}]}, {"title": "Fit the new selector rod (DSSR)", "blocks": [{"t": "text", "b": "Replace the selector rod with the DSSR. It reduces linkage play and replaces BMW 25111222738."}], "only": ["sshort", "schassis"]}, {"title": "Fit the short shifter", "blocks": [{"t": "text", "b": "Follow the kit''s sheet for the lever and fulcrum position. A chassis-mount shifter replaces the carrier completely."}], "only": ["sshort", "schassis"]}, {"title": "Refit and test", "blocks": [{"t": "text", "b": "Reassemble the console and boot. Check every gear with the engine off, then on a short drive. Check the lever doesn''t rub the console."}]}], "alsoReplace": [{"name": "Transmission mount", "why": "A soft mount feels like a loose shifter."}, {"name": "Shift knob and boot", "why": "Cheap and visible."}, {"name": "Guibo", "why": "Driveline slop affects shifting."}], "check": {"tab": "Is it the shifter?", "title": "Shifter diagnosis", "illId": "e36-shift-hero", "illCap": "Slop comes from a few places.", "rows": [{"see": "Lever wobbles with the car off", "means": "Worn bushings or carrier.", "do": "Rebuild."}, {"see": "Lever fine, shifts notchy", "means": "Fluid, clutch or synchros.", "do": "Check fluid and clutch."}, {"see": "Lever moves but gears are hard to find", "means": "Selector rod or ball joint wear.", "do": "Replace the DSSR and bushings."}], "c": {"level": "medium", "n": 2, "note": "Common shifter diagnostics."}}, "aftercare": ["Re-check the bolts after 100 miles.", "Re-grease if it squeaks."], "disagreements": [{"topic": "Rebuild or short shifter first", "pos": "Turner says even a short shifter is at the mercy of soft bushings.", "call": "Rebuild first. Add throw reduction afterwards."}], "sources": ["Turner Motorsport — E36 M3 shifter rebuild, short shift and chassis-mount kits", "Turner Motorsport — DSSR lengths (198 mm S52, 109 mm 420G)", "Garagistic — E36 oval shifter bushing kit (OEM part numbers: oval bushings 25117507695, selector joint 25117580281, front carrier clip 25111221849)", "No published torque found for the shifter carrier or selector hardware"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-trans-diff-fluid', '{"id": "e36-trans-diff-fluid", "title": "Transmission & differential fluid", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Manual E36 M3s; automatics use a different fluid", "category": "Drivetrain", "kind": "repair", "heroId": "e36-fluid-hero", "heroCap": "Each gearbox has a fill plug and a drain plug. Always check you can open the fill plug before you drain anything.", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 1, "cost": "$40–150", "risk": "Draining the fill-plug-less box · wrong fluid in a limited-slip diff", "why": "Old gear oil gets notchy to shift and wears the diff. It''s a plug-out, pump-in job. The one rule is to open the fill plug first.", "note": "Turner says 75W-90 is the weight used in BMW diffs, including the factory clutch-type limited slips. The thick 75W-140 is for newer M-Variable diffs."}, "lifespan": {"title": "When to expect it", "headline": ["Common advice is every 30,000–60,000 miles", "No E36-specific interval found"], "earliest": "Notchy shifts when cold, or a whining diff", "detail": "Interval from general practice, not a factory number. Change it on a car you just bought.", "factors": ["Age", "Track use", "Heat"], "inspect": ["Check fluid color and smell on the drain plug"], "confidence": {"level": "single", "n": 1, "note": "General guidance; no verified BMW interval."}}, "should": {"yesIf": ["You just bought the car and don''t know its history", "Shifts are notchy", "The diff whines or chatters in turns", "You''ve tracked it"], "codes": [], "notes": ["A limited-slip diff can chatter on the wrong fluid. Use 75W-90 unless your diff maker says otherwise. Capacity is about 1.8 US quarts."], "confidence": {"level": "medium", "n": 2, "note": "Turner''s guidance."}}, "variants": {"questions": [{"question": "Which unit?", "hint": "They are separate fluids.", "options": [{"id": "ftrans", "label": "Transmission", "when": "Manual gearbox"}, {"id": "fdiff", "label": "Differential", "when": "Rear end"}, {"id": "fboth", "label": "Both", "when": "Do them together"}]}, {"question": "Genuine or aftermarket fluid?", "hint": "Both are synthetic and well regarded.", "options": [{"id": "foe", "label": "Genuine BMW", "when": "MTF LT-2 and SAF-XO", "oeOnly": true}, {"id": "fam", "label": "Red Line", "when": "MTL or MT-90 and 75W-90"}]}]}, "parts": [{"tier": "oe", "name": "Genuine BMW manual transmission oil MTF LT-2, 1 L", "price": "$20–30", "note": "Turner lists it for the E36 M3. Check the label next to your fill plug.", "only": ["ftrans+foe", "fboth+foe"]}, {"tier": "oe", "name": "Genuine BMW SAF-XO 75W-90 diff fluid", "pn": "07512293972", "price": "$15–25 per liter", "note": "Factory spec for the 75W-90 diff.", "only": ["fdiff+foe", "fboth+foe"]}, {"tier": "aftermarket", "name": "Red Line MTL or MT-90 transmission fluid", "price": "$15–25 per quart", "note": "MTL suits 75W/80W/85W GL-4 specs. MT-90 is the thicker 75W-90.", "only": ["ftrans+fam", "fboth+fam"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-1234-bmw-transmission-and-differential-fluid"}]}, {"tier": "aftermarket", "name": "Red Line 75W-90 differential oil", "price": "$15–25 per quart", "note": "Matches the specification of the factory SAF-XO per Turner.", "only": ["fdiff+fam", "fboth+fam"]}, {"tier": "oe", "name": "New drain and fill plug washers", "price": "$5–10", "note": "Crush washers on each plug."}, {"tier": "aftermarket", "name": "Magnetic diff drain plug (M22 × 1.5)", "price": "$20–90", "note": "Turner sells a titanium one. Optional.", "only": ["fdiff", "fboth"]}], "aftermarket": [{"name": "Red Line MTL / MT-90", "note": "Turner''s best-selling BMW fluids since 1994.", "price": "See Turner"}, {"name": "Royal Purple Synchromax", "note": "For manual boxes that specify ATF-type fluid.", "price": "See retailer", "only": ["ftrans", "fboth"]}], "tools": [{"name": "Socket set and Allen bits", "note": "For the drain and fill plugs", "price": "$30"}, {"name": "Fluid pump", "note": "A hand pump to push gear oil up into the fill hole", "price": "$10–20"}, {"name": "Drain pan", "note": "", "price": "$10"}, {"name": "Jack and four jack stands", "note": "Level ground, car level", "price": "$150+"}], "before": ["Check the colour-coded label near the fill plug.", "Open the fill plug first and make sure you can.", "Level the car on stands."], "steps": [{"title": "Level the car and open the fill plug first", "caution": true, "blocks": [{"t": "text", "b": "Raise the car level on stands. Loosen the fill plug before the drain plug, so you know you can refill."}, {"t": "ill", "id": "e36-fluid-hero", "cap": "Fill plug above, drain plug below. Open the fill plug first."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Drain the unit", "blocks": [{"t": "text", "b": "Put a pan under the drain plug, take it out and let it drain fully. Look at the plug for metal flecks."}, {"t": "torque", "label": "Transmission fill and drain plugs", "nm": 50, "c": {"level": "medium", "n": 3, "note": "Pelican''s forum (from the manual) gives 50 Nm (37 ft-lb), and a torque guide gives 35 Nm (26 ft-lb) for an Allen-head plug."}, "note": "37 ft-lb. Use 35 Nm if it''s an Allen plug", "only": ["ftrans", "fboth"]}, {"t": "torque", "label": "Differential fill and drain plugs", "nm": 56, "c": {"level": "single", "n": 2, "note": "Pelican''s E30/E36 article gives 41 ft-lb. BMW''s later diffs use 60 Nm."}, "note": "about 41–44 ft-lb", "alt": [60], "only": ["fdiff", "fboth"]}, {"t": "note", "b": "Plug sizes: the diff uses 14 mm hex plugs (FCP Euro, UUC). The transmission plug is 17 mm on some boxes and 15 mm on others, so check yours."}]}, {"title": "Refit the drain plug and refill", "blocks": [{"t": "text", "b": "Fit the drain plug with a new washer. Pump fluid in through the fill hole until it just begins to run out of the hole."}, {"t": "text", "b": "Transmission: the Bentley figure, as quoted on Pelican''s forum, is about 1.2 liters (1.3 US quarts). Buy two quarts so you don''t run short. Use the fluid that matches the label near your plug.", "only": ["ftrans", "fboth"]}, {"t": "note", "b": "Which fluid: one source quoting Castrol says a green label with a 17 mm drain plug means MT-90, a red label with a 17 mm plug means D4 ATF, and no label with a 15 mm plug means MTL. Another E36 M3 owner''s guide notes BMW specified ATF for these ZF manual boxes. Turner lists MTF LT-2 for the M3. Follow the label on your box.", "only": ["ftrans", "fboth"]}, {"t": "text", "b": "Differential: it takes about 1.8 US quarts (roughly 1.7 liters). Buy two quarts of 75W-90. Turner says that is the weight for factory clutch-type limited slips.", "only": ["fdiff", "fboth"]}]}, {"title": "Refit the fill plug and check", "blocks": [{"t": "text", "b": "Refit the fill plug with a new washer, lower the car and take a short drive. Check for leaks and that shifts feel smooth."}]}], "alsoReplace": [{"name": "Transmission and diff mounts", "why": "You''re under the car. Check them."}, {"name": "Guibo and center support bearing", "why": "Both are close to the transmission."}], "check": {"tab": "Signs it''s due", "title": "When fluid has had it", "illId": "e36-fluid-hero", "illCap": "Fluid tells you a lot.", "rows": [{"see": "Metal flecks on the plug", "means": "Normal fine paste or wear.", "do": "A little paste is normal; chunks are not."}, {"see": "Burnt smell or dark fluid", "means": "Old fluid.", "do": "Change it."}, {"see": "Notchy shifts when cold", "means": "Old or wrong fluid.", "do": "Change to the correct type."}], "c": {"level": "medium", "n": 2, "note": "General gearbox diagnostics."}}, "aftercare": ["Check for leaks after the first drive.", "Re-check the fluid level after a few days."], "disagreements": [{"topic": "Genuine or Red Line", "pos": "Red Line says its fluids meet or exceed the factory specs. BMW fluids are the approved choice.", "call": "Either is fine. Genuine for a car under warranty-like scrutiny, Red Line for a shifting-feel upgrade."}], "sources": ["Turner Motorsport — E36 M3 transmission and differential fluid (MTF LT-2, SAF-XO, Red Line notes)", "Bimmersport forum thread — E36 gearbox fluid labels and plug sizes", "FCP Euro — E36 differential service (1.8 US quarts for the 323/325/328/M3, 14 mm plugs)", "Pelican Parts — E36 manual transmission and differential fluid articles (Bentley 1.2 L / 1.3 qt transmission, 50 Nm plugs)", "UUC Motorwerks — E36 fluids tech tip (2 quarts of each, plug sizes, loosen the fill plug first)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-battery', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Every E36 has the battery in the trunk, on the right side", "embeds": [], "aftercare": ["Check the terminals for corrosion after a month.", "Keep the vent tube routed away from the car''s interior."], "disagreements": [{"topic": "Group 48 vs Group 47", "pos": "Group 48 (H6) is the common fit, and some owners say H5 is too short for the factory clamp.", "call": "Go with 48/H6 and check the tray length."}], "id": "e36-battery", "title": "Battery replacement (trunk)", "category": "Electrical", "kind": "repair", "heroId": "e36-battery-hero", "heroCap": "The battery sits in a tray on the right side of the trunk, held by a clamp on the negative side, with a vent tube at the positive end.", "glance": {"timeFirst": "30–60 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$150–400", "risk": "Wrong group size · vent tube pointing the wrong way · losing radio presets", "why": "A tired battery shows up first as slow cranking in the cold. The E36 battery is easy to reach in the trunk, but the size matters: some group sizes fit the tray and some don''t.", "note": "Group 48/H6 is the usual fit. Group 47/H5 is shorter and may not clamp properly. Check the length against your tray."}, "lifespan": {"title": "When to expect it", "headline": ["Typically 4–6 years", "Shorter in hot or very cold climates"], "earliest": "Slow cranking, dim lights, or a battery that won''t hold a charge", "detail": "General guidance: a battery that is more than five years old is on borrowed time. A load test at a parts store will tell you.", "factors": ["Age", "Short trips", "Heat", "Parasitic drain"], "inspect": ["Load test the battery", "Check the date code on the case"], "confidence": {"level": "single", "n": 1, "note": "General guidance, not an E36 figure."}}, "should": {"yesIf": ["The car cranks slowly or won''t start", "The battery is over five years old", "A load test fails"], "codes": [], "notes": ["Replace the battery before you chase other electrical gremlins."], "confidence": {"level": "medium", "n": 2, "note": "Common practice."}}, "variants": {"questions": [{"question": "Which battery?", "hint": "Both fit the trunk tray. Optima and Odyssey cost more and last longer if the car sits.", "options": [{"id": "bstd", "label": "Standard flooded", "when": "Group 48/H6, lowest cost", "oeOnly": true}, {"id": "bagm", "label": "AGM upgrade", "when": "Optima H6 or Odyssey 48/H6"}]}]}, "parts": [{"tier": "oe", "name": "Group 48 / H6 battery", "price": "$100–200", "note": "AutoZone lists Group 48/H6 (615 CCA flooded) for the E36 M3. It is about 11 in long, 7.5 in tall and 6 7/8 in wide.", "only": ["bstd"]}, {"tier": "aftermarket", "name": "Optima H6 YellowTop", "pn": "9048-148", "price": "$369.99", "note": "A direct-fit AGM that needs no mount kit. 72 Ah, 800 CCA, and BimmerWorld lists it for the E36 M3.", "only": ["bagm"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Safety-Race-Interior/Battery-Electrical/OPTIMA-H6-BMW-DIN-Direct-Fit-Replacement-Battery.html"}]}, {"tier": "aftermarket", "name": "Odyssey Performance AGM 48/H6", "pn": "ODP-AGM48H6L3", "price": "$300–400", "note": "A Group 48 AGM. Confirm the terminal position and vent before you buy.", "only": ["bagm"]}, {"tier": "oe", "name": "Battery hold-down clamp", "pn": "61217631587", "price": "$10–25", "note": "Replace if rusted or cracked."}, {"tier": "oe", "name": "Battery vent tube", "pn": "61211377745", "price": "$5–15", "note": "Make sure the new battery''s vent is where the old one was, or use a longer tube."}], "aftermarket": [{"name": "Optima H6 YellowTop", "note": "Direct-fit AGM, 800 CCA, good for a car that sits.", "price": "$369.99", "signal": "No mount kit needed"}, {"name": "Odyssey Performance 48/H6", "note": "AGM, high cranking power.", "price": "See retailer"}], "tools": [{"name": "10 mm and 13 mm sockets", "note": "Terminals and clamp", "price": "$20"}, {"name": "Memory saver or a second battery", "note": "To keep the clock and radio memory", "price": "$0–25"}, {"name": "Terminal brush", "note": "", "price": "$5"}], "before": ["Have your radio code ready. Some E36 head units ask for it after power loss.", "Check the new battery''s length against the tray.", "Clean the cable ends."], "steps": [{"title": "Open the trunk and expose the battery", "blocks": [{"t": "text", "b": "Open the trunk, fold back the carpet and remove the plastic cover on the right side. The battery cover is held by a plastic screw and nuts."}, {"t": "ill", "id": "e36-battery-hero", "cap": "Cover off: terminals at the top, clamp on the negative side, vent tube at the positive end."}]}, {"title": "Remove the hold-down and disconnect the cables", "blocks": [{"t": "text", "b": "Remove the clamp by the negative terminal. Pull the black vent tube from the positive end. Disconnect the negative cable first, then the positive, and lift the battery out."}, {"t": "warn", "b": "A battery weighs about 40 lb. Lift with your legs and watch the paint and the trunk lip."}]}, {"title": "Fit the new battery", "blocks": [{"t": "text", "b": "Set the battery in the tray flush to the upper right corner so the cover will fit back over it. Check the vent tube lines up with the new battery''s vent."}, {"t": "text", "b": "Group 47/H5 is about 9 9/16 in long against 11 in for a 48/H6, so a shorter battery may need the clamp adapted.", "only": ["bstd"]}, {"t": "text", "b": "An AGM may sit slightly differently. Check the hold-down grips it and it can''t slide.", "only": ["bagm"]}]}, {"title": "Reconnect and tighten", "blocks": [{"t": "text", "b": "Connect the positive cable first, then the negative. Refit the hold-down clamp, vent tube, cover and carpet."}, {"t": "note", "b": "We found no published terminal torque for the E36. The terminal clamps are small, so snug them firmly without crushing the post."}]}, {"title": "Check and reset", "blocks": [{"t": "text", "b": "Start the car. Reset the clock and radio, and enter the radio code if asked."}]}], "alsoReplace": [{"name": "Battery cables and terminals", "why": "Corroded terminals mimic a dead battery."}, {"name": "Alternator check", "why": "If the new battery dies, test the charging system."}], "check": {"tab": "Dead or something else?", "title": "Is it the battery?", "illId": "e36-battery-hero", "illCap": "Test before you replace.", "rows": [{"see": "Slow crank, lights dim", "means": "Weak battery.", "do": "Load test, then replace."}, {"see": "Battery dies after a day", "means": "Parasitic drain or alternator.", "do": "Test the charging system and draw."}, {"see": "Clicks but won''t crank", "means": "Bad terminals or a dead battery.", "do": "Clean and tighten the terminals."}], "c": {"level": "medium", "n": 2, "note": "Standard battery diagnostics."}}, "sources": ["AutoZone — BMW M3 battery fitment (Group 48/H6, 615 CCA flooded)", "BimmerWorld — Optima H6 for the E36 M3", "BimmerFest — E36 trunk battery change (jumper method, vent tube, ''flush to the corner'')", "Autohausaz — E36 battery hold-down and vent tube part numbers", "ZPost thread — Group 47/H5 vs 48/H6 length", "No published terminal torque found"]}'::jsonb);
insert into guides (id, content) values ('e36-headlight-bulbs', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Euro-style glass ellipsoid headlights use different bulbs than the US housings", "embeds": [], "aftercare": ["Check the aim.", "Wipe fingerprints off the lens."], "disagreements": [{"topic": "LED bulbs in halogen housings", "pos": "They''re widely sold and sometimes scatter light badly.", "call": "Stay with halogen in these housings."}], "id": "e36-headlight-bulbs", "title": "Headlight bulbs", "category": "Electrical", "kind": "repair", "heroId": "e36-bulbs-hero", "heroCap": "Which bulb you need depends on which housing you have. US-spec ellipsoids use two different bulbs per side. Euro glass ellipsoids use H1 for both beams.", "glance": {"timeFirst": "15–30 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$20–80", "risk": "Touching the glass with bare fingers · wrong bulb for your housing", "why": "A burnt-out bulb is an easy fix, and a better bulb is the cheapest lighting upgrade. The only trap is the housing: US cars use 9006 low and 9005 high, while Euro glass lights use H1.", "note": "LED drop-ins in reflector or projector housings aren''t designed for the beam pattern. We don''t recommend them."}, "lifespan": {"title": "When to expect it", "headline": ["Halogen bulbs usually last a few years", "Replace in pairs"], "earliest": "One side going dim or out", "detail": "Halogen bulbs fade slowly. A new pair restores the brightness of both sides.", "factors": ["Age", "Vibration", "Touching the glass"], "inspect": ["Compare brightness left and right at night"], "confidence": {"level": "single", "n": 1, "note": "General guidance."}}, "should": {"yesIf": ["A bulb is out or one side is dimmer", "You want a brighter, whiter halogen"], "codes": [], "notes": ["Replace both sides together."], "confidence": {"level": "medium", "n": 2, "note": "Common practice."}}, "variants": {"questions": [{"question": "Which headlights do you have?", "hint": "US cars have rectangular-looking reflector or ellipsoid units with 9006/9005 bulbs. Euro conversions use glass ellipsoids.", "options": [{"id": "hus", "label": "US housings", "when": "9006 low beam, 9005 high beam", "oeOnly": true}, {"id": "heu", "label": "Euro glass ellipsoids", "when": "H1 low and high, W5W city light"}]}]}, "parts": [{"tier": "oe", "name": "9006 (HB4) low beam bulb, 51 W", "price": "$10–25", "note": "ECS lists Silverstar 9006 for the E36 M3. R3VLimited''s E30 bulb list notes the US ellipsoid low beam is 9006.", "only": ["hus"]}, {"tier": "oe", "name": "9005 (HB3) high beam bulb, 60 W", "price": "$10–25", "note": "Osram Sylvania 9005 and Silver Star Ultra are listed for the E36 M3.", "only": ["hus"]}, {"tier": "oe", "name": "H1 55 W bulbs (low and high)", "price": "$10–25 each", "note": "Euro glass ellipsoids use H1 for both low and high beam.", "only": ["heu"]}, {"tier": "oe", "name": "W5W city light bulb", "price": "$3–8", "note": "Euro glass lights use a W5W parking bulb.", "only": ["heu"]}], "aftermarket": [{"name": "Osram Sylvania Silverstar 9006", "note": "Brighter, whiter halogen replacement.", "price": "See ECS", "signal": "Direct fit for US housings", "only": ["hus"]}, {"name": "Osram Sylvania Silver Star Ultra 9005", "note": "Brighter high beam pair.", "price": "See ECS", "only": ["hus"]}, {"name": "Genuine BMW 9011 HIR", "note": "A 9005 replacement for Euro headlights only, not US housings.", "price": "See retailer", "only": ["heu"]}], "tools": [{"name": "Clean gloves or a rag", "note": "Don''t touch halogen glass with bare fingers", "price": "$2"}, {"name": "Small flathead screwdriver", "note": "For the retaining clip", "price": "$3"}], "before": ["Turn the lights off and let the bulbs cool.", "Buy a pair, not a single bulb.", "Check which housing you have before you order."], "steps": [{"title": "Open the hood and find the bulb", "blocks": [{"t": "text", "b": "Open the hood. The bulb sits at the back of the headlight housing. Remove the rubber or plastic cover if there is one."}, {"t": "ill", "id": "e36-bulbs-hero", "cap": "Low beam and high beam are separate bulbs in the US setup."}]}, {"title": "Unplug and remove the old bulb", "blocks": [{"t": "text", "b": "Pull the connector off the bulb. Release the retaining clip, then pull the bulb straight out."}]}, {"title": "Fit the new bulb", "caution": true, "blocks": [{"t": "text", "b": "Hold the new bulb by its base, not the glass. Slide it in until it seats, relock the clip, and push the connector back on."}, {"t": "warn", "b": "Skin oil on halogen glass shortens its life. If you touch it, wipe it with rubbing alcohol."}]}, {"title": "Test and aim", "blocks": [{"t": "text", "b": "Turn the lights on and check low and high beam. Check the aim against a wall, since a different bulb can shift the pattern slightly."}]}], "alsoReplace": [{"name": "Both bulbs on the pair", "why": "They fade together."}, {"name": "City light and side marker bulbs", "why": "A few dollars while you''re there."}, {"name": "Headlight housings", "why": "If the lenses are yellow or foggy. See the Housings guide."}], "check": {"tab": "Bulb or wiring?", "title": "Bulb, fuse or connector?", "illId": "e36-bulbs-hero", "illCap": "Check the simple things first.", "rows": [{"see": "One side out", "means": "Bulb.", "do": "Replace both."}, {"see": "Both low beams out", "means": "Fuse or relay.", "do": "Check the fuses."}, {"see": "Melted or brown connector", "means": "High resistance.", "do": "Replace the connector."}], "c": {"level": "medium", "n": 2, "note": "Standard lighting diagnosis."}}, "sources": ["ECS — E36 M3 S52 headlight bulbs (9006 Silverstar, 9005 Silver Star Ultra, 9011 HIR for Euro lights)", "R3VLimited — bulb list (US ellipsoid 9006/9005; Euro ellipsoids H1; city W5W)", "Turner Motorsport — E36 bulbs"]}'::jsonb);
insert into guides (id, content) values ('e36-window-regulator', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Sedans have different regulators from the coupe and convertible", "embeds": [], "aftercare": ["Check the window travels smoothly after a few cycles.", "Keep the door panel clips intact."], "disagreements": [{"topic": "Rivets or bolts", "pos": "Factory rivets are fast. Bolts make later repairs simpler.", "call": "Use bolts."}, {"topic": "Number of airbag bolts", "pos": "Red Eye Garage and Doug''s Domain say four 10 mm bolts. A coupe DIY says three.", "call": "Count them on your door before you start."}], "id": "e36-window-regulator", "title": "Window regulator & motor", "category": "Electrical", "kind": "repair", "heroId": "e36-regulator-hero", "heroCap": "The regulator is riveted into the door. A snapped slider clip drops the glass, and a dead motor stops it moving at all.", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$60–300", "risk": "Side airbag in the door · drilling rivets in the wrong place · broken slider clips", "why": "A window that drops or won''t move is the E36''s classic door failure. Often it''s only a broken slider clip or a worn motor, so check before you replace the whole regulator.", "note": "The door has a side airbag. Disconnect the battery and wait before you touch it."}, "lifespan": {"title": "When to expect it", "headline": ["No interval", "Sliders and motors fail with age"], "earliest": "A window that drops, slants or makes a grinding noise", "detail": "Plastic slider clips are the cheapest and most common failure. The motor and regulator wear next.", "factors": ["Age", "Heavy glass", "Cold weather"], "inspect": ["Listen for a grind or a click"], "confidence": {"level": "medium", "n": 2, "note": "Bav Auto, Pelican and Doug''s Domain agree."}}, "should": {"yesIf": ["The window falls at one end", "It grinds or won''t move", "The motor hums but the glass doesn''t move"], "codes": [], "notes": ["Check the slider clips first. They''re a $5 part."], "confidence": {"level": "medium", "n": 3, "note": "Bav Auto and Pelican say the same."}}, "variants": {"questions": [{"question": "Which door?", "hint": "The coupe and convertible have long front doors with two slides. Sedans are different.", "options": [{"id": "rcoupe", "label": "Coupe or convertible", "when": "Two regulator slides"}, {"id": "rsedan", "label": "Sedan", "when": "Different regulators front and rear"}]}, {"question": "What are you replacing?", "hint": "Clips are cheap. Replace the motor with the regulator if both are old.", "options": [{"id": "rclips", "label": "Slider clips only", "when": "Window drops at one end", "oeOnly": true}, {"id": "rreg", "label": "Regulator and motor", "when": "Dead window or worn assembly"}]}]}, "parts": [{"tier": "oe", "name": "Window slider clips (2 per window)", "pn": "51-32-1-938-884 (per Pelican)", "price": "$5–15", "note": "Buy extras. Doug''s Domain bought two spares in case he broke one."}, {"tier": "oe", "name": "Window regulator (and motor)", "price": "$60–200", "note": "Coupe, convertible and sedan parts differ. Confirm by door.", "only": ["rreg"]}, {"tier": "oe", "name": "Door panel clips", "price": "$5–15", "note": "Replace any that break. See the Door panels guide."}, {"tier": "aftermarket", "name": "M6 bolts, washers and nuts, or rivnuts", "price": "$5–15", "note": "Red Eye Garage replaced the rivets with stainless M6 bolts, washers and nuts. That makes future repairs simple.", "only": ["rreg"]}], "aftermarket": [{"name": "M6 stainless bolts instead of rivets", "note": "Red Eye Garage and Pelican both say to use bolts so the next repair doesn''t need drilling.", "price": "$5–15", "only": ["rreg"]}], "tools": [{"name": "Torx bits (T25, T30)", "note": "Door panel and motor screws. Pelican says T15 on some panels, so check yours", "price": "$10"}, {"name": "Drill and bits, or a chisel", "note": "To remove the rivets", "price": "$20"}, {"name": "Nylon trim tools", "note": "", "price": "$10"}, {"name": "5 mm Allen key and a 10 mm socket", "note": "Pivot bar bolt and airbag bolts", "price": "$10"}], "before": ["Disconnect the battery and wait about 15 minutes.", "Buy spare clips.", "Have a plan to hold the glass up while you work, such as tape over the top."], "steps": [{"title": "Disconnect the battery and remove the door panel", "caution": true, "blocks": [{"t": "warn", "b": "Disconnect the battery and wait about 15 minutes before touching any airbag. Keep tools and your body out of line with the module."}, {"t": "text", "b": "Remove the door panel as described in the Door panels guide. It includes the hidden screws near the handle and behind the airbag badge."}, {"t": "ill", "id": "e36-regulator-hero", "cap": "Regulator, motor, slider clips, and the pivot bar bolt at the rear of the door."}]}, {"title": "Remove the vapor barrier and airbag", "caution": true, "blocks": [{"t": "text", "b": "Peel back the vapor barrier carefully. Unplug the yellow airbag connector, pulling it straight out without turning it. Remove the 10 mm bolts holding the airbag (sources say three or four, so count yours) and set it somewhere safe."}, {"t": "warn", "b": "Don''t put anything between you and the airbag when you disconnect it, and don''t store it face up where it could be struck."}]}, {"title": "Check and replace the slider clips", "blocks": [{"t": "text", "b": "Tape the glass up if it has dropped. The regulator arms attach to the glass rail through plastic sliders held by small spring clips. Pull the clips with pliers and fit new sliders and clips."}], "only": ["rclips"]}, {"title": "Drill out the rivets and free the regulator", "timeSink": true, "blocks": [{"t": "text", "b": "The regulator is riveted to the door frame. Drill or chisel the rivets out (about four of them). Remove the 5 mm Allen bolt holding the pivot bar at the rear of the door. Disconnect the motor and airbag wiring from the regulator."}, {"t": "text", "b": "Take the regulator out through the large opening. It can need some aggressive tugging and may break sliders, which is why you bought spares."}], "only": ["rreg"]}, {"title": "Fit the new regulator and motor", "blocks": [{"t": "text", "b": "Move the motor to the new regulator if it''s good (three T30 Torx screws). Fit the new regulator, and use M6 stainless bolts, washers and nuts, or rivnuts, instead of rivets. Refit the pivot bar bolt."}, {"t": "note", "b": "We found no published torque for these small M6 fasteners. Snug them with threadlocker, not hard enough to distort the door frame."}], "only": ["rreg"]}, {"title": "Test before you close up", "blocks": [{"t": "text", "b": "Reconnect the battery briefly with the airbag still unplugged and out of the way, or leave it disconnected and test the window with the switch. Then reconnect the airbag and refit the door panel."}]}], "alsoReplace": [{"name": "Door panel clips", "why": "They break on removal."}, {"name": "Motor", "why": "If the regulator is old, the motor is usually too."}, {"name": "Vapor barrier tape", "why": "A new butyl strip to reseal the barrier."}], "check": {"tab": "Clips, motor or regulator?", "title": "What failed?", "illId": "e36-regulator-hero", "illCap": "Listen before you take the door apart.", "rows": [{"see": "Window drops at one end", "means": "Broken slider clip.", "do": "Replace the clips."}, {"see": "Motor hums, glass doesn''t move", "means": "Regulator binding or stripped parts.", "do": "Replace the regulator."}, {"see": "No sound at all", "means": "Switch, fuse or motor.", "do": "Check those first."}], "c": {"level": "medium", "n": 2, "note": "Bav Auto and Pelican diagnosis."}}, "sources": ["Red Eye Garage — Project E36 M3: replacing the window motor and regulator (airbag, M6 bolts)", "Doug''s Domain — E36 power window DIY (sliders, pivot bar, airbag bolts)", "Pelican Parts — E30/E36 window regulator and motor (rivets, 5 mm Allen bolt, clip part number)", "Bav Auto — E36 window guide clips", "FCP Euro — E36 front window regulator and motor"]}'::jsonb);
insert into guides (id, content) values ('e36-catback', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Most M3 systems also fit 325/328 with hanger changes; check sedan fitment", "embeds": [], "aftercare": ["Re-check clamps after a week.", "Check tip alignment."], "disagreements": [{"topic": "Supersprint price vs value", "pos": "Supersprint costs more. Turner says nothing matches its quality and reputation.", "call": "Supersprint if budget allows; Turner for value."}], "id": "e36-catback", "title": "Cat-back & axle-back exhaust", "category": "Engine", "kind": "upgrade", "heroId": "e36-catback-hero", "heroCap": "A cat-back replaces everything behind Section 1. An axle-back replaces only the rear muffler. Most E36 M3 systems connect to the stock cat section.", "glance": {"timeFirst": "1–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$450–1,800", "risk": "Rusty clamps · hanger alignment · drone", "why": "A cat-back is mostly about sound and a few pounds. Pick by tone, volume and budget. Gains are small.", "note": "Turner''s cat-back fits M3 and replica M3 rear bumpers. Check fitment for a sedan."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Stock mufflers rust out"], "earliest": "Rusty or blowing muffler", "detail": "Stock steel mufflers rust over time.", "factors": ["Rust", "Short trips"], "inspect": ["Check for rust holes"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["You want a better sound", "The stock muffler is rusted"], "codes": [], "notes": ["Listen to clips of each before you buy. Drone is personal."], "confidence": {"level": "medium", "n": 2, "note": "General."}}, "variants": {"questions": [{"question": "Which exhaust?", "hint": "All connect to the stock cat section.", "options": [{"id": "coe", "label": "OE replacement", "when": "Eberspaecher rear muffler", "oeOnly": true}, {"id": "cturner", "label": "Turner cat-back or valved axle-back", "when": "Dual 2.5 in, or 3 in valved", "brand": true}, {"id": "csuper", "label": "Supersprint", "when": "US Sport or Racing muffler", "brand": true}, {"id": "cother", "label": "Another brand", "when": "Corsa, Rogue Engineering and others"}]}]}, "parts": [{"tier": "oe", "name": "Eberspaecher rear muffler", "pn": "18101737491", "price": "$445.99", "note": "OE-style replacement.", "only": ["coe"]}, {"tier": "aftermarket", "name": "Turner performance cat-back", "pn": "023466LA01-01", "price": "$624.74–734.99", "note": "Mandrel-bent dual 2.5 in 304 stainless with an integrated X-pipe, 22 lb, keeps factory emissions and hangers.", "only": ["cturner"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-14651254-e36-m3-performance-axleback-exhaust/"}]}, {"tier": "aftermarket", "name": "Turner valved axle-back", "pn": "023494LA01KT", "price": "$1,002.10", "note": "Full 3 in valved muffler with remote control. Slight hanger change on non-M cars.", "only": ["cturner"]}, {"tier": "aftermarket", "name": "Supersprint US Sport muffler", "pn": "784426", "price": "$1,332–1,510", "note": "76 mm dual round tips, T304. Connects to the stock cat section.", "only": ["csuper"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-351182-e36-m3-us-supersprint-performance-muffler/"}]}, {"tier": "aftermarket", "name": "Supersprint US Racing muffler", "pn": "042806", "price": "$1,138.99", "note": "Louder racing version, dual 70 mm tips.", "only": ["csuper"]}, {"tier": "aftermarket", "name": "Turner/Corsa sport exhaust or Rogue DMS", "pn": "COR14553X · DMS-E36-US", "price": "$725–1,780", "note": "Corsa connects to the stock cat section with 3 in tips. Rogue Engineering DMS is $724.99.", "only": ["cother"]}, {"tier": "oe", "name": "Clamps, gaskets and hanger rubbers", "price": "$20–60", "note": "Replace rusty clamps and tired hangers."}], "aftermarket": [{"name": "Turner performance cat-back", "note": "Deep tone, keeps factory emissions.", "price": "$624.74", "signal": "Best value"}, {"name": "Supersprint US Sport", "note": "Behaves like a stock-replacement sport exhaust per Turner.", "price": "See Turner"}, {"name": "Corsa (Turner/Corsa)", "note": "Straight-through RSC muffler.", "price": "See Turner"}, {"name": "Rogue Engineering DMS", "note": "Budget-friendly.", "price": "$724.99"}], "tools": [{"name": "Socket set and penetrating oil", "note": "", "price": "$30"}, {"name": "Hanger removal tool or pry bar", "note": "", "price": "$15"}, {"name": "Cutting tool", "note": "If the old clamp won''t come off", "price": "$0–40"}], "before": ["Soak the clamps.", "Check that the kit includes clamps and gaskets.", "Check sedan fitment."], "steps": [{"title": "What you get", "blocks": [{"t": "text", "b": "Mostly sound and weight. We found no independently measured E36 M3 power figures for these cat-backs. Turner quotes a 22 lb system weight for its cat-back."}]}, {"title": "Remove the old exhaust", "blocks": [{"t": "text", "b": "Raise the car and support the exhaust. Undo the clamp or flange where the rear section meets Section 1, pop the hangers off and lower it."}, {"t": "ill", "id": "e36-catback-hero", "cap": "Cat-back starts after Section 1. Axle-back is the rear muffler only."}]}, {"title": "Fit the new system", "blocks": [{"t": "text", "b": "Hang the new system on its hangers, loosely clamp the joints, and line up the tips with the bumper."}, {"t": "note", "b": "We found no published E36 clamp torque. Tighten band clamps evenly after the system is aligned and the tips sit straight."}]}, {"title": "Valved exhaust: fit the controller", "blocks": [{"t": "text", "b": "Install the valve controller per the Turner kit and test both positions."}], "only": ["cturner"]}, {"title": "Check and drive", "blocks": [{"t": "text", "b": "Start the engine and check for leaks and contact. Re-check the clamps after a drive."}]}], "alsoReplace": [{"name": "Exhaust hangers", "why": "They sag with age."}, {"name": "Section 1 gaskets", "why": "If the joint leaks."}], "check": {"tab": "Leak or rattle?", "title": "After the install", "illId": "e36-catback-hero", "illCap": "Most noises are fit.", "rows": [{"see": "Rattle under the car", "means": "Contact with the body.", "do": "Re-align the hangers."}, {"see": "Ticking", "means": "Leak at the joint.", "do": "Re-tighten the clamp."}, {"see": "Drone", "means": "Character of the system.", "do": "Try a different muffler."}], "c": {"level": "medium", "n": 2, "note": "Typical exhaust issues."}}, "sources": ["Turner — E36 cat-back and axle-back systems (Turner, Corsa, Supersprint, Rogue, Eberspaecher)", "Turner — Supersprint US Sport and Racing mufflers"]}'::jsonb);
insert into guides (id, content) values ('e36-headers', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "US S52 headers differ from Euro and 1995 S50 headers", "embeds": [], "aftercare": ["Re-check the nuts after a few heat cycles.", "Check for codes."], "disagreements": [{"topic": "Street or race", "pos": "Race headers make more power but need special software and aren''t street legal in many places.", "call": "Street car: the OBD-II Supersprint. Race car: either."}], "id": "e36-headers", "title": "Headers", "category": "Engine", "kind": "upgrade", "heroId": "e36-headers-hero", "heroCap": "Headers replace the cast manifolds. The US S52 has secondary air injection and O2 sensors that a header has to account for.", "glance": {"timeFirst": "4–7 hr", "timeRepeat": "3 hr", "difficulty": 4, "cost": "$800–2,000", "risk": "Broken manifold studs · emissions legality · O2 sensor and secondary air fitment", "why": "Headers matter most on a car that''s already tuned. On the US M3, only a header built for OBD-II with the secondary air injection is street-friendly. Several popular headers are race only.", "note": "Supersprint''s Euro headers are for track use with special software, OBD-I conversion or standalone engine management, per Turner. Active Autowerke''s header is designed for off-road racing."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Stock cast manifolds can crack"], "earliest": "A cracked manifold ticks or leaks", "detail": "Manifolds crack with heat cycles. The studs rust.", "factors": ["Heat cycles", "Rust"], "inspect": ["Listen for a tick at cold start"], "confidence": {"level": "single", "n": 1, "note": "Pelican''s note on cracked manifolds."}}, "should": {"yesIf": ["You''re on a Stage 3–4 tuning path", "A stock manifold is cracked", "The car is a track car"], "codes": [], "notes": ["Check your local emissions rules before buying."], "confidence": {"level": "medium", "n": 2, "note": "Turner and Supersprint listings."}}, "variants": {"questions": [{"question": "Which header?", "hint": "Street legality and fitment differ a lot.", "options": [{"id": "hss", "label": "Supersprint Tubolare (OBD-II)", "when": "With secondary air injection, 1996–99", "brand": true}, {"id": "haa", "label": "Active Autowerke header", "when": "Race (off-road) design", "brand": true}, {"id": "hrace", "label": "Supersprint Euro Tubolare", "when": "Race only, needs special software", "brand": true}]}]}, "parts": [{"tier": "aftermarket", "name": "Supersprint Tubolare headers with OBD-II secondary air", "price": "See Turner", "note": "Connects to the stock cat section (with modification) or the Supersprint center resonator. T304 stainless.", "only": ["hss"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/c-46-bmw-headers/m-663-supersprint"}]}, {"tier": "aftermarket", "name": "Active Autowerke E36 M3 performance header", "pn": "AA-ExhHE36M-G3", "price": "$788", "note": "Polished 304 stainless. Bolts to AA''s Track Pipe Section B. Designed for race use (off road).", "only": ["haa"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Exhaust/Headers/Active-Autowerke-BMW-E36-M3-Performance-Header.html"}]}, {"tier": "aftermarket", "name": "Supersprint Euro Tubolare headers", "pn": "784301KT", "price": "See Turner", "note": "Equal length, mandrel bent, O2 bung in each bank. Racing or track only with special software or OBD-I. May need the secondary air ports blocked.", "only": ["hrace"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-388606-m3-supersprint-euro-tubolare-headers-upgrade-for-us-cars/"}]}, {"tier": "oe", "name": "Exhaust manifold studs and nuts", "pn": "Studs M7 × 42 (11121744057), nuts 11721437202 · Turner kit TEN3649SK1KT", "price": "$40–120", "note": "Replace rusty studs and use new nuts."}, {"tier": "oe", "name": "Manifold gaskets and flange nuts", "pn": "Copper flange nut 11621744323 (M8 × 1.25)", "price": "$20–60", "note": "New gaskets every time."}], "aftermarket": [{"name": "Supersprint", "note": "Italian, hand-made stainless. The OBD-II version is the street-friendly choice.", "price": "See Turner"}, {"name": "Active Autowerke", "note": "Race header, pairs with their Track Pipe and Race exhaust.", "price": "$788"}], "tools": [{"name": "Penetrating oil, socket set, swivel joints", "note": "Manifold nuts are hard to reach", "price": "$40"}, {"name": "O2 sensor socket", "note": "For moving the sensors", "price": "$10"}, {"name": "Torque wrench", "note": "Low range", "price": "$40"}], "before": ["Soak the manifold nuts in penetrating oil for days.", "Buy the stud kit in case a stud snaps.", "Check the header''s legality where you live."], "steps": [{"title": "What you get", "blocks": [{"t": "text", "b": "We found no independently measured E36 M3 gains for these headers. Active Autowerke shows a dyno sheet from its own Mustang dyno without a published number, and Supersprint doesn''t give an S52 figure. Headers matter most on a car that is already tuned through Stage 3 or 4."}, {"t": "warn", "b": "Removing or modifying catalytic converters or emissions parts on a street car is illegal in the US under federal law, and fails inspection in many states. Parts sold for off-road use only are exactly that."}]}, {"title": "Remove the exhaust down to the manifolds", "blocks": [{"t": "text", "b": "Raise the car securely. Unplug and remove the O2 sensors. Drop Section 1 from the manifolds and support it."}, {"t": "ill", "id": "e36-headers-hero", "cap": "Two manifolds, six primaries, O2 sensors and the secondary air ports."}]}, {"title": "Remove the manifolds", "caution": true, "blocks": [{"t": "text", "b": "Remove the manifold nuts. If a stud snaps, replace it with the stud kit."}, {"t": "warn", "b": "Exhaust studs break easily. Use penetrating oil, heat and patience."}]}, {"title": "Fit the header", "blocks": [{"t": "text", "b": "Fit new gaskets and the header, and run the nuts down evenly."}, {"t": "torque", "label": "Exhaust manifold nuts (M7)", "nm": 20, "c": {"level": "medium", "n": 2, "note": "The Bentley figure quoted on R3VLimited is 20 Nm. Another E36 reference gives 15 Nm for M7 and 20 Nm for M8."}, "note": "copper nuts, even pattern"}, {"t": "text", "b": "Secondary air: the OBD-II Supersprint keeps the ports. Race headers may need them blocked.", "only": ["hss", "hrace"]}]}, {"title": "Refit sensors and Section 1", "blocks": [{"t": "text", "b": "Refit the O2 sensors with anti-seize on the threads. Bolt Section 1 back on with new copper flange nuts."}, {"t": "torque", "label": "O2 sensors", "nm": 45, "c": {"level": "medium", "n": 2, "note": "Same value as our E36 O2 sensor guide."}, "note": "anti-seize on threads"}, {"t": "note", "b": "Header-to-Section 1 flange nuts: we found about 24 Nm (18 ft-lb) quoted on the E30 Zone forum and no verified E36 figure. Use the header maker''s sheet if it gives one."}]}, {"title": "Check for leaks", "blocks": [{"t": "text", "b": "Start the engine and listen for ticking at each joint. Re-check the nuts after a few heat cycles."}]}], "alsoReplace": [{"name": "O2 sensors", "why": "Old sensors don''t like being moved."}, {"name": "Section 1 gaskets", "why": "Always new."}], "check": {"tab": "Leaks?", "title": "After the install", "illId": "e36-headers-hero", "illCap": "Ticking means a leak.", "rows": [{"see": "Tick at cold start", "means": "Manifold or flange leak.", "do": "Re-torque after a heat cycle."}, {"see": "Check engine light", "means": "O2 sensor or secondary air.", "do": "Check the plugs and ports."}, {"see": "Rattle", "means": "Heat shield.", "do": "Secure it."}], "c": {"level": "medium", "n": 2, "note": "Typical header issues."}}, "sources": ["Turner Motorsport — Supersprint E36 M3 headers (OBD-II, Euro race only)", "BimmerWorld — Active Autowerke E36 M3 header", "Turner — head-to-manifold stud and nut kit", "R3VLimited — Bentley torque values (manifold nuts 20 Nm)", "E30 Zone — flange nut torque discussion"]}'::jsonb);
insert into guides (id, content) values ('e36-intake', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Most of these also list the E36 323i/328i; check the M3-specific version (HFM adapter, ASC)", "embeds": [], "aftercare": ["Check clamps after 100 miles.", "Clean the filter on schedule."], "disagreements": [{"topic": "How much an intake really adds", "pos": "aFe claims up to 20 whp. One owner says 5–8 bhp on a non-M car. Dinan''s +12 hp is at the crank and with its software.", "call": "Buy an intake for sound and response. Treat power claims as optimistic."}], "id": "e36-intake", "title": "Performance air intake", "category": "Engine", "kind": "upgrade", "heroId": "e36-intake-hero", "heroCap": "An aftermarket intake replaces the airbox and inlet with a larger filter, usually moved toward cooler air behind the bumper. The HFM (air flow meter) stays in the path.", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 1, "cost": "$300–700", "risk": "Unmetered air leaks after the HFM · an oiled filter fouling the HFM · overstated gains", "why": "An intake is the classic first mod: more sound, sharper throttle, a small gain. The published gains are maker claims, measured in different ways, so treat them as relative, not as promises.", "note": "A bigger 3.5 in HFM belongs to the tuning path (Stage 2). This guide keeps the stock HFM."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Clean or replace the filter on its schedule"], "earliest": "When you want the sound and response", "detail": "Filters need service: oiled filters get cleaned and lightly re-oiled, dry filters get replaced or washed per the maker.", "factors": ["Dusty roads"], "inspect": ["Inspect the filter at every oil change"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["You want more intake sound and response", "The stock airbox is cracked", "You''re planning a tune and want the supporting intake"], "codes": [], "notes": ["On its own the gain is small. One E36 owner measured about 5–8 bhp from an intake on a non-M car, well under the maker''s claim."], "confidence": {"level": "medium", "n": 3, "note": "Maker pages and owner reports."}}, "variants": {"questions": [{"question": "Which intake?", "hint": "All are bolt-on. They differ in filter type, material and where the filter sits.", "options": [{"id": "idinan", "label": "Dinan carbon fiber", "when": "D760-0321B, filter behind the bumper", "brand": true}, {"id": "iafe", "label": "aFe Magnum FORCE Stage-2", "when": "Dry (51-12392) or oiled (54-12392)", "brand": true}, {"id": "iturner", "label": "Turner performance carbon", "when": "Aluminum airbox, carbon cover", "brand": true}, {"id": "iother", "label": "Another intake", "when": "Injen and others"}]}]}, "parts": [{"tier": "aftermarket", "name": "Dinan carbon fiber cold air intake", "pn": "D760-0321B", "price": "$420–500", "note": "Fits 1996–99 M3. Dinan quotes +12 hp and +11 lb-ft at 6,000 rpm with its software.", "only": ["idinan"], "links": [{"store": "ECS", "url": "https://www.ecstuning.com/BMW-E36-M3-S52_3.2L/Performance/Engine_-or-_Drivetrain/Intake_Systems/"}]}, {"tier": "aftermarket", "name": "aFe Magnum FORCE Stage-2 intake", "pn": "51-12392 (dry) · 54-12392 (oiled)", "price": "$340–400", "note": "Fits US and Euro HFMs with an adapter. aFe claims up to 20 whp and 25 lb-ft, and 80% more flow than stock.", "only": ["iafe"], "links": [{"store": "Redline360", "url": "https://shop.redline360.com/products/afe-magnum-force-stage-2-cold-air-intake-bmw-m3-e36-us-spec-92-99-oiled-or-dry-filter"}]}, {"tier": "aftermarket", "name": "Turner performance carbon intake system", "pn": "043602LA11", "price": "$400–600", "note": "Aluminum airbox, carbon fiber cover, silicone couplers and a Turner oiled cone filter. Choose the OBD2 version and whether you have ASC.", "only": ["iturner"]}, {"tier": "aftermarket", "name": "Aftermarket intake of your choice", "pn": "Injen SP1105BLK and others", "price": "$200–500", "note": "Check it''s made for the S52 HFM.", "only": ["iother"]}, {"tier": "oe", "name": "Intake boot and clamps", "price": "$20–80", "note": "If the old boot is cracked. A cracked boot after the HFM causes lean codes. See the Intake boot guide."}], "aftermarket": [{"name": "Dinan D760-0321B", "note": "Re-released carbon fiber version; filter relocated below the headlight behind the bumper.", "price": "See ECS"}, {"name": "aFe Magnum FORCE Stage-2", "note": "Dry or oiled filter, rotomolded tube.", "price": "See retailer"}, {"name": "Turner carbon intake", "note": "Designed and tested on E36s by Turner.", "price": "See Turner"}, {"name": "Injen SP1105BLK", "note": "Black intake with heat shield and cover.", "price": "See ECS"}, {"name": "aFe throttle body spacer", "note": "aFe claims +4 hp and +8 lb-ft measured on an E36 M3. A small add-on.", "price": "See Turner"}], "tools": [{"name": "Screwdrivers and sockets", "note": "For the airbox and clamps", "price": "$20"}, {"name": "Torx bits", "note": "HFM screws on some setups", "price": "$10"}], "before": ["Check the boot after the HFM for cracks before you start.", "Have the right version for ASC or no ASC.", "Unplug the HFM before you remove it."], "steps": [{"title": "What you get", "blocks": [{"t": "chart", "title": "Maker-quoted gains over stock", "unit": "hp", "baseline": "Stock", "bars": [{"label": "Dinan (with software)", "v": 12, "note": "crank, at 6,000 rpm"}, {"label": "aFe Stage-2 (claim)", "v": 20, "note": "wheel, aFe''s figure"}, {"label": "Owner report, non-M", "v": 6, "note": "5–8 bhp, one owner"}], "source": "Dinan and aFe product pages; BimmerFest owner thread", "c": {"level": "single", "n": 3, "note": "These are claims measured different ways: crank vs wheel, with and without software. Compare them as relative, not exact."}}, {"t": "text", "b": "Expect a big change in sound and throttle feel, and a small change in power. The biggest claimed numbers come from the maker''s own dyno."}]}, {"title": "Remove the stock airbox", "blocks": [{"t": "text", "b": "Unplug the HFM connector and release the clamp on the boot. Unclip the airbox lid and remove the airbox and inlet."}, {"t": "ill", "id": "e36-intake-hero", "cap": "Airbox and filter come out. The HFM stays, then the boot to the throttle body."}]}, {"title": "Fit the new intake", "blocks": [{"t": "text", "b": "Fit the new tube or airbox and the HFM adapter if the kit has one. Mount the filter where the kit says and tighten all clamps."}, {"t": "note", "b": "We found no published torque for intake clamps. Snug them evenly. Over-tightening cuts the silicone."}]}, {"title": "Check for leaks and the HFM", "caution": true, "blocks": [{"t": "text", "b": "Check every joint after the HFM. Any leak there lets in unmetered air, which runs the engine lean."}, {"t": "text", "b": "Oiled filters: oil them lightly. Excess oil can coat the HFM wire and upset readings.", "only": ["iafe", "iturner", "iother"]}]}, {"title": "Test drive", "blocks": [{"t": "text", "b": "Start the car and check it idles smoothly with no check engine light. Then drive and listen for whistles from leaks."}]}], "alsoReplace": [{"name": "Intake boot", "why": "A cracked boot causes lean codes."}, {"name": "Tune", "why": "Most gains assume software. See the Tuning path guide."}], "check": {"tab": "Running right?", "title": "After the install", "illId": "e36-intake-hero", "illCap": "A few checks.", "rows": [{"see": "Check engine light, lean codes", "means": "Air leak after the HFM.", "do": "Check every joint and the boot."}, {"see": "Rough idle", "means": "Leak or HFM damage.", "do": "Inspect and clean."}, {"see": "Whistling", "means": "A loose clamp.", "do": "Tighten it."}], "c": {"level": "medium", "n": 2, "note": "Typical intake issues."}}, "sources": ["Dinan — E36 carbon fiber cold air intake D760-0321B release", "Redline360 — aFe Magnum FORCE Stage-2 for the E36 M3 (claims, filter part numbers)", "ECS and Turner — E36 M3 intake listings (Turner carbon, Injen)", "BimmerFest — aFe intake owner thread (5–8 bhp report)", "Turner — aFe throttle body spacer listing"]}'::jsonb);
insert into guides (id, content) values ('e36-section1', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "US S52 Section 1 differs from the Euro and 1995 S50 layout", "embeds": [], "aftercare": ["Re-check the flanges after a few heat cycles."], "disagreements": [{"topic": "Cats or no cats", "pos": "Removing cats frees flow. It''s illegal on the street.", "call": "High-flow cats for a street car."}], "id": "e36-section1", "title": "Section 1 (cat section)", "category": "Engine", "kind": "upgrade", "heroId": "e36-section1-hero", "heroCap": "Section 1 runs from the manifolds back. On the US M3 it holds both catalytic converters and a resonator, plus the post-cat O2 sensors.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$500–2,500", "risk": "Emissions law · O2 sensor codes · leaks at the flanges", "why": "Section 1 is where the cats live, and on a stock car it''s also part of what limits flow. The street-friendly upgrade is high-flow cats. Removing the cats is a track-only choice.", "note": "Removing or modifying catalytic converters or emissions parts on a street car is illegal in the US under federal law, and fails inspection in many states. Parts sold for off-road use only are exactly that."}, "lifespan": {"title": "When to expect it", "headline": ["Cats last a long time", "Can fail after misfires or oil burning"], "earliest": "Rattling cats, a P0420 code or a failed emissions test", "detail": "Misfires and oil consumption damage cats.", "factors": ["Misfires", "Oil burning", "Age"], "inspect": ["Check for rattles and cat efficiency codes"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["Cats are failing or rattling", "You''re building the exhaust for a tuned car"], "codes": [], "notes": ["Choose a legal option for a street car."], "confidence": {"level": "medium", "n": 2, "note": "Retailer listings."}}, "variants": {"questions": [{"question": "What are you fitting?", "hint": "For a street car, choose cats.", "options": [{"id": "soe", "label": "OE replacement", "when": "Stock-style cats", "oeOnly": true}, {"id": "shf", "label": "Supersprint high-flow cats", "when": "US midpipe with 200-cell cats"}, {"id": "strack", "label": "Track pipe", "when": "No cats, off-road use only", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "OE-style Section 1 with cats", "price": "$600–1,500", "note": "Like-for-like replacement. Emissions legal.", "only": ["soe"]}, {"tier": "aftermarket", "name": "Supersprint US midpipe with 200-cell catalytic converters", "pn": "043402", "price": "$2,296.99", "note": "For E36 325/328/M3, part of Supersprint''s US system.", "only": ["shf"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-589358-supersprint-us-spec-performance-exhaust-system-e36-328-m3/"}]}, {"tier": "aftermarket", "name": "Active Autowerke Track Pipe", "price": "See AA", "note": "Off-road racing only. Turner''s discontinued Stage 5 package used an AA Track Pipe with software set to ignore the post-cat O2 sensors.", "only": ["strack"]}, {"tier": "oe", "name": "Flange gaskets and copper nuts", "pn": "11621744323 (M8 × 1.25 copper nut)", "price": "$20–40", "note": "New every time."}], "aftermarket": [{"name": "Supersprint 200-cell cats", "note": "High-flow cats that keep the car closer to legal.", "price": "See Turner"}], "tools": [{"name": "O2 sensor socket", "note": "", "price": "$10"}, {"name": "Penetrating oil and sockets", "note": "", "price": "$30"}, {"name": "Transmission jack or helper", "note": "Section 1 is heavy", "price": "$0–80"}], "before": ["Check your local emissions rules.", "Soak the flange nuts.", "Have new gaskets and nuts."], "steps": [{"title": "What you get", "blocks": [{"t": "text", "b": "We found no independently measured S52 gains for Section 1 changes. High-flow cats reduce restriction while keeping cats. A track pipe removes them entirely and is for off-road use only."}, {"t": "warn", "b": "Removing or modifying catalytic converters or emissions parts on a street car is illegal in the US under federal law, and fails inspection in many states. Parts sold for off-road use only are exactly that."}]}, {"title": "Unplug the O2 sensors", "blocks": [{"t": "text", "b": "Raise the car. Unplug and remove the O2 sensors in Section 1."}, {"t": "ill", "id": "e36-section1-hero", "cap": "Two cats and the resonator in Section 1, with O2 sensors before and after the cats."}]}, {"title": "Drop Section 1", "blocks": [{"t": "text", "b": "Support the section. Undo the front flanges at the manifolds and the rear joint to Section 2, then the hangers, and lower it out."}]}, {"title": "Fit the new section", "blocks": [{"t": "text", "b": "Fit new gaskets and the new section, hang it on its hangers, then snug the flanges evenly."}, {"t": "note", "b": "Flange nuts: no verified E36 figure found. An E30 Zone post gives about 24 Nm (18 ft-lb). Use the maker''s sheet if it gives one."}]}, {"title": "Refit the O2 sensors and check", "blocks": [{"t": "text", "b": "Refit the sensors with anti-seize."}, {"t": "torque", "label": "O2 sensors", "nm": 45, "c": {"level": "medium", "n": 2, "note": "Same value as our E36 O2 sensor guide."}}, {"t": "text", "b": "Track pipe: post-cat O2 codes will set unless your software handles them. Turner''s Stage 5 software was written to ignore the post-cat sensors.", "only": ["strack"]}]}], "alsoReplace": [{"name": "O2 sensors", "why": "If they''re old."}, {"name": "Exhaust hangers", "why": "Old rubber sags."}], "check": {"tab": "Codes?", "title": "After the install", "illId": "e36-section1-hero", "illCap": "O2 codes are the usual problem.", "rows": [{"see": "P0420/P0430", "means": "Cat efficiency.", "do": "Check cats and post-cat sensors."}, {"see": "Ticking", "means": "Flange leak.", "do": "Re-torque."}, {"see": "Rattle", "means": "Loose heat shield or broken cat.", "do": "Inspect."}], "c": {"level": "medium", "n": 2, "note": "Typical exhaust issues."}}, "sources": ["Turner — Supersprint US system and US midpipe with 200-cell cats", "Turner — Stage 5 package (AA Track Pipe, post-cat O2 software)", "E30 Zone — flange torque discussion"]}'::jsonb);
insert into guides (id, content) values ('e36-tuning-path', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Shark Injector files are North American spec only; the 1995 S50 uses chips, not this path", "embeds": [], "aftercare": ["Use 91+ octane.", "Keep the original software backup."], "disagreements": [{"topic": "Stock manifold or M50", "pos": "The M50 manifold makes more top end, and some torque is lost lower down. Turner recommends the stock manifold to keep torque.", "call": "Street car: stock manifold. Track car: M50 with matching software."}], "id": "e36-tuning-path", "title": "Tuning path: software, HFM, cams and manifold", "category": "Engine", "kind": "upgrade", "heroId": "e36-tune-hero", "heroCap": "E36 M3 tuning is a staged path. Each stage adds parts, and each needs software written for exactly those parts.", "glance": {"timeFirst": "Stage 1: 30 min · Stage 3: a weekend", "timeRepeat": "—", "difficulty": 3, "cost": "$300–3,000+", "risk": "Software that doesn''t match your parts · the wrong HFM for the file · octane", "why": "The S52 responds to a planned path more than a pile of parts. Stage 1 is software only. Stage 2 adds a bigger HFM and injectors, Stage 3 adds cams, and the M50 manifold trades low-end torque for top end. Each step needs software made for it.", "note": "Shark Injector''s Stage 2 file is written only for the Porsche 809 3.5 in HFM (0 280 217 809). Turner says it won''t work with a Euro, 540 or Dinan HFM."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item"], "earliest": "When you''ve done the bolt-ons and want more", "detail": "Software is reversible. Hard parts aren''t easy to undo.", "factors": [], "inspect": ["Make sure the car is healthy first: no leaks, good plugs and coils"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["You want more power in a planned way", "You''ve done the intake and want it tuned", "You run 91+ octane"], "codes": [], "notes": ["Stage 1 software also raises the rev limit to 7,000 rpm and removes the top speed limiter, per Turner."], "confidence": {"level": "medium", "n": 3, "note": "Turner, ECS and Dinan listings agree."}}, "variants": {"questions": [{"question": "Which stage?", "hint": "Each stage includes the one before it.", "options": [{"id": "t1", "label": "Stage 1: software only", "when": "Shark Injector or Dinan Stage 1"}, {"id": "t2", "label": "Stage 2: 3.5 in HFM and injectors", "when": "Porsche 809 HFM, 24 lb injectors, intake"}, {"id": "t3", "label": "Stage 3: plus cams", "when": "Schrick cams; stock or M50 manifold"}]}]}, "chapters": [{"id": "tplan", "title": "Plan", "blurb": "What each stage needs and gives."}, {"id": "tdo", "title": "Do it", "blurb": "Hardware first, software last."}, {"id": "tcheck", "title": "Check", "blurb": "Confirm it runs right."}], "parts": [{"tier": "aftermarket", "name": "Shark Injector Stage 1 software", "pn": "N3MS41 · N3MS41E (with EWS delete)", "price": "$314.10", "note": "Turner lists the M3 at +12 hp at 6,000 rpm and +10 lb-ft at 4,000 rpm, a 7,000 rpm limit, and 91+ octane. Plugs into the diagnostic port under the hood.", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-338928-e36-323328m3-shark-injector-stage-1-performance-software/"}], "only": ["t1"]}, {"tier": "aftermarket", "name": "Dinan Stage 1 software", "pn": "D900-32M", "price": "See ECS", "note": "ECS lists max gains of +10 hp and +10 lb-ft. The car is dropped off at ECS''s Ohio facility for flashing.", "only": ["t1"]}, {"tier": "aftermarket", "name": "Porsche 809 3.5 in HFM", "pn": "0 280 217 809", "price": "$300–600", "note": "The Stage 2 file is written for this HFM only. A Turner 3.5 in boot keeps the stock ASC.", "only": ["t2", "t3"]}, {"tier": "aftermarket", "name": "24 lb fuel injectors (set of 6)", "price": "$300–600", "note": "Part of the Stage 2 package.", "only": ["t2", "t3"]}, {"tier": "aftermarket", "name": "Shark Injector Stage 2 software", "pn": "N3TKIT", "price": "$314+", "note": "For the HFM, injectors and intake.", "only": ["t2"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-340363-e36-m3-shark-injector-stage-2-performance-software-hfm-kit/"}]}, {"tier": "aftermarket", "name": "Schrick camshafts", "price": "$1,000–1,800", "note": "Stage 3. Turner''s Stage 5 package used 264/256 degree Schricks.", "only": ["t3"]}, {"tier": "aftermarket", "name": "Shark Injector Stage 3 software", "pn": "N3TCAM (stock S52 manifold) · Stage 3+ (M50 manifold)", "price": "$314+", "note": "Turner recommends the stock manifold to keep the most usable torque.", "only": ["t3"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-340360-e36-m3-shark-injector-stage-3-performance-software-hfmcam-kit/"}]}, {"tier": "aftermarket", "name": "Dinan Stage 3 software", "pn": "D903-32M2T", "price": "See ECS", "note": "ECS lists max gains of +31 hp and +26 lb-ft. Drop-off at ECS''s Ohio facility.", "only": ["t3"]}], "aftermarket": [{"name": "Shark Injector (Conforti)", "note": "Hand-held flash; no laptop, just a battery charger during the flash.", "price": "$314.10"}, {"name": "Dinan software", "note": "Flashed at ECS''s facility.", "price": "See ECS"}, {"name": "BimmerWorld M50 manifold adapter kit", "note": "For the Stage 3+ path.", "price": "See BimmerWorld", "only": ["t3"]}], "tools": [{"name": "Battery charger", "note": "Keeps voltage steady while flashing", "price": "$40–80"}, {"name": "Socket set and Torx bits", "note": "HFM and injectors", "price": "$30"}, {"name": "Cam tools and a shop manual", "note": "Stage 3: cam timing on the VANOS engine", "price": "$100+ or a shop"}], "before": ["Fix any leaks, misfires or codes first.", "Only buy the file that matches your exact parts.", "Use 91+ octane after flashing."], "steps": [{"chapter": "tplan", "title": "What you get", "blocks": [{"t": "chart", "title": "Quoted gains by stage", "unit": "hp", "baseline": "Stock", "bars": [{"label": "Shark Stage 1", "v": 12, "note": "Turner dyno, at 6,000 rpm"}, {"label": "Dinan Stage 1", "v": 10, "note": "ECS listing"}, {"label": "Stage 2 kit (claim)", "v": 30, "note": "about 30 whp, Conforti via owner review"}, {"label": "Dinan Stage 3", "v": 31, "note": "ECS listing"}], "source": "Turner, ECS and an owner review quoting Jim Conforti", "c": {"level": "single", "n": 4, "note": "Seller and tuner figures, crank and wheel mixed. Use them to compare stages, not as guarantees."}}, {"t": "text", "b": "Stage 1 is software alone. Each stage after that adds hardware, and the software must match it."}]}, {"chapter": "tplan", "title": "Match software to hardware", "caution": true, "blocks": [{"t": "text", "b": "Shark Injector Stage 2 is written for the Porsche 809 HFM only. Stage 3 is written for the stock S52 manifold, with Stage 3+ for the M50 manifold. Stage 4 adds headers."}, {"t": "warn", "b": "Running software that doesn''t match your hardware can lean the engine out. Buy the file for the parts you actually have."}]}, {"chapter": "tdo", "title": "Fit the HFM and injectors", "blocks": [{"t": "text", "b": "Install the 3.5 in HFM with its boot and the 24 lb injectors. Disconnect the battery first, keep the injector O-rings lubricated, and check for fuel leaks before starting."}], "only": ["t2", "t3"]}, {"chapter": "tdo", "title": "Fit the cams (or have a shop do it)", "caution": true, "blocks": [{"t": "text", "b": "Cam installation on the VANOS S52 needs the correct timing tools. If you aren''t experienced, have a shop do this step."}, {"t": "note", "b": "We don''t cover the full cam timing procedure here. Use the shop manual or the cam maker''s instructions."}], "only": ["t3"]}, {"chapter": "tdo", "title": "Flash the software", "blocks": [{"t": "text", "b": "Connect a battery charger. Plug the Shark Injector into the diagnostic port under the hood and follow the on-screen steps. Don''t open doors or switch anything on during the flash."}, {"t": "text", "b": "Dinan software is flashed at ECS''s facility: book a drop-off."}]}, {"chapter": "tcheck", "title": "Check and drive", "blocks": [{"t": "text", "b": "Start the car, check for codes, and drive gently at first. Fill with 91+ octane."}, {"t": "text", "b": "Keep the Shark Injector. It can return the car to stock software."}]}], "alsoReplace": [{"name": "Spark plugs and coils", "why": "Fresh ignition makes the tune work properly."}, {"name": "Intake boot", "why": "No leaks after the HFM."}], "check": {"tab": "Running right?", "title": "Post-tune checks", "illId": "e36-tune-hero", "illCap": "Watch for these.", "rows": [{"see": "Check engine light", "means": "Mismatched hardware or a leak.", "do": "Check parts against the file."}, {"see": "Hesitation", "means": "Wrong HFM or injectors for the file.", "do": "Confirm part numbers."}, {"see": "Knocking", "means": "Low octane.", "do": "Use 91+."}], "c": {"level": "medium", "n": 2, "note": "Common post-tune issues."}}, "sources": ["Turner Motorsport — Shark Injector Stage 1, 2, 3 and 3+ listings (gains, HFM rule, manifold advice)", "ECS — Dinan Stage 1 and Stage 3 for the E36 M3", "BimmerWorld — Conforti Stage 3 (M52) and M50 manifold adapter", "BimmerFest — Turner Euro Stage II review (about 30 whp claim)", "Turner — Stage 5 package (now discontinued) for cam spec"]}'::jsonb);
insert into guides (id, content) values ('e36-headlight-housings', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Euro glass ellipsoids and the US units mount in the same openings", "embeds": [], "aftercare": ["Re-aim after a week.", "Check the adapter connections."], "disagreements": [{"topic": "Legality of Euro housings", "pos": "Sellers market them as direct fit. Rules differ by region.", "call": "Check your local rules."}], "id": "e36-headlight-housings", "title": "Headlight housings & Euro conversion", "category": "Exterior", "kind": "upgrade", "heroId": "e36-housing-hero", "heroCap": "Hazy plastic lenses cut the light. Glass Euro ellipsoids are the popular fix and use H1 bulbs, a W5W city light and a wiring adapter.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–800", "risk": "Wiring adapter fit · aiming · illegal headlights if the housing isn''t DOT approved in your area", "why": "US housings yellow and haze over the years. Glass Euro ellipsoids with a projector cutoff give a better beam, and a wiring adapter lets them plug in.", "note": "Check your local rules. Euro-spec lights may not be street legal everywhere."}, "lifespan": {"title": "When to expect it", "headline": ["Plastic lenses haze and yellow with age", "Glass ones don''t"], "earliest": "Foggy, yellow or cracked lenses and weak output", "detail": "UV and heat dull the plastic. The beam gets weaker over the years.", "factors": ["Age", "UV exposure", "Stone chips"], "inspect": ["Compare the lens to a clean one"], "confidence": {"level": "single", "n": 1, "note": "General description."}}, "should": {"yesIf": ["The lenses are hazy or cracked", "You want a better beam pattern", "You''re doing a Euro-style conversion"], "codes": [], "notes": ["Do the aiming after the swap."], "confidence": {"level": "medium", "n": 2, "note": "Retailer and owner descriptions agree."}}, "variants": {"questions": [{"question": "Which route?", "hint": "Glass Euro housings are a bolt-in with a wiring adapter.", "options": [{"id": "gus", "label": "Replace like-for-like (US)", "when": "Same plastic US unit", "oeOnly": true}, {"id": "geu", "label": "Euro glass ellipsoid conversion", "when": "H1 bulbs, W5W city light"}]}]}, "parts": [{"tier": "oe", "name": "US headlight housing (each)", "price": "$80–250", "note": "A like-for-like replacement.", "only": ["gus"]}, {"tier": "aftermarket", "name": "Depo / Hella-style Euro glass ellipsoid headlights (pair)", "price": "$250–700", "note": "Kits are sold with special 9005/9006 wiring adapters and a Euro-to-US connector, and need H1 bulbs and W5W city lights.", "only": ["geu"], "links": [{"store": "Unique Style Racing", "url": "https://www.uniquestyleracingstore.com/products/depo-1992-1999-bmw-e36-3-series-yellow-high-clear-low-glass-lens-hella-euro-ellipsoid-projector-headlight-hlb3e36dphelalhd2c2y"}]}, {"tier": "oe", "name": "H1 bulbs and W5W city bulbs", "price": "$15–40", "note": "See the Headlight bulbs guide.", "only": ["geu"]}], "aftermarket": [{"name": "Euro glass ellipsoid kits", "note": "Hella-style ''nipple'' projectors give a clean cutoff.", "price": "See retailer", "signal": "The popular upgrade"}], "tools": [{"name": "Socket set and screwdrivers", "note": "", "price": "$30"}, {"name": "A wall and tape for aiming", "note": "", "price": "$5"}], "before": ["Check local rules for Euro-spec lights.", "Make sure the kit includes the wiring adapter.", "Have bulbs ready."], "steps": [{"title": "Open the hood and remove the bumper bits that block the housing", "blocks": [{"t": "text", "b": "Open the hood and remove the front trim or turn-signal pieces that block the housing. Take photos."}, {"t": "ill", "id": "e36-housing-hero", "cap": "Housing in the front corner, held by bolts and clips."}]}, {"title": "Unbolt and remove the old housing", "blocks": [{"t": "text", "b": "Unplug the bulb connectors and take the retaining bolts out. Slide the housing forward and out."}]}, {"title": "Fit the new housing and wiring adapter", "blocks": [{"t": "text", "b": "Fit the new housing and connect the wiring adapter between the US connectors and the Euro bulbs. Use the right bulb in each position."}, {"t": "note", "b": "We found no published torque for the housing fasteners. They''re small, so snug them without cracking the plastic."}], "only": ["geu"]}, {"title": "Fit the replacement housing", "blocks": [{"t": "text", "b": "Fit the new housing and plug in the connectors."}], "only": ["gus"]}, {"title": "Aim the headlights", "caution": true, "blocks": [{"t": "text", "b": "Park the car square to a wall on level ground. Aim the low beam cutoff using the adjusters, and check it again at night."}]}], "alsoReplace": [{"name": "Bulbs", "why": "Fresh pair with new housings."}, {"name": "Turn signal and marker lenses", "why": "Matched condition."}], "check": {"tab": "Housing or bulb?", "title": "Do you need new housings?", "illId": "e36-housing-hero", "illCap": "A cloudy lens is a clue.", "rows": [{"see": "Cloudy or yellow lens", "means": "Weathered plastic.", "do": "Replace the housing."}, {"see": "Water inside", "means": "Failed seal.", "do": "Replace the housing."}, {"see": "Dim but clear", "means": "Old bulbs.", "do": "Replace the bulbs."}], "c": {"level": "medium", "n": 2, "note": "General diagnosis."}}, "sources": ["Unique Style Racing — Euro glass ellipsoid headlights for the E36 (H1, W5W, wiring adapters)", "R3VLimited — bulb list (Euro ellipsoid H1, W5W)", "No published torque found"]}'::jsonb);
insert into guides (id, content) values ('e36-hood-trunk-struts', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Coupe and convertible share a hood strut; sedan hoods use a different one", "embeds": [], "aftercare": ["Check the clips are locked."], "disagreements": [{"topic": "OE or cheap struts", "pos": "Stabilus is the OE maker. Unbranded ones are cheaper.", "call": "Stabilus is inexpensive enough to just buy."}], "id": "e36-hood-trunk-struts", "title": "Hood & trunk gas struts", "category": "Exterior", "kind": "repair", "heroId": "e36-struts-hero", "heroCap": "Gas struts hold the hood and trunk up. When they weaken, the lid drops.", "glance": {"timeFirst": "10–20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$30–150", "risk": "A lid falling on you · wrong strut for your body style", "why": "Weak struts let the hood fall while you work. They''re a ten-minute swap, and you replace them as pairs.", "note": "Hood struts are different on sedans. Trunk struts fit sedan and coupe. A heavy spoiler needs a stronger trunk strut."}, "lifespan": {"title": "When to expect it", "headline": ["Gas struts lose pressure over years", "No fixed interval"], "earliest": "A lid that won''t stay up or drifts down", "detail": "Seals leak gas slowly.", "factors": ["Age", "Cold weather", "Extra weight like a spoiler"], "inspect": ["Does the lid hold open?"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["The hood or trunk won''t stay up"], "codes": [], "notes": ["Replace in pairs."], "confidence": {"level": "medium", "n": 2, "note": "Common practice."}}, "variants": {"questions": [{"question": "Which body style?", "hint": "Hood struts differ for the sedan. Trunk struts are shared by sedan and coupe.", "options": [{"id": "scoupe", "label": "Coupe or convertible", "when": "Hood strut 51238119558"}, {"id": "ssedan", "label": "Sedan", "when": "Hood strut 51231960852"}]}]}, "parts": [{"tier": "oe", "name": "Hood strut, coupe/convertible (2 per car)", "pn": "51238119558", "price": "$20–50 each", "note": "Stabilus. Left and right.", "only": ["scoupe"], "links": [{"store": "ECS", "url": "https://www.ecstuning.com/BMW-E36-M3-S52_3.2L/Exterior/Body/Hood/Strut/"}]}, {"tier": "oe", "name": "Hood strut, sedan (2 per car)", "pn": "51231960852", "price": "$20–50 each", "note": "Stabilus or genuine BMW.", "only": ["ssedan"]}, {"tier": "oe", "name": "Trunk gas strut (2 per car)", "pn": "51241960862", "price": "$20–50 each", "note": "Stabilus, for sedan and coupe models."}, {"tier": "aftermarket", "name": "Heavy-spoiler trunk strut (610 N)", "pn": "51242264448", "price": "$60–120 pair", "note": "Only for cars with a heavy aftermarket wing, not the standard spoiler.", "links": [{"store": "M Sport Parts", "url": "https://www.msportparts.com/products/e36-trunk-gas-pressurized-strut-610n-51242264448-pair"}]}], "aftermarket": [{"name": "Stabilus hood and trunk strut kit", "note": "All four struts in one box.", "price": "See ECS or Turner"}, {"name": "610 N heavy-spoiler struts", "note": "For Class II wings.", "price": "See M Sport Parts"}], "tools": [{"name": "Small flathead screwdriver", "note": "To lift the retaining clips", "price": "$3"}, {"name": "A prop for the lid", "note": "A stick or a helper", "price": "$0"}], "before": ["Prop the lid up securely before you remove a strut.", "Replace both sides.", "Check the body style."], "steps": [{"title": "Prop the lid up", "blocks": [{"t": "text", "b": "Open the hood or trunk and hold it up with a stick or a helper. Never rely on the old struts."}, {"t": "ill", "id": "e36-struts-hero", "cap": "A strut at each side. Each end clips onto a ball stud."}]}, {"title": "Release and remove the old strut", "blocks": [{"t": "text", "b": "Lift the small spring clip at each end with a screwdriver and pull the strut off its ball stud."}]}, {"title": "Fit the new strut", "blocks": [{"t": "text", "b": "Push each end onto its ball stud until the clip locks. Fit the strut with the rod end the right way up per the old one, then do the other side."}]}, {"title": "Check", "blocks": [{"t": "text", "b": "Remove the prop and check the lid holds open firmly."}]}], "alsoReplace": [{"name": "Both sides", "why": "They age together."}], "check": {"tab": "Are they weak?", "title": "Test the struts", "illId": "e36-struts-hero", "illCap": "A quick hold test.", "rows": [{"see": "Lid slowly drops", "means": "Weak struts.", "do": "Replace both."}, {"see": "Lid holds but is stiff", "means": "Fine.", "do": "Nothing."}, {"see": "Lid slams up", "means": "Wrong pressure for the weight.", "do": "Check the part number."}], "c": {"level": "medium", "n": 2, "note": "Standard strut check."}}, "sources": ["ECS — E36 M3 S52 hood struts (51238119558, 51231960852, 51241960862)", "Turner Motorsport — E36 hood and trunk struts (coupe vs sedan)", "M Sport Parts — 610 N trunk strut for Class II wings"]}'::jsonb);
insert into guides (id, content) values ('e36-supercharger', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "1996–99 S52 kits differ from 1995 S50 kits; US spec only for VF", "embeds": [], "aftercare": ["Check the belt regularly.", "Check boost and temperatures.", "Follow the kit''s service intervals."], "disagreements": [{"topic": "Intercooled or not", "pos": "AA Level 2 and 3 add an intercooler. VF''s 6 psi kit is not intercooled and claims similar power.", "call": "Intercooled for track or hot climates."}], "id": "e36-supercharger", "title": "Supercharger kit", "category": "Forced induction", "kind": "upgrade", "heroId": "e36-sc-hero", "heroCap": "Both kits bolt a centrifugal supercharger to the front of the engine, driven by the belt, with bigger injectors and new software. Higher levels add an intercooler and a bigger fuel pump.", "glance": {"timeFirst": "2–4 days", "timeRepeat": "—", "difficulty": 5, "cost": "$5,000–14,000+", "risk": "Clutch and cooling limits · tuning · off-road-only waivers · automatic transmissions", "why": "A supercharger is the biggest single power step on an E36 M3. Active Autowerke''s Rotrex kits run from about 360 hp to around 400 whp, and VF Engineering''s Vortech kit claims 350 hp at 6 psi.", "note": "Active Autowerke requires an off-road-use-only waiver before it ships. VF''s kit is for North American spec cars only."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "The supercharger and belt need service"], "earliest": "When the engine and chassis are ready for more power", "detail": "Plan the clutch, cooling and brakes as part of the job.", "factors": ["Engine health", "Cooling", "Clutch"], "inspect": ["Compression and leak-down test before you buy"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["The engine is healthy (compression test)", "You''ve done cooling, clutch and brakes", "You accept that it''s not street-legal everywhere"], "codes": [], "notes": ["Active Autowerke''s kits list automatic transmissions with a premature transmission wear warning."], "confidence": {"level": "medium", "n": 3, "note": "AA and VF product listings."}}, "variants": {"questions": [{"question": "Which kit?", "hint": "AA Level 1 is non-intercooled; Levels 2 and 3 add an intercooler and fuel pump.", "options": [{"id": "aa1", "label": "Active Autowerke Level 1", "when": "Rotrex C38, about 360 hp", "brand": true}, {"id": "aa2", "label": "Active Autowerke Level 2", "when": "C38-81, intercooler, fuel pump", "brand": true}, {"id": "aa3", "label": "Active Autowerke Level 3", "when": "C38-92, about 400 whp", "brand": true}, {"id": "vf", "label": "VF Engineering VF350", "when": "Vortech, 6 psi, about 350 hp", "brand": true}]}]}, "chapters": [{"id": "scplan", "title": "Plan", "blurb": "What you get and what the car needs first."}, {"id": "scfit", "title": "Install", "blurb": "Bracket, blower, plumbing, fuel."}, {"id": "sctune", "title": "Tune & test", "blurb": "Software, checks, first drives."}], "parts": [{"tier": "aftermarket", "name": "Active Autowerke Level 1 (OBD2)", "pn": "12-003", "price": "$8,074–8,499", "note": "Rotrex C38, bracket, pulleys and belt, 6 larger injectors, AA filter and dyno-tuned software. AA lists 360 bhp at 6,900 rpm, 300 lb-ft and 7.0 psi.", "only": ["aa1"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-340092-active-autowerke-supercharger-kit-rotrex-e36-m3/"}]}, {"tier": "aftermarket", "name": "Active Autowerke Level 2 (OBD2)", "pn": "12-004", "price": "$11,019–11,599", "note": "Rotrex C38-81, front-mount air-to-air intercooler and a high-flow fuel pump. Over 400 hp at the crank, about 350 whp, 25–50 hp more than Level 1.", "only": ["aa2"]}, {"tier": "aftermarket", "name": "Active Autowerke Level 3", "pn": "12-005", "price": "$14,125", "note": "Rotrex C38-92, larger intake pipes, and it removes the traction control to make space. AA claims about 400 hp at the wheels, 35–50 more than Level 2.", "only": ["aa3"], "links": [{"store": "Active Autowerke", "url": "https://store.activeautowerke.com/products/active-autowerke-bmw-e36-m3-supercharger-kit-level-3-rotrex-c38-blower"}]}, {"tier": "aftermarket", "name": "VF Engineering VF350 (S52)", "pn": "VFK28-01", "price": "$4,995", "note": "Vortech supercharger at about 6 psi, VF software (7,000 rpm, top speed governor removed), high-flow injectors, colder NGK plugs, bypass valve, K&N filter. VF lists 350 hp and 295 lb-ft against stock 240/236.", "only": ["vf"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-371024-vf-engineering-supercharger-kit-350hp-295-ft-lbs-torque/"}]}, {"tier": "aftermarket", "name": "Clutch rated for the power", "price": "$450–1,500", "note": "See the Clutch guide. SPEC''s Stage 2 is rated 370 ft-lb."}, {"tier": "oe", "name": "Cooling refresh", "price": "$300–1,000", "note": "See the Cooling system guide. Do this first."}], "aftermarket": [{"name": "Active Autowerke Rotrex kits", "note": "Three levels from 7 psi non-intercooled to about 400 whp.", "price": "See AA"}, {"name": "VF Engineering Vortech kit", "note": "Lower cost, non-intercooled, 6 psi.", "price": "$4,995"}, {"name": "Turbo kits", "note": "We couldn''t confirm a currently shipping complete E36 M3 turbo kit to cover. Piecemeal turbo builds are outside this guide.", "price": "—"}], "tools": [{"name": "Full metric tool set, torque wrench", "note": "", "price": "$200+"}, {"name": "Fuel-safe work area and a fire extinguisher", "note": "", "price": "$40"}, {"name": "Laptop or flasher as the kit requires", "note": "", "price": "Varies"}], "before": ["Compression and leak-down test the engine.", "Refresh the cooling system and clutch first.", "Sign AA''s off-road waiver if buying AA."], "steps": [{"chapter": "scplan", "title": "What you get", "blocks": [{"t": "chart", "title": "Quoted power by kit", "unit": "hp", "baseline": "Stock S52", "bars": [{"label": "Stock S52", "v": 240, "note": "crank, factory rating"}, {"label": "VF350", "v": 350, "note": "crank, VF figure, 6 psi"}, {"label": "AA Level 1", "v": 360, "note": "crank, AA figure, 7 psi"}, {"label": "AA Level 2", "v": 400, "note": "crank ''over 400'', AA figure"}], "source": "VF Engineering and Active Autowerke listings", "c": {"level": "single", "n": 2, "note": "Maker figures. AA also quotes about 350 whp for Level 2 and about 400 whp for Level 3."}}, {"t": "text", "b": "All figures are maker claims, not independent tests."}]}, {"chapter": "scplan", "title": "Prepare the car", "caution": true, "blocks": [{"t": "text", "b": "Do a compression or leak-down test, refresh the cooling system, and plan the clutch. Run the right octane."}, {"t": "warn", "b": "Forced induction on a tired engine is the fastest way to destroy it."}]}, {"chapter": "scfit", "title": "Install the bracket and blower", "blocks": [{"t": "text", "b": "Follow the kit instructions for the bracket, pulleys and belt. Check the belt routing against the kit''s diagram."}, {"t": "ill", "id": "e36-sc-hero", "cap": "Blower at the front of the engine, intake and charge pipes, bypass valve and (on AA Level 2/3) an intercooler."}]}, {"chapter": "scfit", "title": "Fit fuel and plumbing", "blocks": [{"t": "text", "b": "Fit the larger injectors, charge pipes, intercooler and fuel pump where the kit includes them. Check every hose clamp."}, {"t": "note", "b": "We don''t give kit torques here. Use the kit''s own instructions."}]}, {"chapter": "sctune", "title": "Flash the software", "blocks": [{"t": "text", "b": "Install the kit software before you drive. Never run boost on stock software."}]}, {"chapter": "sctune", "title": "Check and break in", "blocks": [{"t": "text", "b": "Check for leaks and codes, check the boost gauge if fitted, and start with gentle drives. Watch coolant and oil temperatures."}]}], "alsoReplace": [{"name": "Clutch", "why": "Stock clutches slip at these levels."}, {"name": "Cooling system", "why": "More heat."}, {"name": "Brakes", "why": "More speed."}, {"name": "Spark plugs one step colder", "why": "VF includes them in its kit."}], "check": {"tab": "Running right?", "title": "After installation", "illId": "e36-sc-hero", "illCap": "Watch carefully.", "rows": [{"see": "Belt squeal", "means": "Belt tension or slippage.", "do": "Check the tensioner."}, {"see": "Knock or hesitation", "means": "Fuel or software problem.", "do": "Stop and check."}, {"see": "Overheating", "means": "Cooling not up to it.", "do": "Upgrade cooling."}], "c": {"level": "medium", "n": 2, "note": "Common FI issues."}}, "sources": ["Active Autowerke and Turner — E36 M3 Rotrex supercharger kit Levels 1–3", "VF Engineering via Turner and Vivid Racing — VF350 kit (VFK28-01)", "SPEC Clutches — Stage 2 rating"]}'::jsonb);
insert into guides (id, content) values ('e36-door-panels', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Sedan, coupe and convertible panels all have hidden screws, and 1997+ doors hold a side airbag", "embeds": [], "aftercare": ["Close the door gently and check for rattles."], "disagreements": [{"topic": "Screw type", "pos": "Pelican says T15. Others say T30. FCP says the inner handle is T25.", "call": "Test fit the bit before you turn it, since sizes vary by year and trim."}], "id": "e36-door-panels", "title": "Door panel removal & clips", "category": "Interior", "kind": "repair", "heroId": "e36-panel-hero", "heroCap": "The panel is held by screws hidden near the handle and behind the airbag badge, plus clips around the edge. The upper panel often warps.", "glance": {"timeFirst": "30–60 min", "timeRepeat": "20 min", "difficulty": 2, "cost": "$10–60", "risk": "Broken panel clips · the side airbag · scratching the panel", "why": "You''ll need the door panel off to fix a window, replace speakers or repair the lock. It''s easy once you know where the hidden screws are, and the panels are fragile.", "note": "Red Eye Garage says the airbag badge hides a mounting screw. Pelican says E36 door panels are fragile and clips often need replacing."}, "lifespan": {"title": "When to expect it", "headline": ["Clips age and break", "Upper panels warp over the years"], "earliest": "Rattling, sagging or a warped panel", "detail": "Plastic clips get brittle and the vapor barrier glue dries out.", "factors": ["Age", "Heat"], "inspect": ["Press the panel edge and listen for rattles"], "confidence": {"level": "single", "n": 1, "note": "Pelican''s note on fragile panels."}}, "should": {"yesIf": ["You need access to the regulator, speaker or lock", "The panel rattles or sags"], "codes": [], "notes": ["Buy spare clips first."], "confidence": {"level": "medium", "n": 2, "note": "Pelican and Red Eye Garage agree."}}, "parts": [{"tier": "oe", "name": "Door panel clips", "price": "$5–15", "note": "Buy a bag. Pelican says to have spare clips and a door panel tool."}, {"tier": "oe", "name": "Butyl vapor barrier sealant", "price": "$8–15", "note": "To reseal the barrier."}], "aftermarket": [], "tools": [{"name": "Torx bits", "note": "T30 is common; Pelican says T15 on some. FCP says the inner handle is T25", "price": "$10"}, {"name": "Nylon trim tools or a plastic spatula", "note": "To pop the clips and trim", "price": "$10"}], "before": ["Disconnect the battery if the door has a side airbag (1997 and later).", "Buy spare clips.", "Gather the right Torx bits."], "steps": [{"title": "Disconnect the battery", "blocks": [{"t": "text", "b": "On a car with door airbags, disconnect the battery and wait about 15 minutes before you start."}, {"t": "warn", "b": "Disconnect the battery and wait about 15 minutes before touching any airbag. Keep tools and your body out of line with the module."}]}, {"title": "Find and remove the hidden screws", "blocks": [{"t": "text", "b": "Pop the covers by the pull handle with a nylon tool and take out the screws. The airbag badge also hides a mounting screw behind it (Red Eye Garage). Remove the door lock rod cap, which threads off."}, {"t": "ill", "id": "e36-panel-hero", "cap": "Screws by the pull handle and behind the airbag badge. Slide the handle shroud back."}]}, {"title": "Release the clips and lift the panel", "caution": true, "blocks": [{"t": "text", "b": "Start low and pop the clips around the edge one at a time with a trim tool. Free the lower panel, then pop the upper tabs and lift the panel up and over the lock rod. Disconnect the speaker and switch wiring."}, {"t": "warn", "b": "Don''t pull the panel off in one go. The wires and the fragile plastic will tear."}]}, {"title": "Peel back the vapor barrier", "blocks": [{"t": "text", "b": "The vapor barrier is stuck with butyl sealant. Peel it back carefully with a knife if needed."}]}, {"title": "Refit", "blocks": [{"t": "text", "b": "Fit new clips, reseal the barrier, reconnect the wiring, line up the panel, press the clips home and refit the screws and covers."}]}], "alsoReplace": [{"name": "Speakers", "why": "The panel is off already."}, {"name": "Window regulator or sliders", "why": "See the Window regulator guide."}], "check": {"tab": "Why is it rattling?", "title": "Panel problems", "illId": "e36-panel-hero", "illCap": "Most noise is clips.", "rows": [{"see": "Rattle when you close the door", "means": "Broken clips.", "do": "Replace the clips."}, {"see": "Warped upper panel", "means": "Heat and age.", "do": "Reseat with new clips; replace if badly warped."}, {"see": "Panel won''t come off", "means": "A hidden screw.", "do": "Check behind the badge and the covers."}], "c": {"level": "medium", "n": 2, "note": "Common panel issues."}}, "sources": ["Red Eye Garage — Project E36 M3 window motor and regulator (hidden screws, airbag badge)", "FCP Euro — E36 front window regulator and motor (door card removal)", "Pelican Parts — E30/E36 door panel and lock troubleshooting (fragile panels, clips)"]}'::jsonb);
insert into guides (id, content) values ('e36-seat-twist', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The power seat flex cable fix applies to E36, E39 and E46 power seats", "embeds": [], "aftercare": ["Re-check the bolts after a week.", "Check the belt warning light."], "disagreements": [{"topic": "Zip tie or splice", "pos": "Zip-tying removes slack. The hose splice bridges a gap.", "call": "Try the zip tie first. It''s reversible."}], "id": "e36-seat-twist", "title": "Seat twist fix & racing seat mounting", "category": "Interior", "kind": "repair", "heroId": "e36-seat-hero", "heroCap": "A power seat moves on flexible drive cables. When a cable twists or slips, the seat tilts or won''t move straight.", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$0–400", "risk": "Pinched wiring · lifting the seat without support", "why": "A seat that tilts or twists is usually a slack or slipped flex cable, not a broken seat. A zip tie or a sleeve repair is often enough.", "note": "You don''t have to remove the seat for some twist fixes. For a racing seat swap, you do."}, "lifespan": {"title": "When to expect it", "headline": ["No interval", "Cables stretch and slip with age"], "earliest": "Seat bottom or back tilts on one side", "detail": "A cable slips out of its sheath or loses the grip of its motor.", "factors": ["Age", "Heavy use"], "inspect": ["Move each seat control and see which side doesn''t follow"], "confidence": {"level": "community", "n": 2, "note": "Owner threads on BimmerFest describe the same fix."}}, "should": {"yesIf": ["The seat twists or tilts", "You want a racing seat in place of the power seat"], "codes": [], "notes": ["Try the cable fix before you replace anything."], "confidence": {"level": "community", "n": 2, "note": "BimmerFest threads."}}, "variants": {"questions": [{"question": "What are you doing?", "hint": "A twist fix keeps the factory seat. A racing seat swap needs mounting brackets.", "options": [{"id": "sfix", "label": "Fix a twisted seat", "when": "Cable repair", "oeOnly": true}, {"id": "sswap", "label": "Fit a racing seat", "when": "Floor adapters and side brackets"}]}]}, "parts": [{"tier": "oe", "name": "Zip ties and a short piece of rubber hose", "price": "$5", "note": "For the cable repair that owners describe: zip-tie the cable to remove slack, or sleeve a cut gap.", "only": ["sfix"]}, {"tier": "aftermarket", "name": "Racing seat floor mount adapters", "price": "$150–300", "note": "Garagistic''s E36/E46 adapters are 6061 aluminum, M8×1.25 hardware, with two position settings (under 6 ft and over 6 ft). The VAC kit uses M8 × 25 mm bolts. BimmerWorld sells billet adapters from $249.99.", "only": ["sswap"], "links": [{"store": "Garagistic", "url": "https://www.garagistic.com/products/e36-e46-racing-seat-floor-mount-adapters"}, {"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Safety-Race-Interior/Seat-Mounting/"}]}, {"tier": "aftermarket", "name": "Side mount brackets for your seat", "price": "$35–150", "note": "Specific to the seat maker. Garagistic''s adapters fit side-mount seats.", "only": ["sswap"]}], "aftermarket": [{"name": "Garagistic floor mount adapters", "note": "Fit all E36s (not convertibles), with the most adjustment of any bracket.", "price": "See Garagistic", "only": ["sfix"]}, {"name": "VAC Motorsports race seat kit", "note": "Floor adapters with M8 × 25 mm bolts and side mounts.", "price": "See VAC", "only": ["sfix"]}], "tools": [{"name": "Socket set", "note": "For the seat bolts", "price": "$30"}, {"name": "Zip ties, wire cutters, needle-nose pliers", "note": "For the cable fix", "price": "$10"}, {"name": "Torque wrench", "note": "For the seat bolts", "price": "$40–70"}], "before": ["Disconnect the battery if the seat has any airbag or belt sensor wiring.", "Have a helper for the seat.", "Take photos of the wiring."], "steps": [{"title": "Find which control is twisting", "blocks": [{"t": "text", "b": "Move each seat control. A seat has several motors: base forward and back, up and down, tilt, recline and thigh extension. Find the one that doesn''t follow."}, {"t": "ill", "id": "e36-seat-hero", "cap": "Each motor drives its own flex cable. The slack one is the culprit."}], "only": ["sfix"]}, {"title": "Get at the cable", "blocks": [{"t": "text", "b": "Raise the seat as high as it goes. Owners describe undoing the rear bolts and rolling the seat forward to unhook the front, which gives access without a full removal. Take the back cover off the seat back if the twist is in the upper back."}], "only": ["sfix"]}, {"title": "Remove the slack", "caution": true, "blocks": [{"t": "text", "b": "One owner removed about an inch of sheathing and zip-tied the cable to the seat frame to take out slack. Another cut the tube, trimmed it, and bridged the gap with a piece of rubber hose and two clamps on each end."}, {"t": "note", "b": "These are owner fixes from BimmerFest. No factory procedure was found."}], "only": ["sfix"]}, {"title": "Refit and test", "blocks": [{"t": "text", "b": "Level the seat so both sides are equal, roll it back, bolt it down and test every control."}], "only": ["sfix"]}, {"title": "Remove the factory seat", "blocks": [{"t": "text", "b": "Disconnect the battery and unplug the seat wiring. Undo the rear bolts and roll the seat forward to unhook the front, then lift it out with a helper."}], "only": ["sswap"]}, {"title": "Fit the floor adapters and side brackets", "blocks": [{"t": "text", "b": "Mark and fit the floor adapters to the factory seat points, then mount the side brackets to the seat. VAC''s sheet says the wide adapter mounts closest to the door and that you may need to elongate the seat''s holes."}, {"t": "torque", "label": "Seat mounting bolts", "nm": 56, "c": {"level": "single", "n": 2, "note": "Garagistic''s E36 torque guide gives 41 ft-lb for seat bolts and floor mounts. Use blue threadlocker."}, "note": "41 ft-lb"}], "only": ["sswap"]}, {"title": "Test the belt and fit", "caution": true, "blocks": [{"t": "text", "b": "Check the seatbelt still reaches and latches, and that nothing rubs. Check the seat at your driving position with the helmet if you wear one."}, {"t": "warn", "b": "A seat that isn''t properly bolted is a safety hazard. Check every bolt."}], "only": ["sswap"]}], "alsoReplace": [{"name": "Seat belt sensor connector", "why": "A removed seat may trigger a warning light."}, {"name": "Seat rail grease", "why": "Cheap while you''re there."}], "check": {"tab": "Cable or motor?", "title": "Why is it twisting?", "illId": "e36-seat-hero", "illCap": "Listen to the motor.", "rows": [{"see": "Motor whirs but nothing moves", "means": "Slipped cable.", "do": "Re-seat or remove the slack."}, {"see": "One side moves and one doesn''t", "means": "Slack on that side.", "do": "Zip-tie the cable."}, {"see": "Nothing at all", "means": "Fuse, switch or motor.", "do": "Check those first."}], "c": {"level": "community", "n": 2, "note": "BimmerFest owner threads."}}, "sources": ["BimmerFest — seat twist fix threads (cable zip-tie and hose splice)", "Garagistic — racing seat floor mount adapters and E36 torque guide (seat bolts 41 ft-lb)", "VAC Motorsports — race seat installation kit for the E36/E46", "BimmerWorld — seat mounting adapters"]}'::jsonb);
insert into guides (id, content) values ('e36-steering-wheel', '{"fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The M3 uses the same round-airbag wheels as other 1996–99 E36s; square-airbag E46 wheels are a different swap", "embeds": [], "aftercare": ["Check the center bolt after a week.", "Check the horn and SRS light."], "disagreements": [{"topic": "Resistors vs real airbag", "pos": "Resistors keep the light off but delete the driver''s airbag.", "call": "Keep a real airbag if you can. Resistors only for race use."}], "id": "e36-steering-wheel", "title": "Steering wheel swap", "category": "Interior", "kind": "upgrade", "heroId": "e36-wheel-hero", "heroCap": "The wheel bolts to the column splines. The airbag rides on the wheel, and a contact ring (clock spring) behind it carries the horn and airbag signals.", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$100–600", "risk": "The airbag · breaking the contact ring · airbag warning light", "why": "A new wheel is one of the nicest feel upgrades. A round-airbag M wheel swaps in directly, and an aftermarket wheel needs a hub adapter and resistors to keep the airbag circuit happy.", "note": "Disconnect the battery and wait about 15 minutes. Don''t let the contact ring spin while the wheel is off."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Wheels wear at the leather and horn pad"], "earliest": "Worn leather or a cracked rim", "detail": "Wheel wear is cosmetic.", "factors": [], "inspect": ["Check the leather and the horn"], "confidence": {"level": "single", "n": 1, "note": "General."}}, "should": {"yesIf": ["The leather is worn or cracked", "You want an M or aftermarket wheel"], "codes": [], "notes": ["A round airbag M3 wheel is plug and play on an E36 with a round airbag."], "confidence": {"level": "medium", "n": 2, "note": "E46Fanatics swap thread and Pelican agree."}}, "variants": {"questions": [{"question": "Which wheel?", "hint": "Round-airbag OEM wheels reuse your airbag. Aftermarket wheels need an adapter and resistors.", "options": [{"id": "woem", "label": "OEM M3 round-airbag wheel", "when": "Reuse your airbag", "oeOnly": true}, {"id": "waft", "label": "Aftermarket wheel", "when": "Momo, Sparco etc., with hub adapter"}]}]}, "parts": [{"tier": "oe", "name": "M3 steering wheel (round airbag)", "price": "$150–500", "note": "A plug-and-play swap if your car has a round airbag. Reuse your airbag module.", "only": ["woem"]}, {"tier": "aftermarket", "name": "Aftermarket wheel and hub adapter", "price": "$150–500", "note": "Pelican describes a Momo hub (2008) with a green/yellow ground wire and a black horn wire.", "only": ["waft"]}, {"tier": "aftermarket", "name": "Airbag resistors", "price": "$5", "note": "Pelican lists a 1.5 W 3.3 ohm resistor or 3.5 W 10 ohm resistors for the airbag connector so the warning light stays off.", "only": ["waft"]}], "aftermarket": [{"name": "Momo / Sparco hub adapter wheels", "note": "Need a horn wire and resistors.", "price": "See retailer", "only": ["woem"]}], "tools": [{"name": "T27 and T30 Torx", "note": "Airbag screws. T27 on the Sport 3-spoke", "price": "$10"}, {"name": "16 mm socket and a breaker bar", "note": "For the center bolt", "price": "$15"}, {"name": "Torque wrench", "note": "Up to 63 Nm", "price": "$40–70"}, {"name": "13 mm wrench", "note": "Battery terminal", "price": "$5"}], "before": ["Disconnect the battery and wait at least 15 minutes.", "Mark the wheel to the shaft.", "Keep the key out and the column locked."], "steps": [{"title": "Disconnect the battery and wait", "caution": true, "blocks": [{"t": "warn", "b": "Disconnect the battery and wait about 15 minutes before touching any airbag. Keep tools and your body out of line with the module."}, {"t": "text", "b": "Remove the lower plastic cover under the wheel and unplug the bright orange airbag connector."}]}, {"title": "Remove the airbag", "blocks": [{"t": "text", "b": "Undo the two Torx screws on the back of the wheel that hold the airbag (T27 or T30 depending on the wheel). Lift the airbag off and unplug the small harness. Store the module face up, away from you."}, {"t": "ill", "id": "e36-wheel-hero", "cap": "Airbag, wheel, center bolt, and the contact ring behind it."}]}, {"title": "Mark and remove the wheel", "blocks": [{"t": "text", "b": "Mark the wheel''s position to the shaft with a paint pen. Undo the 16 mm center bolt with a breaker bar and pull the wheel off. Keep the contact ring from spinning while the wheel is off."}, {"t": "warn", "b": "If the contact ring turns, the ribbon inside can snap. Pelican says loosening the bolt activates a spring clip that holds the ring centered."}]}, {"title": "Fit the new wheel", "caution": true, "blocks": [{"t": "text", "b": "Line up the splines and the marks, with the lock pin on the column engaging the opening in the contact ring. Fit the center bolt."}, {"t": "torque", "label": "Steering wheel center bolt", "nm": 63, "c": {"level": "high", "n": 3, "note": "Doug''s Domain, Redline Goods and the Bentley figure all give 63 Nm (46 ft-lb). A different source gives 80 Nm for a nut."}, "note": "46 ft-lb"}, {"t": "text", "b": "Doug''s Domain notes that is a lot of torque for the steering lock to hold. Hold the wheel off the lock and use the torque wrench carefully."}]}, {"title": "Connect the airbag or resistors", "blocks": [{"t": "text", "b": "Reconnect the airbag harness and refit the airbag with its Torx screws, tightened to about 8 Nm (6 ft-lb) per Redline Goods."}, {"t": "text", "b": "Aftermarket wheel: plug resistors into the two airbag connectors instead and wire the horn through the hub adapter.", "only": ["waft"]}]}, {"title": "Reconnect the battery and check", "blocks": [{"t": "text", "b": "Reconnect the battery. The airbag light should come on briefly and go out. If it stays on, check the connectors and resistors."}, {"t": "text", "b": "Center the wheel and check the horn and the cruise and radio buttons if fitted."}]}], "alsoReplace": [{"name": "Contact ring", "why": "If the horn or airbag light misbehaves."}, {"name": "Shift knob", "why": "Pair with the interior upgrade."}], "check": {"tab": "Airbag light on?", "title": "SRS light checks", "illId": "e36-wheel-hero", "illCap": "The light tells you a lot.", "rows": [{"see": "Light stays on", "means": "Airbag connector not seated or resistor wrong.", "do": "Check both connectors."}, {"see": "Horn doesn''t work", "means": "Contact or ground wire.", "do": "Check the hub wiring."}, {"see": "Wheel off-center", "means": "Splines misaligned.", "do": "Realign with the paint marks."}], "c": {"level": "medium", "n": 2, "note": "Common wheel swap problems."}}, "sources": ["Doug''s Domain — E36 steering wheel conversion (63 Nm, T27/T30, 16 mm)", "Redline Goods — 1990–98 BMW steering wheel installation (63 Nm bolt, 8 Nm airbag screws, contact ring pin)", "Pelican Parts — E36 steering wheel removal and replacement (Momo hub, resistors, 15-minute wait)", "E46Fanatics — steering wheel swap info thread (round airbag swap)"]}'::jsonb);
insert into guides (id, content) values ('e36-control-arms', '{"id": "e36-control-arms", "title": "Front control arms & ball joints", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "1995 M3 arms share the geometry; 1996–99 M3 arms and bushings differ from other E36s", "category": "Steering", "kind": "repair", "heroId": "e36-arm-hero", "heroCap": "The ball joint is part of the arm. When it wears, the whole arm is replaced, and the bushing at the rear locates the arm to the frame rail.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$250–700", "risk": "Worn ball joint separating under load · using non-M bushings on the wrong geometry", "why": "Ball joints on the M3''s control arms aren''t normally serviceable. When one wears, the arm goes. A failed ball joint is a safety problem, and the arm, bushing and alignment all have to be right afterwards.", "note": "The 96–99 M3 used a different control arm, bushing and spindle from other E36s, so mixing parts changes caster and wheel position."}, "lifespan": {"title": "When to expect it", "headline": ["No official interval", "Turner advises yearly inspection and replacement every 3–4 years on a street car"], "earliest": "Clunking over bumps, vague steering or wandering at speed", "detail": "A retailer''s maintenance advice, not a factory number. The honest rule is to inspect often and replace when there''s play.", "factors": ["Age", "Lowering", "Hard driving", "Torn ball joint boots"], "inspect": ["Check ball joint play with the wheel unloaded", "Look for cracked or torn bushings"], "confidence": {"level": "single", "n": 1, "note": "Turner''s advice is the only interval given."}}, "should": {"yesIf": ["Ball joint has play", "Control arm bushing is split", "Steering wanders or clunks", "You''re lowering the car and want the front end tight"], "codes": [], "notes": ["A bad ball joint is a failure risk. Don''t put this off."], "confidence": {"level": "medium", "n": 2, "note": "Turner and owner threads agree."}}, "variants": {"questions": [{"question": "What kind of arm do you want?", "hint": "Factory M3 arms are expensive and sometimes hard to source.", "options": [{"id": "oearm", "label": "OE-style arm", "when": "Lemförder or Meyle HD, rubber bushing", "oeOnly": true}, {"id": "trackcab", "label": "Arms with Delrin bushings", "when": "BimmerWorld TrackCAB, track use", "brand": true}]}]}, "parts": [{"tier": "oe", "name": "Front control arm (each)", "pn": "BMW 31122228461 (L) / 31122228462 (R) for 96–99 M3 · Lemförder 31121140957 (L, non-M E36)", "price": "$100–250 each", "note": "BimmerWorld says original M3 arms are costly and hard to source. Many owners use Meyle HD non-M arms with offset bushings.", "only": ["oearm"]}, {"tier": "aftermarket", "name": "TrackCAB control arm and bushing package", "price": "$259.99", "note": "Left and right Meyle HD arms with offset Delrin bushings, as close as possible to the original 96–99 M3 caster. Track use only.", "only": ["trackcab"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Front-Control-Arm-Bushing-Package-TrackCAB-E36-M3-96-99.html"}]}, {"tier": "oe", "name": "Control arm bushings", "price": "$30–120", "note": "See the FCAB guide. Do them with the arms."}, {"tier": "oe", "name": "Tie rod ends and sway bar links", "price": "$60–120", "note": "Often disturbed on this job."}], "aftermarket": [{"name": "Condor / Turner E46 conversion arms", "note": "Gives more negative camber and steering angle, but needs E36 outer tie rods and E90 inner tie rods per Turner.", "price": "See Turner", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-755-bmw-front-control-arm/m-1476-condor-speed-shop?Nrpp=48"}]}], "tools": [{"name": "Jack and four jack stands", "note": "Rated for the car", "price": "$150+"}, {"name": "Ball joint separator or pickle fork", "note": "", "price": "$15–30"}, {"name": "Torque wrench", "note": "Up to the largest nut on the arm", "price": "$60–100"}, {"name": "Press or vise", "note": "For pressing bushings into the arm", "price": "Shop or $60"}], "before": ["Decide on bushings first. Do the FCAB job at the same time.", "Book an alignment for after.", "Soak the nuts in penetrating oil the night before."], "steps": [{"title": "Lift the front and take the wheel off", "blocks": [{"t": "text", "b": "Chock the rear wheels, jack the front and use stands. Remove the wheel."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Look before you loosen", "blocks": [{"t": "text", "b": "Check the ball joint boot, the bushing and the arm itself. Note how the old bushing sits so the new one goes in the same way."}, {"t": "ill", "id": "e36-arm-hero", "cap": "Ball joint at the outer end and the bushing at the rear."}]}, {"title": "Disconnect the sway bar link and strut", "blocks": [{"t": "text", "b": "On the M3 the sway bar link attaches to the strut bracket, not the arm. Take it off there if it''s in the way. Take out the bolt holding the arm to the strut or knuckle, supporting the strut so it can''t drop."}]}, {"title": "Separate the ball joint and the arm", "caution": true, "blocks": [{"t": "text", "b": "Undo the ball joint nut and separate the joint from the hub with a puller. Remove the bolts at the front and rear of the arm where it meets the subframe, and take the arm out."}, {"t": "torque", "label": "Ball joint nut to steering arm", "nm": 65, "c": {"level": "high", "n": 2, "note": "The Bentley list gives 48 ft-lb for the control arm ball joint to the steering arm, and another E36 reference gives 65 Nm."}, "note": "48 ft-lb, new self-locking nut"}]}, {"title": "Fit the new arm and bushing", "blocks": [{"t": "text", "b": "Press the new bushing into the arm if it isn''t pre-fitted (see the FCAB guide), then fit the arm and bolts finger-tight."}, {"t": "text", "b": "Final-tighten the arm and ball joint nut with the car at ride height, not hanging on stands."}, {"t": "torque", "label": "Arm bushing carrier to body", "nm": 46, "c": {"level": "high", "n": 3, "note": "Bentley list gives 34 ft-lb, and Garagistic gives 31–35 ft-lb."}, "note": "34 ft-lb, at ride height"}, {"t": "torque", "label": "Strut to steering arm", "nm": 105, "c": {"level": "high", "n": 3, "note": "Bentley list (78 ft-lb, new bolt), Turner (105 Nm) and FCP Euro (107 Nm) agree."}, "note": "78 ft-lb, new bolt"}]}, {"title": "Lower the car and get an alignment", "caution": true, "blocks": [{"t": "text", "b": "Settle the car on its wheels, tighten the fasteners at ride height and book the alignment. Control arms change caster and camber."}]}], "alsoReplace": [{"name": "Control arm bushings", "why": "They''re already out. Doing them now saves a second alignment."}, {"name": "Tie rod ends", "why": "Same corner, same alignment visit."}], "check": {"tab": "Ball joint test", "title": "Is the ball joint worn?", "illId": "e36-arm-hero", "illCap": "Check with the wheel off the ground.", "rows": [{"see": "Wheel rocks top and bottom", "means": "Ball joint or wheel bearing.", "do": "Pry between arm and hub; if the joint moves, replace the arm."}, {"see": "Boot torn and dry", "means": "Joint will fail soon.", "do": "Replace the arm."}, {"see": "Clunk on bumps with a tight joint", "means": "Bushing or sway bar link.", "do": "Check those before buying an arm."}], "c": {"level": "medium", "n": 2, "note": "Standard ball joint checks."}}, "aftercare": ["Alignment right away.", "Re-check the arm bolts after 100 miles.", "Look at the boot after a few weeks."], "disagreements": [{"topic": "OE M3 arms or non-M arms with offset bushings", "pos": "BimmerWorld''s package uses non-M Meyle HD arms with offset bushings to get close to the M3''s original caster. E30 M3 arms are aluminum and expensive.", "call": "Non-M arms with offset bushings are a sound street fix. Use real M3 parts if you want zero compromise."}], "sources": ["BimmerWorld — TrackCAB package for 1995–99 E36 M3 (96–99 M3 differ; OE part numbers)", "Turner Motorsport — Lemförder E36 control arm (inspection advice, bushing at rear) and Condor arms", "Bimmerforums — M3 ball joint threads (arms not normally serviceable)", "Bentley E36 list as posted on Club Cobra (ball joint 48 ft-lb, bushing carrier 34 ft-lb)", "Garagistic — E36 bolt torque guide (front control arms 31–35 ft-lb)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-steering-rack', '{"id": "e36-steering-rack", "title": "Steering rack (replace or Z3 swap)", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The Z3 rack fits E36 six-cylinders; E46 racks need different tie rods", "category": "Steering", "kind": "upgrade", "heroId": "e36-rack-hero", "heroCap": "The M3''s rack isn''t quicker than a standard E36 rack. Locking plates just limit its travel. The Z3 rack is the quick-ratio swap most owners choose.", "glance": {"timeFirst": "5–8 hr", "timeRepeat": "3–4 hr", "difficulty": 3, "cost": "$400–1,200", "risk": "Centering the rack wrong · power steering fluid mess · losing alignment", "why": "A leaking or loose rack is a replace-it job, and the Z3 rack is a popular upgrade at the same time because it needs no custom linkage. Plan on new tie rods and a fluid flush with it.", "note": "A Z3 swap is a mild improvement, not the jump you''d get from an E30 rack to a Z3 one."}, "lifespan": {"title": "When to expect it", "headline": ["No fixed interval", "Replace when it leaks or the steering has slop you can''t trace elsewhere"], "earliest": "Fluid on the rack, a wet boot or a heavy, notchy feel", "detail": "Racks wear slowly. Excess fluid heat accelerates wear per Turner. Try the tie rods, mounts and fluid before condemning the rack.", "factors": ["Hot power steering fluid", "Leaking boots", "Age"], "inspect": ["Look for wet boots", "Check the fluid level and color"], "confidence": {"level": "single", "n": 1, "note": "Turner''s description only."}}, "should": {"yesIf": ["The rack leaks or has slack that tie rods and mounts don''t explain", "You want a quicker ratio", "You''re already replacing the tie rods"], "codes": [], "notes": ["Reman and new racks vary in quality. Buy from a known supplier."], "confidence": {"level": "medium", "n": 2, "note": "Turner and owner threads agree."}}, "variants": {"questions": [{"question": "Like-for-like or Z3 rack?", "hint": "The Z3 rack is the quickest option that bolts in.", "options": [{"id": "samerack", "label": "Replace like-for-like", "when": "Same M3 rack", "oeOnly": true}, {"id": "z3rack", "label": "Z3 quick-ratio rack", "when": "2.7 turns lock to lock"}]}]}, "parts": [{"tier": "oe", "name": "Steering rack (M3)", "price": "$300–900", "note": "New or remanufactured. Includes locking plates on the M3 rack.", "only": ["samerack"]}, {"tier": "oe", "name": "Z3 steering rack", "pn": "32 13 1 094 038 (as listed on the e30zone wiki)", "price": "$350–1,000", "note": "2.7 turns lock to lock. Needs a full set of E36 inner and outer tie rods, not E46.", "only": ["z3rack"]}, {"tier": "oe", "name": "Inner and outer tie rod assemblies", "price": "$80–240", "note": "A complete set of E36-style tie rods. See the Tie rods guide."}, {"tier": "oe", "name": "Steering guibo / U-joint, mounts, fluid", "price": "$30–100", "note": "Replace the guibo while the shaft is off."}], "aftermarket": [{"name": "Turner comprehensive power steering service kit (E36 M3)", "note": "For routine service or when replacing a pump or rack.", "price": "See Turner"}], "tools": [{"name": "Jack and four jack stands", "note": "", "price": "$150+"}, {"name": "Inner tie rod tool", "note": "", "price": "$25–45"}, {"name": "Drain pan and fluid", "note": "Power steering fluid spills", "price": "$20"}, {"name": "Torque wrench", "note": "", "price": "$60–100"}], "before": ["Order the tie rods with the rack.", "Check the new rack''s centering mark before fitting.", "Book the alignment."], "steps": [{"title": "Lift the car and drain the fluid", "blocks": [{"t": "text", "b": "Lift the front onto stands, take the wheels off and drain the power steering reservoir and lines into a pan."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Disconnect the steering shaft", "blocks": [{"t": "text", "b": "Mark the guibo and shaft position so the steering wheel ends up straight, then undo the shaft clamp at the rack."}, {"t": "text", "b": "Both racks have a short boot on the input shaft that lines up with a mark on the rack to center it, per an owner who did the Z3 swap."}]}, {"title": "Remove the tie rods and rack", "blocks": [{"t": "chart", "title": "Turns lock to lock (fewer is quicker)", "unit": "turns", "baseline": "E36 M3 ''96–99", "bars": [{"label": "E30", "v": 4.0}, {"label": "E36", "v": 3.4}, {"label": "E36 M3 ''95", "v": 3.0}, {"label": "E36 M3 ''96–99", "v": 3.2}, {"label": "E46", "v": 3.2}, {"label": "Z3", "v": 2.7}], "source": "e30zone wiki, steering rack conversions", "c": {"level": "single", "n": 1, "note": "One wiki table; M3 racks are standard racks with locking plates."}}, {"t": "text", "b": "Separate the outer ends from the struts. Undo the fluid lines at the rack and the mounting bolts, then lower the rack out."}, {"t": "note", "b": "Mark the guibo and shaft before you undo the clamp, and bend back the inner tie rod locking plates before unscrewing them."}, {"t": "ill", "id": "e36-rack-hero", "cap": "Rack ratio: lock-to-lock turns for each rack. Fewer turns is quicker."}]}, {"title": "Fit the new rack", "caution": true, "blocks": [{"t": "text", "b": "Put the new rack in, center it using its mark, and fit the mounts and fluid lines with new seals."}, {"t": "text", "b": "Z3 rack: this fits without custom linkage. Use a complete set of E36 inner and outer tie rods.", "only": ["z3rack"]}, {"t": "torque", "label": "Rack to subframe bolts", "nm": 51, "c": {"level": "single", "n": 2, "note": "A Z3 rack retrofit write-up on an E36 gives 38 ft-lb. Other racks'' write-ups differ, so follow your rack''s sheet if it has one."}, "note": "38 ft-lb"}, {"t": "torque", "label": "Steering shaft coupler bolt", "nm": 22, "c": {"level": "single", "n": 2, "note": "The same write-up gives 16 ft-lb. An E46 rack guide agrees (16 ft-lb)."}, "note": "16 ft-lb, replace if it''s a stretch bolt"}, {"t": "torque", "label": "Pressure line banjo bolt (22 mm)", "nm": 40, "c": {"level": "medium", "n": 2, "note": "Two E36 write-ups give 30 ft-lb. Use new crush washers and don''t over-tighten; the bolts are hollow."}, "note": "30 ft-lb"}, {"t": "torque", "label": "Inner tie rod to rack", "nm": 70, "c": {"level": "high", "n": 2, "note": "Garagistic gives 52 ft-lb."}, "note": "52 ft-lb"}, {"t": "torque", "label": "Outer end nut / lock nut", "nm": 45, "c": {"level": "high", "n": 2, "note": "Garagistic gives 33 ft-lb for the nut and 26 ft-lb for the lock nut (35 Nm)."}, "note": "33 ft-lb nut, 26 ft-lb lock nut"}]}, {"title": "Fill, bleed and align", "blocks": [{"t": "text", "b": "Refill with the correct fluid, bleed the system by turning the wheel lock to lock with the engine off, then running it. Wheels on, car down, then the alignment."}]}], "alsoReplace": [{"name": "Tie rods", "why": "Always with a new rack."}, {"name": "Steering guibo", "why": "Cheap while the shaft is apart."}, {"name": "Power steering fluid and hoses", "why": "Old fluid and a leaking hose will contaminate the new rack."}], "check": {"tab": "Rack or tie rod?", "title": "Rack or something else?", "illId": "e36-rack-hero", "illCap": "Rule out the cheap stuff first.", "rows": [{"see": "Wet rack boots or fluid on the rack", "means": "Leaking rack.", "do": "Replace or reseal."}, {"see": "Play at the wheel but a dry rack", "means": "Tie rods or ball joints.", "do": "Check those first."}, {"see": "Heavy or notchy steering", "means": "Low fluid or pump.", "do": "Check the fluid and pump before the rack."}], "c": {"level": "medium", "n": 2, "note": "Common diagnosis path."}}, "aftercare": ["Check for leaks after the first drive.", "Top up the fluid after a day.", "Alignment before real miles."], "disagreements": [{"topic": "Is the M3 rack the quick one?", "pos": "Its 3.2-turn figure looks quick, but the e30zone wiki says it''s a standard E36 rack with locking plates limiting its travel.", "call": "Don''t buy it for ratio. The Z3 rack is the real quick option."}], "sources": ["e30zone wiki — steering rack conversions (turns lock to lock by rack, tie rod rules, Z3 rack)", "Bimmerforums — owner''s Z3 rack swap thread (centering, E46 guibo vane)", "Turner Motorsport — steering rack (2.7 turn Z3 rack, PS service kit)", "NAM3Forum — Z3 steering rack retrofit (rack bolts, coupler, banjo bolts)", "Garagistic — E36 bolt torque guide (tie rods)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-tie-rods', '{"id": "e36-tie-rods", "title": "Tie rods (inner & outer)", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "The same Lemförder tie rod assembly fits E36 six-cylinders and the Z3, M Roadster and M Coupe", "category": "Steering", "kind": "repair", "heroId": "e36-tierod-hero", "heroCap": "Each side has an inner tie rod screwed into the rack and an outer end that clamps to the strut. The pair is sold as one assembly.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$80–250", "risk": "Alignment goes out the moment you turn the outer end · skipping the locking plate", "why": "Worn tie rods put slop in the steering and make popping and knocking noises. They''re cheap to replace as complete assemblies, and doing both ends together makes the alignment easier because every joint is new.", "note": "Count turns on the old outer end before you take it off so the new one starts near the right toe. You still need an alignment afterwards."}, "lifespan": {"title": "When to expect it", "headline": ["No fixed interval", "Replace when there''s play, popping or uneven tire wear"], "earliest": "Slack in the steering or a popping ball joint is the classic sign", "detail": "Turner describes worn tie rods as slop in the wheel plus knocks and creaks, and calls replacement cheap insurance. Boots tear first, then the joints loosen.", "factors": ["Age", "Torn boots letting grit in", "Curb strikes"], "inspect": ["Grab each front wheel at 9 and 3 o''clock and rock it with the car on stands", "Look for torn boots"], "confidence": {"level": "single", "n": 1, "note": "Retailer description only; no published mileage."}}, "should": {"yesIf": ["The steering has slack or clunks", "A tie rod boot is torn", "The front tires wear unevenly", "You''re replacing the rack or control arms anyway"], "codes": [], "notes": ["Replace left and right together. If you''re swapping the rack, do the tie rods at the same time. The new rack should get new tie rods."], "confidence": {"level": "medium", "n": 2, "note": "Turner and owner write-ups agree."}}, "parts": [{"tier": "oe", "name": "Tie rod assembly, left and right", "pn": "Lemförder (OE supplier), Meyle, Febi, Bav Auto", "price": "$40–120 each", "note": "Complete inner and outer assembly. Fits E36 including the M3 coupe, sedan and convertible, and the Z3."}, {"tier": "oe", "name": "Inner tie rod locking plates", "price": "$5–15", "note": "Securing plate for the inner assembly. Replace it, don''t reuse a bent one."}, {"tier": "aftermarket", "name": "Turner steering rack stop kit", "price": "$30–60", "note": "Delrin stops that limit steering travel, plus two locking plates (E36 only). Optional.", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-864-bmw-tie-rods"}]}], "aftermarket": [{"name": "Turner rack stops", "note": "Protect the rack and let you turn to full lock without rubbing on wide wheels.", "price": "See Turner", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-864-bmw-tie-rods"}]}], "tools": [{"name": "Inner tie rod removal tool", "note": "Removes the inner rod without taking the outer end off first (CTA type)", "price": "$25–45"}, {"name": "Tie rod end puller or pickle fork", "note": "To separate the outer ball joint from the strut", "price": "$15–30"}, {"name": "Jack and four jack stands", "note": "Rated for the car", "price": "$150+"}, {"name": "Torque wrench", "note": "For the outer nut and lug nuts", "price": "$40–70"}], "before": ["Book the alignment before you start so you''re not stranded with a car that tracks badly.", "Mark the old outer end''s position on the thread with paint, or count the turns when you take it off.", "Soak the threads in penetrating oil the night before."], "steps": [{"title": "Lift the front and take the wheels off", "blocks": [{"t": "text", "b": "Chock the rear wheels, lift the front and put the car on stands. Take off the wheels."}, {"t": "warn", "b": "Support the car on jack stands on level ground. Never work under a car held only by a jack."}]}, {"title": "Free the outer end from the strut", "blocks": [{"t": "text", "b": "Undo the 17 mm lock nut holding the outer tie rod end to the strut, then separate the joint with a puller or pickle fork. The e30 wiki''s rack conversion notes describe this same nut."}, {"t": "ill", "id": "e36-tierod-hero", "cap": "Outer end on the strut, inner rod into the rack. Don''t touch the adjustment nut between them unless the instructions say to."}]}, {"title": "Count turns and take the old outer end off", "caution": true, "blocks": [{"t": "text", "b": "Hold the rod and unscrew the old outer end, counting full turns. Write the number down. This puts the new end close to the right toe."}, {"t": "text", "b": "Do not touch the adjustment nut between the inner and outer rods on a complete assembly."}]}, {"title": "Remove the inner tie rod", "blocks": [{"t": "text", "b": "Peel back the rack boot to see the inner rod and its locking plate. Bend the plate flat, then unscrew the inner rod from the rack with the inner tie rod tool."}, {"t": "note", "b": "Bend the locking plate flat first, and use a new plate when you refit."}]}, {"title": "Fit the new assembly", "blocks": [{"t": "text", "b": "Screw the new inner rod into the rack with a new locking plate, then bend the plate over to lock it. Fit the new boot and clamps."}, {"t": "text", "b": "Thread the new outer end on the same number of turns, fit it into the strut and tighten the nut."}, {"t": "torque", "label": "Inner tie rod to rack", "nm": 70, "c": {"level": "high", "n": 2, "note": "Garagistic''s E36 guide gives 52 ft-lb and another E36 reference gives 71 Nm."}, "note": "52 ft-lb"}, {"t": "torque", "label": "Outer end to strut (castle nut)", "nm": 45, "c": {"level": "high", "n": 3, "note": "Garagistic 33 ft-lb, an E36 reference of 45 Nm, and an owner write-up of 31–42 ft-lb overlap here."}, "note": "33 ft-lb, new cotter pin if it''s a castle nut"}, {"t": "torque", "label": "Outer end lock nut", "nm": 35, "c": {"level": "high", "n": 2, "note": "Garagistic 26 ft-lb and another E36 reference of 35 Nm agree."}, "note": "26 ft-lb"}]}, {"title": "Put the car down and get the alignment", "caution": true, "blocks": [{"t": "text", "b": "Wheels on, car down, steering straight. Drive carefully to the alignment shop. Don''t wait on this: you changed toe the moment the outer end moved."}]}], "alsoReplace": [{"name": "Steering rack boots", "why": "The boots are off anyway. A torn boot is why most inner rods die."}, {"name": "Front control arms / ball joints", "why": "If the steering feels loose, check these too. See the Control arms guide."}], "check": {"tab": "Is it the tie rod?", "title": "How to find play", "illId": "e36-tierod-hero", "illCap": "Rock the wheel at 9 and 3, not 12 and 6.", "rows": [{"see": "Play when you rock the wheel side to side", "means": "Tie rod end or inner rod.", "do": "Watch the joint while an assistant rocks it, then replace both."}, {"see": "Play when you rock the wheel top and bottom", "means": "Ball joint or wheel bearing.", "do": "Check the control arm and bearing next."}, {"see": "Clunk when turning at parking speeds", "means": "Inner rod or rack mount.", "do": "Inspect the inner rod and rack bushings."}], "c": {"level": "medium", "n": 2, "note": "Standard steering play checks."}}, "aftercare": ["Get the alignment immediately.", "Re-check the lock nut after the first 100 miles.", "Look at the boots after a month."], "disagreements": [{"topic": "Assembly or outer ends only", "pos": "Turner recommends replacing inner and outer together, since an all-new assembly aligns more easily.", "call": "Replace the assembly. Outer-only is a cheaper short-term fix."}], "sources": ["Turner Motorsport — E36 M3 tie rods (assembly fitment, rack stops, replace-together advice)", "e30zone wiki — steering rack conversions (17 mm outer nut, don''t touch the adjustment nut)", "Garagistic — E36 bolt torque guide (inner 52, outer 33, lock nut 26 ft-lb)", "Owner steering rack write-ups (R3VLimited E36 rack swap)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-camber-plates', '{"id": "e36-camber-plates", "title": "Front camber plates", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Other E36 six-cylinders use a different part", "category": "Suspension", "kind": "upgrade", "heroId": "e36-camber-hero", "heroCap": "A camber plate sits on top of the factory strut mount and shifts the top of the strut inward, which tilts the wheel''s top edge in.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$150–500", "risk": "Compressed spring · undercoating between plate and tower", "why": "Lowering takes camber away from the front end. A plate puts it back. Turner''s fixed plates add about 2° of negative camber and bolt on top of the stock mount.", "note": "You''re already taking the strut off the car. This pairs with new dampers or springs."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "You fit it when the alignment runs out of camber"], "earliest": "When the shop says it can''t get the front camber in spec after lowering", "detail": "Plates don''t wear on a street car. The bearing and strut mount underneath do. Fit plates when you already have the strut apart.", "factors": ["Lowering", "Wider wheels", "Track use"], "inspect": ["Ask the shop what camber it can reach on the front"], "confidence": {"level": "single", "n": 1, "note": "Turner''s maker sheet is the only specific source."}}, "should": {"yesIf": ["The car is lowered and the front tires wear on the outside edge", "The alignment shop can''t reach spec camber", "You drive on a track or autocross and want more negative camber"], "codes": [], "notes": ["If you''re not lowered and the car aligns fine, you don''t need these."], "confidence": {"level": "medium", "n": 2, "note": "Maker instructions and alignment advice agree."}}, "variants": {"questions": [{"question": "Which kind of plate?", "hint": "Fixed plates give a set amount. Adjustable plates let the shop or you move the strut for more or less camber.", "options": [{"id": "cfixed", "label": "Turner fixed plates", "when": "Bolts on, adds about 2° negative", "brand": true}, {"id": "cadj", "label": "Adjustable plates", "when": "Vorshlag, Ground Control, TC Kline or another"}]}]}, "parts": [{"tier": "aftermarket", "name": "Turner E36 M3 fixed camber plates", "pn": "Pair with studs pressed in, six flat-head M8 Allen bolts", "price": "See Turner", "note": "Bolts on top of the factory upper strut bearing. Fits the M3 and MZ3.", "only": ["cfixed"]}, {"tier": "aftermarket", "name": "Adjustable camber plates", "price": "$250–600", "note": "Vorshlag, Ground Control and TC Kline are the usual names. Confirm they fit the M3 strut and your coilover or damper before buying.", "only": ["cadj"]}, {"tier": "oe", "name": "Strut bearings", "price": "$40–100 each", "note": "Replace if they''re notchy. The 1995 M3 bearings are the same left and right, the 1996–99 are handed.", "only": ["cfixed", "cadj"]}], "aftermarket": [{"name": "Vorshlag", "note": "Adjustable. Check M3 fitment.", "price": "See Vorshlag", "only": ["cadj"]}, {"name": "Ground Control", "note": "Adjustable plates, designed for their coilover kit.", "price": "See Ground Control", "only": ["cadj"]}, {"name": "TC Kline", "note": "Adjustable plates and kits. Check that they suit your dampers.", "price": "See TC Kline", "only": ["cadj"]}], "tools": [{"name": "Quality spring compressor", "note": "Jaws on both sides, rated for strut springs", "price": "$60–150"}, {"name": "Strut nut socket and Allen key", "note": "To hold the shaft", "price": "$30"}, {"name": "Floor jack, jack stands, second jack", "note": "To support the car and the hub", "price": "$200+"}, {"name": "Torque wrench", "note": "Covers 16 to 105 Nm", "price": "$60–100"}], "before": ["Do this while the strut is out for new dampers or springs. It''s the same job.", "Clean any undercoating off the tower surface where the plate sits.", "Check which side is left and which is right on 1996–99 cars."], "steps": [{"title": "Take the front strut out", "blocks": [{"t": "text", "b": "Follow the same removal as in the coilover guide. Disconnect the brake line clip, ABS wire and sway bar link, support the hub, take out the strut-to-hub fasteners, and take off the three flange nuts at the top."}, {"t": "ill", "id": "e36-camber-hero", "cap": "The plate sits between the strut mount and the tower. Check the arrow and decal direction."}]}, {"title": "Open the strut", "caution": true, "blocks": [{"t": "warn", "b": "A compressed spring stores enough energy to cause serious injury. Use a proper compressor with a jaw on each side and never loosen the top nut until the spring is fully captured."}, {"t": "text", "b": "Compress the spring and take off the shaft nut."}, {"t": "warn", "b": "Don''t over-tighten the strut shaft nut. Hold the shaft with an Allen key and use a socket made for the job. Too much torque can snap the piston rod."}]}, {"title": "Fit the plates to the strut mount", "blocks": [{"t": "text", "b": "Bolt the plate to the top of the factory strut mount. Look at the top of the strut bearing: the arrows should face the front and outward. The decal on the Turner plate faces the front."}, {"t": "torque", "label": "Plate nuts", "nm": 24, "c": {"level": "single", "n": 1, "note": "Turner''s M3 instructions give 24 Nm (16 ft-lb) for the M8 nylock nuts."}, "note": "M8 nylock"}, {"t": "text", "b": "Test-fit the assembled mount to the tower before reassembling the strut. Make sure no undercoating is trapped between plate and tower."}], "only": ["cfixed"]}, {"title": "Fit the plates (adjustable)", "blocks": [{"t": "text", "b": "Follow the maker''s sheet for the order of parts. Mark the plate''s slot position with paint pen so you can set it back after the alignment."}, {"t": "note", "b": "Adjustable plates are commonly set once, then locked after the shop dials in the camber."}], "only": ["cadj"]}, {"title": "Reassemble and refit the strut", "blocks": [{"t": "text", "b": "Rebuild the strut with the plate fitted and refit it to the car."}, {"t": "torque", "label": "Strut shaft nut (internal hex)", "nm": 45, "c": {"level": "single", "n": 2, "note": "Z3 owner thread, same strut family: 33 ft-lb."}, "note": "33 ft-lb"}, {"t": "torque", "label": "Strut shaft nut (external hex)", "nm": 65, "c": {"level": "single", "n": 2, "note": "Same thread: 48 ft-lb."}, "note": "48 ft-lb"}, {"t": "torque", "label": "Strut tower flange nuts", "nm": 24, "c": {"level": "high", "n": 2, "note": "Turner (24 Nm) and Dinan (18 ft-lb, about 24 Nm) agree for the E36 M3."}, "note": "all three"}, {"t": "torque", "label": "Strut to hub", "nm": 105, "c": {"level": "high", "n": 3, "note": "Turner (105 Nm), FCP Euro (107 Nm) and an owner thread (78 ft-lb) agree."}, "note": "both lower bolts and the upper bolt"}]}, {"title": "Get the alignment", "caution": true, "blocks": [{"t": "text", "b": "Plates change camber and move the toe. Book an alignment as soon as the car is on the ground. Tell the shop you''ve fitted them and what you want."}, {"t": "text", "b": "Adjustable plates: ask the shop to lock the plate after setting camber.", "only": ["cadj"]}]}], "alsoReplace": [{"name": "Strut bearings and mounts", "why": "They''re apart already. Notchy or noisy ones add steering feel problems."}, {"name": "Coilovers or new dampers", "why": "If you haven''t done these, do the plate job at the same time."}], "check": {"tab": "Need plates?", "title": "Do you need plates?", "illId": "e36-camber-hero", "illCap": "Check tire wear before you buy.", "rows": [{"see": "Outer front tire edge wears faster than the inside", "means": "Not enough negative camber, or the toe is out.", "do": "Get an alignment first. If camber is maxed, fit plates."}, {"see": "Shop says camber can''t be set in spec", "means": "Out of adjustment range.", "do": "Fit plates."}, {"see": "Car is stock height and aligns fine", "means": "No need.", "do": "Skip the plates."}], "c": {"level": "medium", "n": 2, "note": "Typical alignment advice."}}, "aftercare": ["Re-torque the strut top nuts after the first 100 miles.", "Check tire wear after a few hundred miles.", "If you used adjustable plates, re-check the slot marks."], "disagreements": [{"topic": "Fixed or adjustable", "pos": "Fixed plates are cheap and simple. Adjustable plates let you tune camber later.", "call": "Street car: fixed is fine. Track or changing setups: adjustable."}], "sources": ["Turner Motorsport — E36 M3/MZ3 fixed camber plate instructions (about 2°, torques, orientation, undercoating)", "Turner Motorsport — fitment and class legality notes", "Vorshlag, Ground Control, TC Kline — product pages for adjustable options; M3 fitment to be confirmed by the buyer"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-coilovers', '{"id": "e36-coilovers", "title": "Coilovers, springs & dampers", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Other 1992–1999 E36 six-cylinders share the layout but not the part numbers or the M3 strut", "category": "Suspension", "kind": "upgrade", "heroId": "e36-coil-hero", "heroCap": "Two routes to the same ride: replace the whole strut and shock with a coilover kit, or keep the stock layout and swap new springs and dampers into it.", "glance": {"timeFirst": "6–10 hr", "timeRepeat": "4–5 hr", "difficulty": 3, "cost": "$700–2,500", "risk": "Compressed spring · over-lowering · the rear brake line running out of slack", "why": "Fresh dampers and springs are the biggest single change you can make to how an E36 M3 drives. The route you pick sets the price, ride height range and whether you also need new mounts.", "note": "Whatever you fit, plan for an alignment afterwards. Lowering changes camber and toe, front and rear."}, "lifespan": {"title": "When to expect it", "headline": ["Original-spec dampers last roughly 60–100k miles", "On a car this old they''re past due either way"], "earliest": "Bounce and float after bumps, nose dive under braking, or leaking oil on the damper body", "detail": "Most E36 M3s have had at least one set of dampers by now, and rubber mounts, spring pads and bump stops age with them. Replace the whole stack at once, not just one part.", "factors": ["Age and mileage", "Rough roads", "Lowering on worn-out mounts", "Track use"], "inspect": ["Push down hard on each corner and see if it settles in one bounce", "Look for oil on the damper body"], "confidence": {"level": "single", "n": 1, "note": "The mileage range is a general rule of thumb, not an E36-specific published interval."}}, "should": {"yesIf": ["The car floats, wallows or dives and the dampers are old or leaking", "You want a lower stance or a firmer, more controlled ride", "You''re building the car for track, autocross or spirited driving", "Your mounts and spring pads are worn and you''d rather replace everything once"], "codes": [], "notes": ["Spring rates, ride height and damping are a package. A cheap coilover on a stiff setting can be worse than good dampers with mild springs.", "A new sway bar and camber plates make the most sense after this, not before."], "confidence": {"level": "medium", "n": 5, "note": "Turner, BimmerWorld and Bilstein agree on the package approach."}}, "variants": {"questions": [{"question": "Which route are you taking?", "hint": "Coilovers replace the strut and the shock with height-adjustable units. Springs and dampers keep the factory layout.", "options": [{"id": "coils", "label": "Coilovers", "when": "Height-adjustable kit, one box"}, {"id": "sprdamp", "label": "Springs + dampers", "when": "Lowering springs with new sport dampers"}]}, {"question": "Does the kit bring its own mounts?", "hint": "Some kits use the stock strut mounts and bearings, others supply their own with camber plates.", "options": [{"id": "stockmounts", "label": "Reuses stock mounts", "when": "e.g. Bilstein PSS9, most spring-and-damper combos"}, {"id": "ownmounts", "label": "Brings its own mounts", "when": "e.g. Ground Control, TC Kline, most race kits"}]}]}, "parts": [{"tier": "aftermarket", "name": "Bilstein B16 PSS9 coilover kit", "pn": "1996–99 M3 and 1995 M3 are different kits", "price": "$1,800–2,500", "note": "Works with the stock mounts and sway bar links, 9-position damping, spanner wrenches included. Not for cars with factory EDC shocks.", "only": ["coils+stockmounts"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-344018-bilstein/"}]}, {"tier": "aftermarket", "name": "Coilover kit with its own mounts", "price": "$1,000–2,500", "note": "Ground Control (Koni inserts), TC Kline, KW, BC and others. Follow the maker''s sheet where it differs.", "only": ["coils+ownmounts"]}, {"tier": "aftermarket", "name": "Sport dampers, front and rear", "pn": "Bilstein B6/B8 · Koni Sport", "price": "$600–1,000", "note": "Bilstein B8 Performance Plus is sold for lowered cars. E36 M3 front Bilsteins come as a complete strut assembly.", "only": ["sprdamp"]}, {"tier": "aftermarket", "name": "Lowering springs", "pn": "H&R · Eibach · Dinan", "price": "$250–400", "note": "Match the spring to the damper. Eibach''s Pro Kit pairs its springs with Bilstein Sport shocks.", "only": ["sprdamp"]}, {"tier": "oe", "name": "Front strut mounts and bearings", "price": "$100–250 pair", "note": "Replace with new dampers. The 1995 M3 mounts are the same left to right, the 1996–99 are handed.", "only": ["stockmounts"]}, {"tier": "oe", "name": "Rear shock mounts", "price": "$50–200 pair", "note": "See the Rear shock mounts guide for the upgrade options.", "only": ["stockmounts", "sprdamp"]}, {"tier": "oe", "name": "Spring pads and bump stops", "price": "$30–80", "note": "New with new springs. Old ones squash flat and change ride height."}], "aftermarket": [{"name": "Bilstein B16 PSS9", "note": "9-position damping, uses stock mounts, TUV approved. Progressive springs. Ordered separately for 1995 and 1996–99 M3.", "price": "See Turner", "signal": "Easiest big-brand kit", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-554-bmw-coilovers/m-23-bilstein"}], "only": ["coils"]}, {"name": "Ground Control + Koni", "note": "Race-oriented setup. The insert is shorter than the stock housing, so they supply their own housings. Needs camber plates.", "price": "See Ground Control", "only": ["coils"]}, {"name": "Bilstein B8 Performance Plus with H&R or Eibach springs", "note": "A common street pairing for lowered cars.", "price": "$850–1,300", "only": ["sprdamp"]}, {"name": "Koni Sport with H&R OE Sport springs", "note": "One owner pairs Koni Sport with H&R and reports a tight feel with fronts and a Porsche-valved rear Koni.", "price": "See retailer", "only": ["sprdamp"]}], "tools": [{"name": "Quality spring compressor", "note": "Jaws with safety lips on both sides. Rent or buy one made for struts.", "price": "$60–150"}, {"name": "Strut nut socket and Allen key", "note": "To hold the shaft while tightening the top nut", "price": "$30"}, {"name": "Floor jack, four jack stands, a second jack", "note": "To lift the car and to support the hub or trailing arm", "price": "$200+"}, {"name": "Torque wrench (1/2 in, up to ~110 Nm)", "note": "For the hub and shock bolts", "price": "$60–100"}, {"name": "Spanner wrenches (often supplied)", "note": "To set coilover height", "price": "Included"}], "before": ["Do this on a dry day with a long weekend. A first-timer should plan a full day per axle.", "Soak the strut, hub and lower shock bolts in penetrating oil the night before.", "Know your tire and wheel clearances before you set a ride height.", "Book the alignment for the day after. You can''t drive far on a bad one."], "chapters": [{"id": "front", "title": "Front axle", "blurb": "Remove the strut, swap the spring and damper or the whole coilover, put it back."}, {"id": "rear", "title": "Rear axle", "blurb": "The rear spring and shock are separate. Both come out, both go back in."}, {"id": "finish", "title": "Ride height & alignment", "blurb": "Settle it, set it, then align."}], "steps": [{"chapter": "front", "title": "Loosen the wheel nuts, then lift the front", "blocks": [{"t": "text", "b": "Crack the lug nuts while the car is on the ground. Chock the rear wheels, jack the front and put the car on stands. Take the wheels off."}]}, {"chapter": "front", "title": "Free the strut from the car", "timeSink": true, "blocks": [{"t": "text", "b": "Unclip the brake line and ABS wire from the strut so nothing pulls when it drops. Take the sway bar link off its bracket on the strut, holding the stud with a wrench while you turn the nut."}, {"t": "text", "b": "Support the hub with a jack. Take out the two lower bolts and the upper nut and bolt that join the strut to the hub (Turner''s instructions for the M3 describe this layout)."}, {"t": "ill", "id": "e36-coil-strut", "cap": "The strut stack, top to bottom: nut, mount and bearing, spring pad, spring, bump stop, damper."}]}, {"chapter": "front", "title": "Take the strut out of the car", "blocks": [{"t": "text", "b": "Under the hood, take off the three flange nuts on top of the strut tower while holding the strut from below. Lower the strut and pull it out through the wheel arch."}]}, {"chapter": "front", "title": "Swap the spring and damper", "caution": true, "blocks": [{"t": "warn", "b": "A compressed spring stores enough energy to cause serious injury. Use a proper compressor with a jaw on each side and never loosen the top nut until the spring is fully captured."}, {"t": "text", "b": "Compress the spring until the top mount is loose, then take off the shaft nut, mount and bearing."}, {"t": "warn", "b": "Don''t over-tighten the strut shaft nut. Hold the shaft with an Allen key and use a socket made for the job. Too much torque can snap the piston rod."}, {"t": "torque", "label": "Strut shaft nut (internal hex)", "nm": 45, "c": {"level": "single", "n": 2, "note": "A Z3 owner thread (same strut family) gives 33 ft-lb for an internal-hex nut."}, "note": "33 ft-lb"}, {"t": "torque", "label": "Strut shaft nut (external hex)", "nm": 65, "c": {"level": "single", "n": 2, "note": "The same thread gives 48 ft-lb for an external-hex nut."}, "note": "48 ft-lb"}, {"t": "text", "b": "Fit the new damper, a new bump stop and boot, a new spring pad and the new spring, and put the mount and bearing back on. With a coilover that reuses the stock mount, the assembly goes together the same as the factory strut.", "only": ["coils+stockmounts"]}, {"t": "text", "b": "A coilover kit with its own mounts goes together the way its sheet shows. Follow it for the order of parts and where each nut sits.", "only": ["coils+ownmounts"]}, {"t": "text", "b": "The new strut stack goes together in the same order as the old one. Take a photo before you take the old one apart.", "only": ["sprdamp"]}]}, {"chapter": "front", "title": "Fit the strut and torque it", "blocks": [{"t": "text", "b": "Raise the strut into the tower and fit the three flange nuts. Reconnect the strut to the hub and the sway bar link."}, {"t": "torque", "label": "Strut tower flange nuts", "nm": 24, "c": {"level": "high", "n": 2, "note": "Turner (24 Nm) and Dinan (18 ft-lb, about 24 Nm) agree for the E36 M3."}, "note": "all three"}, {"t": "torque", "label": "Strut to hub", "nm": 105, "c": {"level": "high", "n": 3, "note": "Turner (105 Nm), FCP Euro (107 Nm) and an owner thread (78 ft-lb) agree."}, "note": "both lower bolts and the upper bolt"}, {"t": "torque", "label": "Sway bar link to strut bracket", "nm": 59, "c": {"level": "medium", "n": 3, "note": "Bentley list gives 44 ft-lb for the M3. Doug''s Domain says TIS gives 59 Nm."}}, {"t": "note", "b": "Tighten the hub bolts with threadlocker where the kit says to, and replace the strut-to-hub bolts if the manual or kit calls for new ones."}]}, {"chapter": "rear", "title": "Lift the rear and take the wheels off", "blocks": [{"t": "text", "b": "Crack the lug nuts, chock the front wheels and jack the rear onto stands under the frame rails. Take the wheels off."}]}, {"chapter": "rear", "title": "Support the trailing arm and unbolt the shock", "blocks": [{"t": "text", "b": "Put a jack under the trailing arm so it doesn''t drop. Take out the lower shock bolt."}, {"t": "text", "b": "Open the top mount from inside the trunk: take off the tail light covers, fold the carpet liner back and remove the two 13 mm nuts. That''s the coupe layout described by owner write-ups. A sedan or convertible may need more trim removed."}]}, {"chapter": "rear", "title": "Lower the arm and swap the spring", "caution": true, "blocks": [{"t": "warn", "b": "Don''t let the trailing arm hang. The brake line and ABS wire only have so much slack."}, {"t": "text", "b": "Lower the jack slowly until the spring can be lifted out, with its pad and bump stop. Fit the new spring with a new pad and bump stop, and bring the arm back up."}]}, {"chapter": "rear", "title": "Fit the new shock and torque it", "blocks": [{"t": "text", "b": "Move the top mount over to the new shock if it''s reused, then feed the shock through the spring and fit the mount to the body. Tighten the lower bolt at ride height."}, {"t": "torque", "label": "Shock shaft nut to mount", "nm": 14, "c": {"level": "medium", "n": 2, "note": "Pelican''s rear overhaul (from the Bentley) gives 10 ft-lb. One owner guide says 13 ft-lb."}, "note": "be gentle: it''s only about 10 ft-lb"}, {"t": "torque", "label": "Rear upper mount nuts", "nm": 24, "c": {"level": "high", "n": 3, "note": "Pelican 17 ft-lb, FCP Euro 25 Nm, and an owner guide''s 18 ft-lb agree."}, "note": "two nuts per side"}, {"t": "torque", "label": "Rear shock to trailing arm", "nm": 77, "c": {"level": "high", "n": 3, "note": "ECS (77 Nm), Pelican (57 ft-lb) and the Bentley list agree. FCP''s coilover page lists 100 Nm, which doesn''t match."}, "note": "at ride height"}]}, {"chapter": "finish", "title": "Settle the car and set the height", "blocks": [{"t": "text", "b": "Put the wheels on and lower the car. Roll it forward and back a few feet and bounce each corner to settle the suspension."}, {"t": "torque", "label": "Wheel bolts", "nm": 100, "c": {"level": "medium", "n": 2, "note": "Bentley E36 list gives 74 ft-lb (about 100 Nm). Some wheel makers specify differently, so follow yours if it does."}, "note": "star pattern, car on the ground"}, {"t": "text", "b": "On a coilover kit, set the ride height with the spanner wrenches. Measure from the center of the hub to the fender lip on each corner and keep both sides equal.", "only": ["coils"]}, {"t": "text", "b": "Springs sit at a fixed height. Let them settle for a few days before judging the stance or booking the alignment.", "only": ["sprdamp"]}]}, {"chapter": "finish", "title": "Book the alignment", "caution": true, "blocks": [{"t": "text", "b": "A lowered car needs an alignment before you put real miles on it. Front and rear camber and toe will all have moved."}, {"t": "note", "b": "If the front camber won''t come into spec, that''s when camber plates make sense. See the Camber plates guide. Rear camber is in the rear camber and toe guide."}]}], "alsoReplace": [{"name": "Front strut mounts and bearings", "why": "They''re off the car anyway, and tired ones add noise and wander."}, {"name": "Rear shock mounts and reinforcement", "why": "Weak rear mounts and cracked towers are the main E36 rear-end failure. Fix them now. See the RSM guide."}, {"name": "Spring pads, bump stops and boots", "why": "Cheap, and old ones change ride height and noise."}, {"name": "Sway bar links", "why": "A new height changes the bar''s preload. Adjustable links solve it."}], "check": {"tab": "Worn or fine?", "title": "Do your dampers need replacing?", "illId": "e36-coil-hero", "illCap": "A few checks you can do in the driveway.", "rows": [{"see": "Car keeps bouncing after you push down hard on a corner", "means": "Worn damper.", "do": "Replace in pairs, front or rear."}, {"see": "Oil weeping on the damper body", "means": "Failed seal.", "do": "Replace that damper and its partner."}, {"see": "Clunk or rattle over bumps with no leak", "means": "Top mount or bump stop.", "do": "Check those before spending on dampers."}], "c": {"level": "medium", "n": 3, "note": "Standard damper checks."}}, "aftercare": ["Re-torque the strut and shock bolts after the first 100 miles.", "Check ride height again after a week of settling, then fix it if it''s off.", "Get the alignment done and keep the printout."], "disagreements": [{"topic": "Coilovers or springs and dampers", "pos": "Coilovers give you adjustability. Springs and sport dampers cost less and keep a stock ride quality.", "call": "Street car: springs and dampers. Track or stance: coilovers."}, {"topic": "Spring rate", "pos": "One owner runs 500 lb rear springs, about 25% stiffer than H&R Sports, and likes it. Others find that too stiff for the street.", "call": "Start with a matched kit. Go stiffer only if you track the car."}], "sources": ["Turner Motorsport — Bilstein B16 PSS9 for E36 M3 (stock mounts and links, EDC note, 1995 vs 1996–99)", "Turner Motorsport — Bilstein E36 M3 B6/B8 and Eibach Pro Kit descriptions", "Turner Motorsport — E36 M3 fixed camber plate instructions (strut torque, shaft nut warning)", "Bimmerforums — Ground Control inserts and Koni rear shock thread", "ECS — E36 rear suspension torque specifications (77 Nm shock bolt)", "Pelican Parts — E36 rear suspension overhaul (10 ft-lb shaft nut, 17 ft-lb upper nuts, 57 ft-lb lower bolt)", "FCP Euro — E36 coilover install (upper nuts 25 Nm, front strut bolts 107 Nm)", "Bentley E36 list as posted on Club Cobra", "Bimmerfest — front strut torque thread (shaft nut by hex type)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-endlinks', '{"id": "e36-endlinks", "title": "Sway bar end links", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Rear links also fit other E36 six-cylinders; the front M3 link is its own part", "category": "Suspension", "kind": "repair", "heroId": "e36-links-hero", "heroCap": "The M3''s front link goes from the bar up to a bracket on the strut. The rear link goes from the bar up to the rear upper control arm. The M3''s front link is not the same part as a 325i''s.", "glance": {"timeFirst": "45 min–1.5 hr", "timeRepeat": "30 min", "difficulty": 1, "cost": "$50–200", "risk": "Ball stud spinning with the nut · wrong link for the M3", "why": "A worn end link is one of the cheapest fixes for a clunk on an E36 M3. Adjustable links are also the right fix for a lowered car that fights its sway bar.", "note": "Turner says front link ball joint failure on the M3 is something that can''t be avoided. Replace them in pairs."}, "lifespan": {"title": "When to expect it", "headline": ["No fixed interval", "Replace when there''s play or a clunk"], "earliest": "Often the first thing to clunk on a twenty-year-old E36", "detail": "The ball joint at each end wears until it knocks over bumps. There''s no published mileage. The test is to pry on the link and feel for play.", "factors": ["Age", "A lowered car with links pulled to the wrong length", "Torn boots letting grit in"], "inspect": ["Pry on each link with a bar", "Look for torn boots"], "confidence": {"level": "single", "n": 1, "note": "Only retailers describe the failure, with no mileage figures."}}, "should": {"yesIf": ["You hear a clunk or knock over bumps", "A boot is torn or a link has visible play", "You''ve lowered the car or fitted a new bar and need the links to fit", "You want adjustable links to remove sway bar preload"], "codes": [], "notes": ["Do the pair on each axle at the same time. If one is gone the other is close behind."], "confidence": {"level": "medium", "n": 2, "note": "Retailer and owner advice agree."}}, "variants": {"questions": [{"question": "Which end of the car?", "hint": "The front and rear parts are different.", "options": [{"id": "front", "label": "Front links", "when": "Bar to strut"}, {"id": "rear", "label": "Rear links", "when": "Bar to rear control arm"}]}, {"question": "Stock length or adjustable?", "hint": "Adjustable links let you set the bar''s preload by length. They''re the usual choice when the car is lowered.", "options": [{"id": "oelink", "label": "Stock replacement", "when": "OE-style Lemförder or Meyle", "oeOnly": true}, {"id": "adjlink", "label": "Adjustable", "when": "Set length yourself, for lowered cars or new bars"}]}]}, "parts": [{"tier": "oe", "name": "Front sway bar link, M3 (each)", "pn": "31352227203 (Lemförder) · 31352227203MY (Meyle HD)", "price": "$25–45", "note": "The M3 front link. A 325i link (31351091764) is a different part.", "only": ["front+oelink"]}, {"tier": "oe", "name": "Rear sway bar link (each)", "pn": "33551126932 (alt 33551124375)", "price": "$20–35", "note": "Lemförder. Replace in a pair.", "only": ["rear+oelink"]}, {"tier": "aftermarket", "name": "Adjustable front links (pair)", "pn": "Turner TMS2104 · ECS 053153LA01 (215–275 mm)", "price": "$80–150", "note": "10 mm studs. Set length to remove preload.", "only": ["front+adjlink"]}, {"tier": "aftermarket", "name": "Adjustable rear links (pair)", "pn": "Turner TSU9913RS2", "price": "$70–130", "note": "Rod-end style, length-adjustable.", "only": ["rear+adjlink"]}], "aftermarket": [{"name": "Turner adjustable front links", "note": "Custom-length, 10 mm studs, quiet like stock links but with rod-end strength.", "price": "See Turner", "signal": "Direct OE replacement", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-1236-bmw-front-end-links"}], "only": ["front"]}, {"name": "ECS adjustable front links", "note": "215–275 mm, up to about 60 mm of adjustment.", "price": "See ECS", "only": ["front"]}, {"name": "Turner adjustable rear links", "note": "Length-adjustable, for lowered cars.", "price": "See Turner", "only": ["rear"]}], "tools": [{"name": "Wrench set and a thin wrench or Allen key", "note": "To hold the ball stud still while turning the nut", "price": "$30"}, {"name": "Jack and stands", "note": "Rated for the car", "price": "$150+"}, {"name": "Torque wrench", "note": "To finish the nuts", "price": "$40–70"}], "before": ["Check which link you actually need. M3 front links differ from a 325i''s.", "Replace left and right at the same time.", "If you''re fitting adjustable links, measure the old link center to center first."], "steps": [{"title": "Jack the car and take the wheel off", "blocks": [{"t": "text", "b": "Chock the other axle, jack the car and put it on stands. Take off the wheel on the side you''re working on."}]}, {"title": "Hold the stud, turn the nut (front)", "blocks": [{"t": "text", "b": "Take off the nut at each end of the front link. Hold the stud with a wrench while you turn the nut, or the ball stud just spins."}, {"t": "ill", "id": "e36-links-hero", "cap": "Hold the stud with a wrench; the ball joint will spin if you don''t."}], "only": ["front"]}, {"title": "Hold the stud, turn the nut (rear)", "blocks": [{"t": "text", "b": "Take the nuts off at both ends of the rear link. Hold the stud with a wrench while you turn the nut, or the ball stud just spins. Use a narrow spanner on the stud flats."}], "only": ["rear"]}, {"title": "Compare and set the new link", "blocks": [{"t": "text", "b": "Hold the new link next to the old one. Same length, same stud size."}, {"t": "text", "b": "For adjustable links, set the length to match the old link as a starting point, then adjust once the car is on the ground.", "only": ["adjlink"]}]}, {"title": "Fit the new links", "blocks": [{"t": "text", "b": "Fit the link to the bar and to the arm and snug the nuts. Don''t force the bar to line up. If you can''t get a stud into its hole without pulling the bar, the length is wrong."}]}, {"title": "Set preload with the car on the ground", "caution": true, "blocks": [{"t": "text", "b": "Lower the car to ride height and bounce it. The link should hang with no sideways pressure on the bar. With adjustable links, lengthen or shorten until the bar sits neutral, then lock the jam nuts."}, {"t": "torque", "label": "Front link to strut bracket nut", "nm": 59, "c": {"level": "medium", "n": 3, "note": "Bentley list gives 44 ft-lb for the M3. Doug''s Domain says TIS gives 59 Nm for all E36."}, "note": "hold the stud", "only": ["front"]}, {"t": "torque", "label": "Front link to bar nut", "nm": 42, "c": {"level": "medium", "n": 2, "note": "Garagistic and Pelican both give 31 ft-lb for the M10 nut."}, "only": ["front"]}, {"t": "torque", "label": "Rear link nuts", "nm": 41, "c": {"level": "single", "n": 2, "note": "Pelican says 30 ft-lb. Doug''s Domain says 44 ft-lb."}, "note": "30 ft-lb, or up to 44", "alt": [59], "only": ["rear"]}, {"t": "note", "b": "Adjustable links often come with their own torque for the rod-end jam nuts. Use the maker''s sheet for those."}]}], "alsoReplace": [{"name": "Sway bar bushings", "why": "The bar is right there. If the bushings are split, it''s a few minutes more."}, {"name": "Front lower control arm bushings", "why": "If you''re chasing a clunk, check these before you assume it was only the link."}], "check": {"tab": "Is it the link?", "title": "Link test", "illId": "e36-links-hero", "illCap": "A simple pry test finds a worn link.", "rows": [{"see": "Link moves or rattles when pried", "means": "Worn ball joint.", "do": "Replace both on that axle."}, {"see": "Link is tight but you still hear a clunk", "means": "Bushing, control arm or damper.", "do": "Check those next."}, {"see": "Link fits only with the bar bent", "means": "Wrong length for the ride height.", "do": "Fit adjustable links."}], "c": {"level": "medium", "n": 2, "note": "Standard end link diagnosis."}}, "aftercare": ["Re-check the nuts after the first drive.", "Look at preload again after any spring or ride height change."], "disagreements": [{"topic": "Stock links on a lowered car", "pos": "Some owners run stock-length links on a mild drop and see no problem. Retailers recommend adjustable links.", "call": "If the links go on without forcing the bar, stock is fine. If not, go adjustable."}], "sources": ["Turner Motorsport — E36 M3 front and rear end links (part numbers, failure note)", "ECS — adjustable front sway bar end links (215–275 mm)", "Ground Control — E36 sway bar directions (link length set last)", "Bentley E36 list as posted on Club Cobra", "Doug''s Domain — E36 swaybar service (59 Nm link nut per TIS)", "Pelican Parts — E36 front and rear sway bar link articles", "Garagistic — E36 bolt torque guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-rear-camber-toe', '{"id": "e36-rear-camber-toe", "title": "Rear camber & toe correction", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Other E36 six-cylinders share the multilink layout; the Compact and Z3 use a different rear", "category": "Suspension", "kind": "upgrade", "heroId": "e36-rcamber-hero", "heroCap": "Lowering pulls the rear wheels into negative camber and changes toe. The factory eccentric on the lower arm only goes so far.", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$250–600", "risk": "Parts that don''t fit the M3 · torquing at the wrong height", "why": "A lowered E36 often runs out of rear camber. Adjustable lower arms give the alignment shop more range. Toe parts are the confusing bit, because some listings don''t fit the M3.", "note": "Do this after the rear spring and shock work. The shop will need a car at final ride height."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Needed when the rear won''t align after lowering"], "earliest": "The alignment printout shows rear camber or toe out of range with no adjustment left", "detail": "Rear tires wear on the inside edge when camber or toe is out. The shop will tell you when the factory adjustment is used up.", "factors": ["Lowering", "Worn arm bushings", "Wider tires"], "inspect": ["Look at the inside edge of the rear tires", "Read the alignment printout"], "confidence": {"level": "single", "n": 1, "note": "Based on retailer and alignment-article descriptions."}}, "should": {"yesIf": ["The rear tires wear on the inside edge", "The shop can''t get rear camber into spec after lowering", "You''re building a track car and want rear adjustability"], "codes": [], "notes": ["A change in camber also changes toe, so the shop sets camber first, then toe."], "confidence": {"level": "medium", "n": 2, "note": "Alignment article and retailer notes agree."}}, "variants": {"questions": [{"question": "What do you want to do?", "hint": "Many cars only need the factory eccentric and a good alignment.", "options": [{"id": "shop", "label": "Alignment shop only", "when": "Use the factory adjustments", "oeOnly": true}, {"id": "arms", "label": "Adjustable rear arms", "when": "More camber range"}]}]}, "parts": [{"tier": "aftermarket", "name": "Adjustable rear control arms (pair)", "pn": "ECS adjustable rear arms (E36/E46)", "price": "$250–500", "note": "ECS''s install notes include an M3-only step to remove the rear reinforcing brace.", "only": ["arms"]}, {"tier": "oe", "name": "Eccentric bolts and nuts", "price": "$10–30", "note": "Replace rusted ones. The eccentric on the lower arm sets camber.", "only": ["shop", "arms"]}], "aftermarket": [{"name": "ECS adjustable rear control arms", "note": "Fit E36 and E46. Check M3 notes before ordering.", "price": "See ECS", "only": ["arms"], "links": [{"store": "ECS", "url": "https://blog.ecstuning.com/diy-bmw-e36-or-e46-ecs-adjustable-control-arms/"}]}], "tools": [{"name": "Jack stands and jack", "note": "Rated for the car", "price": "$150+"}, {"name": "Torque wrench", "note": "Up to 110 Nm", "price": "$60–100"}, {"name": "Wrench set", "note": "Large combination wrenches for the eccentric bolt", "price": "$40"}], "before": ["Settle the ride height first. This job is only worth doing once.", "Tell the alignment shop what you''ve fitted and ask for a printout.", "Soak the eccentric bolts in penetrating oil the night before."], "steps": [{"title": "Check what the shop can reach", "blocks": [{"t": "text", "b": "Get an alignment printout. If the rear camber and toe are in range, you don''t need new parts."}, {"t": "ill", "id": "e36-rcamber-hero", "cap": "Camber is the tilt of the wheel top. Toe is how far the fronts point in or out."}], "only": ["shop", "arms"]}, {"title": "Lift the rear and take the wheels off", "blocks": [{"t": "text", "b": "Chock the front wheels, jack the rear and set the car on stands. Remove the wheels."}], "only": ["arms"]}, {"title": "Fit the adjustable arms", "caution": true, "blocks": [{"t": "text", "b": "Take out the lower control arm bolts, one arm at a time. ECS''s instructions for the M3 add a step to take off the rear reinforcing brace first."}, {"t": "text", "b": "Fit the new arm in the same position. Tighten the bolts only after the car is on the ground at ride height."}, {"t": "torque", "label": "Lower arm to trailing arm (eccentric)", "nm": 110, "c": {"level": "medium", "n": 2, "note": "ECS lists 110 Nm (81 ft-lb) for the E36 eccentric bolt."}, "note": "at ride height"}, {"t": "torque", "label": "Upper arm to trailing arm", "nm": 110, "c": {"level": "medium", "n": 2, "note": "ECS lists 110 Nm (81 ft-lb)."}}, {"t": "torque", "label": "Upper arm to subframe", "nm": 77, "c": {"level": "medium", "n": 2, "note": "ECS lists 77 Nm (57 ft-lb)."}}], "only": ["arms"]}, {"title": "Go to the alignment shop", "blocks": [{"t": "text", "b": "With the car at ride height, have the shop set rear camber first, then toe. Ask for a printout of before and after."}, {"t": "note", "b": "One retailer''s adjustable toe brackets are listed as not fitting the E36 M3. Check with the maker before buying a toe part. Factory toe adjustment is done by the shop."}]}], "alsoReplace": [{"name": "Rear trailing arm bushings", "why": "Worn bushings change toe and camber. See the Bushings guides."}, {"name": "Rear shocks and springs", "why": "Do those first, then align."}], "check": {"tab": "Tire wear", "title": "What''s the tire telling you?", "illId": "e36-rcamber-hero", "illCap": "Rear tires show alignment problems early.", "rows": [{"see": "Inside edge worn", "means": "Too much negative camber or toe out.", "do": "Get an alignment."}, {"see": "Feathered edges", "means": "Toe is out.", "do": "Set toe."}, {"see": "Even wear", "means": "Fine.", "do": "Nothing."}], "c": {"level": "medium", "n": 2, "note": "Standard tire-wear reading."}}, "aftercare": ["Check the tires after a few hundred miles.", "Recheck torque on the arm bolts after 100 miles."], "disagreements": [{"topic": "Eccentric bushings vs adjustable arms", "pos": "Eccentric bushings can slip out of adjustment. Weld-in tabs and adjustable arms hold their setting.", "call": "Adjustable arms for a car that''s lowered a lot."}], "sources": ["ECS — E36/E46 adjustable rear control arms DIY and torque specs", "Brake & Front End — alignment of 1998–2006 BMW 3 Series (camber first, then toe)", "BimmerWorld — trailing arm camber/toe kit (not for the M3, E30/Z3/318ti only)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-rsm', '{"id": "e36-rsm", "title": "Rear shock mounts & reinforcement", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "E36, E46 and Z3 share the mount and plate family; the convertible needs its own plate", "category": "Suspension", "kind": "repair", "heroId": "e36-rsm-hero", "heroCap": "The rear shock sits in a rubber mount bolted to a thin stamped tower. The mount rots first. The tower cracks if the mount fails and the car is lowered.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$100–400", "risk": "A cracked tower hidden under old mounts · shock dropping if it isn''t supported", "why": "The rear shock mount is the thing that clunks on an E36. Turner and ECS both say reinforcement plates prevent tower cracks on lowered or hard-driven cars, and installing them with the mounts takes almost no extra time.", "note": "Z3 plates fit coupes and sedans. A convertible needs a plate made for it."}, "lifespan": {"title": "When to expect it", "headline": ["Rubber mounts harden and fail with age", "Often well before the dampers do"], "earliest": "A clunk or rattle from the rear on rough roads, or visible cracks in the rubber", "detail": "Rubber mounts soften, then split. A failed mount lets the shaft move, which shows up as a knock and, over time, a cracked tower. Plates stop the tower cracking.", "factors": ["Age", "Lowering", "Hard driving", "Rough roads"], "inspect": ["Look at the mounts through the trunk trim for cracks", "Check the tower for hairline cracks around the bolt holes"], "confidence": {"level": "medium", "n": 3, "note": "Described by Turner, ECS and BimmerWorld; no mileage figure published."}}, "should": {"yesIf": ["You hear a clunk or rattle from the rear", "The mount rubber is cracked or squashed", "The car is lowered or driven hard", "You''re replacing the rear dampers and want to do everything once"], "codes": [], "notes": ["If the tower is already cracked, a plate helps but won''t fix it. Have the crack welded first."], "confidence": {"level": "medium", "n": 3, "note": "Retailer and owner sources agree."}}, "variants": {"questions": [{"question": "What body style is your M3?", "hint": "The reinforcement plate and access differ on a convertible.", "options": [{"id": "cpe", "label": "Coupe or sedan", "when": "Z3-style plates fit"}, {"id": "cvt", "label": "Convertible", "when": "Needs a plate made for the convertible"}]}, {"question": "Which mount do you want?", "hint": "Rubber is quiet. Urethane is firmer. Spherical is for track cars.", "options": [{"id": "rubber", "label": "Heavy-duty rubber", "when": "Meyle HD, Lemförder, OE style", "oeOnly": true}, {"id": "poly", "label": "Polyurethane", "when": "Powerflex, firmer but still street-friendly"}, {"id": "sphere", "label": "Spherical / aluminum", "when": "BimmerWorld, Turner. Track-focused, more noise", "brand": true}]}]}, "parts": [{"tier": "oem", "name": "Heavy-duty rear shock mounts (pair)", "pn": "Meyle HD · Lemförder", "price": "$60–150", "note": "ECS''s complete kit uses Meyle HD mounts from the E46 M3 convertible with gaskets and plates.", "only": ["rubber"]}, {"tier": "aftermarket", "name": "Powerflex rear shock mounts (pair)", "pn": "PFR5-5630-10", "price": "$120–180", "note": "Polyurethane, fit 10 mm-thread dampers. Lifetime warranty.", "only": ["poly"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Urethane-Bushings/Powerflex-Rear-Shock-Mounts-PFR5-5630-10.html"}]}, {"tier": "aftermarket", "name": "BimmerWorld spherical rear mounts (10 mm)", "price": "$200–300", "note": "Aluminum, slotted for tire clearance, stainless plate included. Some convertibles mount the plate underneath.", "only": ["sphere"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Camber-Caster-Parts/10mm-Spherical-Rear-Shock-Mounts-E30-E36-E46.html"}]}, {"tier": "oe", "name": "Reinforcement plates (pair)", "pn": "Bavarian Autosport B3300044 · Z3-style", "price": "$40–80", "note": "Fits E36 coupes and sedans, not convertibles. Priced each; order two.", "only": ["cpe"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-578621-rear-shock-mount-reinforcement-priced-each/"}]}, {"tier": "aftermarket", "name": "ECS 4 mm reinforcement plates (pair)", "price": "$60–100", "note": "Thicker than Z3 plates, bolt-on for convertibles too.", "only": ["cvt"], "links": [{"store": "ECS", "url": "https://www.ecstuning.com/ES2642687/"}]}, {"tier": "oe", "name": "Shock mount gaskets and new nuts", "price": "$15–30", "note": "Elring gaskets are in the ECS kit. Upper damper nut sizes vary from shock to shock."}], "aftermarket": [{"name": "ECS complete rear upper mounting kit", "note": "Meyle HD mounts, Elring gaskets and 4 mm plates in one box.", "price": "See ECS", "signal": "One-box solution", "links": [{"store": "ECS", "url": "https://www.ecstuning.com/b-assembled-by-ecs-parts/complete-rear-upper-shock-mounting-kit/33521092362~kit/"}]}, {"name": "Powerflex rear mounts", "note": "Polyurethane, 10 mm thread.", "price": "See BimmerWorld", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Urethane-Bushings/Powerflex-Rear-Shock-Mounts-PFR5-5630-10.html"}]}, {"name": "BimmerWorld spherical mounts", "note": "Aircraft-quality bearings, remove about half an inch of play from a rubber mount, more noise.", "price": "See BimmerWorld", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/Camber-Caster-Parts/10mm-Spherical-Rear-Shock-Mounts-E30-E36-E46.html"}]}, {"name": "Turner aluminum rear shock tower mounts", "note": "Sold with gaskets, washers and Nyloc nuts.", "price": "See Turner"}], "tools": [{"name": "Floor jack and four jack stands", "note": "Plus a second jack for the trailing arm", "price": "$200+"}, {"name": "Socket set, ratchet wrenches", "note": "Several sizes for the upper nuts", "price": "$40"}, {"name": "Torque wrench", "note": "For the lower bolt", "price": "$40–70"}, {"name": "Flashlight", "note": "For checking the tower", "price": "$10"}], "before": ["Check which body style you have before ordering plates.", "Replace both sides at once.", "Look at the tower first. Cracks change the plan."], "steps": [{"title": "Lift the rear and take the wheels off", "blocks": [{"t": "text", "b": "Chock the front wheels, jack the rear and set the car on stands. Remove the wheels."}]}, {"title": "Open up the trunk trim", "blocks": [{"t": "text", "b": "Take off the tail light covers and fold the carpet liner back to see the top of each shock tower. Owner write-ups describe two 13 mm nuts holding each mount. A sedan or convertible may need more trim out of the way."}, {"t": "ill", "id": "e36-rsm-hero", "cap": "Look at the top of the tower before you start. Hairline cracks show up as rust lines around the bolt holes."}]}, {"title": "Support the shock and trailing arm", "caution": true, "blocks": [{"t": "text", "b": "Put a jack under the trailing arm. Take out the lower shock bolt."}, {"t": "warn", "b": "Don''t let the arm hang. The brake line and ABS wire will pull."}]}, {"title": "Take the old mount off", "blocks": [{"t": "text", "b": "Remove the upper nut on the shock and the bolts or nuts holding the mount to the tower. Lower the shock a little and pull the mount out. Clean the tower surface."}]}, {"title": "Look for cracks", "caution": true, "blocks": [{"t": "text", "b": "Check the tower and the mount seat for cracks, especially around the bolt holes. If you find any, the tower should be welded and plated before a new mount goes in."}]}, {"title": "Fit the plate and new mount", "blocks": [{"t": "text", "b": "Fit the new gasket, then the reinforcement plate, then the new mount. The plate goes between the mount and the tower on coupes and sedans."}, {"t": "text", "b": "Some convertibles mount the plate underneath, depending on clearance. Follow the plate''s instructions.", "only": ["cvt"]}, {"t": "torque", "label": "Shock shaft nut to mount", "nm": 14, "c": {"level": "medium", "n": 2, "note": "Pelican (from the Bentley) gives 10 ft-lb. One owner guide says 13 ft-lb."}, "note": "be gentle: about 10 ft-lb"}, {"t": "torque", "label": "Mount to body nuts", "nm": 24, "c": {"level": "high", "n": 3, "note": "Pelican 17 ft-lb, FCP Euro 25 Nm and an owner guide''s 18 ft-lb agree."}, "note": "two nuts per side"}, {"t": "note", "b": "Spherical and aftermarket mounts may use a different shaft nut or size. Check the mount''s sheet."}]}, {"title": "Reconnect and torque", "blocks": [{"t": "text", "b": "Bring the shock up into the new mount and tighten the upper nut. Then fit the lower bolt and tighten it at ride height."}, {"t": "torque", "label": "Rear shock to trailing arm", "nm": 77, "c": {"level": "high", "n": 3, "note": "ECS (77 Nm), Pelican (57 ft-lb) and the Bentley list agree. FCP''s coilover page lists 100 Nm."}, "note": "at ride height"}]}, {"title": "Refit the trim and test", "blocks": [{"t": "text", "b": "Put the trim back and the wheels on. Take a short drive over a rough road and listen for a knock."}]}], "alsoReplace": [{"name": "Rear shocks", "why": "If they''re old, it''s much easier now."}, {"name": "Rear spring pads and bump stops", "why": "Cheap, and they wear out with the shocks."}, {"name": "Subframe and trailing arm bushings", "why": "A knock may not be the mount at all. See the Bushings and mounts guides."}], "check": {"tab": "Mount or tower?", "title": "What''s making the noise?", "illId": "e36-rsm-hero", "illCap": "Rear clunks have a few causes. Check the mount first.", "rows": [{"see": "Rubber cracked or squashed", "means": "Failed mount.", "do": "Replace it, with a plate."}, {"see": "Rust lines or cracks at the tower", "means": "Tower damage.", "do": "Weld it, then fit plates."}, {"see": "Mount looks fine but you still clunk", "means": "Shock, bump stop, trailing arm bushing or sway bar link.", "do": "Check those next."}], "c": {"level": "medium", "n": 3, "note": "Standard E36 rear-end checks."}}, "aftercare": ["Re-check the upper nut after 100 miles.", "Look at the tower again at the next oil change.", "Get an alignment if you changed ride height."], "disagreements": [{"topic": "Rubber, urethane or spherical", "pos": "Spherical mounts remove about half an inch of play. They also add noise and vibration.", "call": "Street car: heavy-duty rubber or urethane. Spherical only for track cars."}, {"topic": "Plate thickness", "pos": "ECS''s plate is thicker than the Z3 plate. Turner says theirs and Bavarian Autosport''s also do the job.", "call": "Any plate beats none. Use a thicker one on a convertible or a track car."}], "sources": ["ECS — Complete rear upper shock mounting kit and heavy-duty reinforcement plate set", "Turner Motorsport / Bavarian Autosport — Z3-style plate (not for convertibles)", "BimmerWorld — spherical rear shock mounts; Powerflex rear shock mounts", "ECS — E36 rear suspension torque specifications", "Pelican Parts — E36 rear suspension overhaul (shaft nut, upper nuts, lower bolt)", "FCP Euro — E36 coilover install (upper nuts 25 Nm)", "Owner suspension install guide — tail light cover and carpet access to the upper mount"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-strut-brace', '{"id": "e36-strut-brace", "title": "Front strut brace", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Other E36 six-cylinders; the M3 needs the dust cap swap described below", "category": "Suspension", "kind": "upgrade", "heroId": "e36-brace-hero", "heroCap": "A strut brace ties the two front strut towers together across the engine bay to cut flex under cornering loads.", "glance": {"timeFirst": "30–45 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$100–500", "risk": "Cruise cable routing · tall strut pins hitting the bar", "why": "Tying the towers together reduces flex when you corner hard. It''s a bolt-on, half-hour job that needs no alignment.", "note": "On an M3 the stock dust cover no longer fits once the brace is on. Dinan lists replacement caps."}, "lifespan": {"title": "When to expect it", "headline": ["Not a wear item", "Fit it once, forget it"], "earliest": "Any time", "detail": "A brace doesn''t wear out. Check the fasteners occasionally.", "factors": [], "inspect": ["Check the nuts at each oil change"], "confidence": {"level": "single", "n": 1, "note": "No lifespan data needed."}}, "should": {"yesIf": ["You drive hard or on track", "You want a simple, reversible chassis upgrade", "You''re already doing suspension work and want to finish the set"], "codes": [], "notes": ["Gains are modest on a street car. It''s a supporting upgrade, not a first one."], "confidence": {"level": "medium", "n": 3, "note": "Dinan and Turner descriptions agree."}}, "parts": [{"tier": "aftermarket", "name": "Dinan strut tower brace", "pn": "D180-0362", "price": "$499.95", "note": "Fits 1995–99 M3. Includes end plates, rod ends and hardware.", "links": []}, {"tier": "aftermarket", "name": "ECS or Turner strut bar", "price": "$100–250", "note": "Check fitment for the M3 and your intake before ordering."}, {"tier": "oe", "name": "Replacement strut dust cap", "pn": "31 33 1 129 512 (1995 M3) · 31 33 1 133 729 (1996+ M3)", "price": "$10–25 each", "note": "Dinan lists these because the stock cover no longer fits with their brace."}], "aftermarket": [{"name": "Dinan front strut tower brace", "note": "Brushed aluminum or carbon fiber. Fits with any suspension. Four-year, 50,000-mile warranty.", "price": "$499.95", "signal": "Strongest-reputed design"}, {"name": "Turner billet X-brace", "note": "A front subframe X-brace, not a strut bar. Fits E36 coupes and sedans.", "price": "See Turner", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-65-bmw-strut-braces/m-1016-turner-motorsport"}]}], "tools": [{"name": "Socket set and wrench", "note": "Mostly 13 mm and 17 mm", "price": "$30"}, {"name": "Torque wrench", "note": "Low range", "price": "$40"}], "before": ["Check the brace clears your intake and any tall strut pins. Turner warns some aftermarket struts have an extra-tall pin that hits it.", "Measure first if you''ve fitted camber plates."], "steps": [{"title": "Take the flange nuts off", "blocks": [{"t": "text", "b": "Take off the three flange nuts on top of each strut tower. Keep them."}, {"t": "ill", "id": "e36-brace-hero", "cap": "Three flange nuts on each tower, then the end plates go on."}]}, {"title": "Fit the end plates", "blocks": [{"t": "text", "b": "Fit the end plates onto the strut towers. Fit the flange nuts finger-tight."}, {"t": "text", "b": "Route the cruise control cable under the brace. Dinan''s instructions call this out for the E36."}]}, {"title": "Fit the brace and adjust it", "blocks": [{"t": "text", "b": "Screw the rod ends into the center section with the jam nuts first. Place the brace so the logo reads from the front, and attach it to the end plate ears."}, {"t": "text", "b": "Adjust the rod ends so the brace sits without loading the towers, then tighten the jam nuts."}]}, {"title": "Tighten everything", "blocks": [{"t": "torque", "label": "Strut tower flange nuts", "nm": 24, "c": {"level": "high", "n": 3, "note": "Dinan (18 ft-lb), Garagistic (18.4 ft-lb) and Turner/Dinan''s strut-nut figure (24 Nm) agree."}, "note": "all six"}, {"t": "text", "b": "Hold the brace''s flanged nuts to protect the finish while tightening."}, {"t": "note", "b": "A front subframe X-brace is a separate part. Garagistic''s torque guide gives 31 ft-lb (about 42 Nm) for it."}]}, {"title": "Fit the replacement dust caps (M3)", "blocks": [{"t": "text", "b": "The stock dust cover on the M3 strut no longer fits. Fit the replacement caps in its place."}]}], "alsoReplace": [{"name": "Strut top mounts", "why": "The nuts are off anyway if you want to inspect them."}], "check": {"tab": "Worth it?", "title": "Will it help?", "illId": "e36-brace-hero", "illCap": "A brace helps most when the car is driven hard.", "rows": [{"see": "Track or autocross car", "means": "Worth it.", "do": "Fit it."}, {"see": "Street car with stock suspension", "means": "Small gain.", "do": "Do suspension first."}, {"see": "Intake or struts that hit the bar", "means": "Fitment problem.", "do": "Check clearance before ordering."}], "c": {"level": "medium", "n": 2, "note": "Typical advice."}}, "aftercare": ["Check the nuts after the first week.", "Look for rubbing against the intake or hood."], "disagreements": [{"topic": "Does a strut bar do anything on a street car?", "pos": "Makers say it reduces flex. Skeptics say gains are small without stiffer suspension.", "call": "Fit it with the rest of the set, but don''t expect a big change on its own."}], "sources": ["Dinan — front strut tower brace D180-0362 instructions (torque, cruise cable, dust caps)", "Turner Motorsport — strut braces and X-brace for E36", "Turner Motorsport — note on tall aftermarket strut pins", "Garagistic — E36 bolt torque guide (strut brace nuts 18.4 ft-lb, X-brace 31 ft-lb)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-sway-front', '{"id": "e36-sway-front", "title": "Front sway bar upgrade", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same bolt-in bars fit other 1992–1999 E36 six-cylinders, but the M3 uses its own front links (see the End links guide)", "category": "Suspension", "kind": "upgrade", "heroId": "e36-swayf-hero", "heroCap": "The front bar hangs from two brackets under the front subframe and links up to a bracket on each strut. Nothing about the job needs the subframe lowered.", "glance": {"timeFirst": "1.5–2.5 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$310–500", "risk": "Bar going in backwards or binding · links forced into place with preload", "why": "The stock M3 front bar is about 23 mm. A 28–30 mm bar cuts body roll and sharpens turn-in, and on this car it is a bolt-in job with the front wheels off and no subframe drop. The only part that takes thought is setting the links so the bar isn''t pre-loaded.", "note": "Most owners fit the bar after springs or coilovers, because lowering changes the link length the bar wants."}, "lifespan": {"title": "When to expect it", "headline": ["The bar itself doesn''t wear out", "The rubber bushings and links do"], "earliest": "A creak over speed bumps or a clunk on turn-in usually points at bushings or links first", "detail": "A sway bar is a torsion spring that never really fatigues on a street car. The reasons to change it are handling, not wear. If you''re only chasing a noise, try fresh bushings and links before spending on a bigger bar.", "factors": ["Dry or split rubber bushings", "Lowering without adjustable links", "Road salt on the brackets"], "inspect": ["Look for split bushings and a shiny wear ring on the bar", "Pry on each link for play"], "confidence": {"level": "medium", "n": 3, "note": "Wear pattern is consistent across Turner, BimmerWorld and owner write-ups, but nobody publishes an interval."}}, "should": {"yesIf": ["The car rolls more than you''d like in corners, especially on stock springs", "You''ve fitted lowering springs or coilovers and want the handling to match", "Your front bar bushings are split or the bar is clunking at the brackets", "You want a front/rear pair tuned together (see the Rear sway bar guide)"], "codes": [], "notes": ["A bigger front bar adds roll stiffness at the front. Used alone it shifts the balance toward understeer at the limit, so most people pair it with a modest rear bar rather than a monster one.", "Fit the bar after your springs and dampers. A bar set up on the stock ride height will be pre-loaded once the car is lowered."], "confidence": {"level": "medium", "n": 4, "note": "Turner, H&R, Eibach and MotoIQ all describe the same trade-offs."}}, "variants": {"questions": [{"question": "Which bar are you fitting?", "hint": "Each of these bolts in without changes to the subframe. The bar you pick sets the steps below.", "options": [{"id": "hr", "label": "H&R 28 mm", "when": "Fixed rate, Teflon-lined bushings", "brand": true}, {"id": "turner", "label": "Turner 30 mm", "when": "Solid bar, two adjustment holes", "brand": true}, {"id": "hotchkis", "label": "Hotchkis tubular", "when": "33.4 mm hollow, two adjustment holes", "brand": true}, {"id": "other", "label": "A different bar", "when": "Follow the maker''s sheet where it differs"}]}]}, "parts": [{"tier": "aftermarket", "name": "Front sway bar (your choice)", "price": "$300–450", "note": "Comes with bushings and brackets on most kits; confirm yours does", "only": ["other"]}, {"tier": "aftermarket", "name": "H&R front sway bar, 28 mm", "pn": "E36 M3 front", "price": "$307.95", "note": "Teflon-lined urethane bushings that need no grease. Bolts in with the stock links.", "only": ["hr"], "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/H-R-Sway-Bar-E36-M3-Front.html"}]}, {"tier": "aftermarket", "name": "Turner 30 mm front sway bar", "price": "$300–500", "note": "Two adjustment holes, CNC ends, works with M or non-M links. Sold alone or in a 30/24 front-and-rear set.", "only": ["turner"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-131-bmw-sway-bar/m-1016-turner-motorsport"}]}, {"tier": "aftermarket", "name": "Hotchkis tubular front bar, 33.4 mm", "price": "Check current price", "note": "Comes with polyurethane bushings, grease-fitting mounts and hardware. Confirm it is still in production before ordering.", "only": ["hotchkis"]}, {"tier": "oe", "name": "Front sway bar link, M3", "pn": "31352227203 (Lemförder) · 31352227203MY (Meyle HD)", "price": "$25–45 each", "note": "The M3 has its own link; the non-M 31351091764 is a different part. Replace both while the bar is out if they have play."}, {"tier": "oe", "name": "Sway bar mounting brackets", "pn": "31351131622", "price": "$15–30 each", "note": "Only if yours are rusted through or the bar rubs. Most kits supply their own."}], "aftermarket": [{"name": "H&R front bar, 28 mm", "note": "Fixed rate, Teflon-lined bushings, German-made.", "price": "$307.95", "signal": "Maintenance-free bushings", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/H-R-Sway-Bar-E36-M3-Front.html"}]}, {"name": "Turner 30 mm front bar", "note": "Solid, two positions. Turner suggests starting front on stiff and rear on soft.", "price": "See Turner", "signal": "World Challenge-derived", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-131-bmw-sway-bar/m-1016-turner-motorsport"}]}, {"name": "Hotchkis front bar", "note": "33.4 mm tubular, two holes giving roughly 300% or 380% of the stock bar''s stiffness in one magazine test.", "price": "See retailer"}, {"name": "Eibach front bar, 26 mm", "note": "Adjustable ends. BimmerWorld lists it as discontinued, so it only turns up used.", "price": "Used only"}], "tools": [{"name": "Floor jack and four jack stands", "note": "Rated for the car. Never use the sway bar as a lift point.", "price": "$150+"}, {"name": "Socket set and combination wrenches", "note": "Mostly 13, 16 and 17 mm. A thin wrench for the link studs.", "price": "$40"}, {"name": "Torque wrench", "note": "Needed for the bracket bolts and links", "price": "$40–70"}, {"name": "Teflon tape or silicone-free grease", "note": "On the bar where it meets each bushing, if your bushings aren''t pre-lined", "price": "$5"}], "before": ["Lay the new bar next to the old one on the floor and compare every bend before you start.", "Chock the rear wheels and make sure the car is on stands that sit on the frame rails, not on the bar or links.", "If you also plan springs, dampers or a rear bar, do those first and set ride height before the bar.", "Soak the bracket nuts and link nuts in penetrating oil the night before if the car sees salt."], "steps": [{"title": "Raise the front and take the wheels off", "blocks": [{"t": "text", "b": "Chock the rear wheels, jack the front by the jack point or subframe, and put stands under the frame rails. Take both front wheels off."}, {"t": "warn", "b": "Support the car on stands, not the jack. You''ll be pulling and pushing on a bar under the car."}]}, {"title": "Find and photograph everything", "blocks": [{"t": "text", "b": "Look under the front subframe. The bar runs across the car and is held by two brackets (a rubber bushing inside each). The ends connect through a short link up to a bracket on each strut. On the M3 the link goes to the strut, not the control arm."}, {"t": "text", "b": "Take a photo from each side. Mark which end of each bushing faces the car, because the new ones go on the same way."}, {"t": "ill", "id": "e36-swayf-hero", "cap": "Two brackets under the subframe, one link on each control arm. Take a photo before you take anything off."}]}, {"title": "Undo the links at the bar", "blocks": [{"t": "text", "b": "Take off the nut holding each link to the bar. Hold the stud with a wrench while you turn the nut, or the ball stud just spins."}, {"t": "note", "b": "If a link''s ball stud turns with the nut, hold it with a thin wrench on the flats or an Allen key in the end of the stud, depending on the link."}]}, {"title": "Remove the brackets and drop the bar", "timeSink": true, "blocks": [{"t": "text", "b": "Each bracket has two nuts. Take all four off, supporting the bar as the last one comes loose."}, {"t": "text", "b": "Lower the bar and shift it a few inches to one side so it comes out past the tie rods and control arms. You don''t need the subframe down. Turn the bar as you go. It''s an awkward shape and goes in and out only at one angle."}]}, {"title": "Compare, then dress the new bar", "blocks": [{"t": "text", "b": "Put the old and new bar side by side. Slide the new bushings onto the same position as the old ones."}, {"t": "text", "b": "Spread the bushings by hand rather than prying with a screwdriver."}, {"t": "text", "b": "Teflon-lined H&R bushings go on dry. Anything else gets a thin wrap of Teflon tape on the bar where it meets each bushing, or the maker''s grease. Plain grease squeezes out over time and the squeak returns, which is why the tape is the popular fix.", "only": ["turner", "hotchkis", "other"]}, {"t": "text", "b": "Teflon-lined H&R bushings need no grease at all, so skip any lube.", "only": ["hr"]}]}, {"title": "Fit the bar and tighten the brackets", "blocks": [{"t": "text", "b": "Raise the bar up behind the steering components, set the bushings where the old ones sat, and fit the brackets and nuts finger-tight. Check the bar is centered side to side and not touching the steering rack or tie rods."}, {"t": "torque", "label": "Sway bar bracket nuts", "nm": 22, "c": {"level": "high", "n": 3, "note": "The Bentley list and Pelican''s E36 bushing article both give 16 ft-lb."}, "note": "four nuts, 16 ft-lb"}]}, {"title": "Pick the adjustment position", "blocks": [{"t": "text", "b": "The holes further from the end of the bar give a shorter lever and a stiffer setting. Turner suggests starting the front on the stiff hole and the rear on its soft hole, then adjusting from how it feels."}, {"t": "text", "b": "Start in the middle if you''re unsure and change one hole at a time."}], "only": ["turner", "hotchkis"]}, {"title": "Connect the links and set preload", "caution": true, "blocks": [{"t": "text", "b": "Fit the links to the bar, finger-tight at first. Hold the stud with a wrench while you turn the nut, or the ball stud just spins."}, {"t": "text", "b": "The goal is a bar that rests with no twist in it when the car is on the ground. If a link only goes on by forcing the bar up or down, the link is the wrong length (usually after lowering). Adjustable links solve that. See the End links guide."}, {"t": "text", "b": "Final tightening is best done with the car on its wheels so the bar isn''t twisted while you torque it."}, {"t": "torque", "label": "Link to strut bracket nut", "nm": 59, "c": {"level": "medium", "n": 3, "note": "Bentley list gives 44 ft-lb for the M3. Doug''s Domain says BMW TIS gives 59 Nm for all E36 and that the non-M Bentley figure is wrong."}, "note": "hold the stud while you turn the nut"}, {"t": "torque", "label": "Link to bar nut", "nm": 42, "c": {"level": "medium", "n": 2, "note": "Garagistic''s guide gives 31 ft-lb for the M10 nut, and Pelican gives 31 ft-lb for its E36 links."}, "note": "if your bar kit ships its own links, use the kit''s number"}]}, {"title": "Lower the car and finish", "blocks": [{"t": "text", "b": "Put the wheels on, lower the car, and bounce the front a few times to settle it. Then final-tighten the link nuts with the car at normal ride height, and finish the wheel bolts."}, {"t": "torque", "label": "Wheel bolts", "nm": 100, "c": {"level": "medium", "n": 2, "note": "Bentley E36 list gives 74 ft-lb (about 100 Nm). Some wheel makers specify differently, so follow yours if it does."}, "note": "star pattern, car on the ground"}, {"t": "text", "b": "Check the bar doesn''t rub the steering rack or exhaust at full lock and over a bump."}]}], "alsoReplace": [{"name": "Sway bar links", "why": "They''re off for this job anyway, and M3 front links are a known clunk. Replace them if there is any play."}, {"name": "Adjustable links (if lowered)", "why": "Lowering changes the bar-to-arm distance. Adjustable links let you remove preload instead of fighting it."}, {"name": "Front lower control arm bushings", "why": "With the car up and the bar out you can see what shape they''re in. A worn bushing makes a new bar feel vague."}], "check": {"tab": "Noise or clunk?", "title": "Is it the bar, the links or something else?", "illId": "e36-swayf-hero", "illCap": "Three places a front-end clunk can hide. Check them in this order.", "rows": [{"see": "Clunk over small bumps, worse in a turn", "means": "Most often a worn sway bar link.", "do": "Pry each link with a bar; replace any that moves or rattles."}, {"see": "Creak or groan over speed bumps that goes away when you spray the bushing", "means": "Dry or worn bar bushings.", "do": "Lube-and-wrap or replace the bushings."}, {"see": "A thud on bumps that isn''t affected by turning", "means": "Control arm bushing or ball joint, or the dampers.", "do": "Check those before buying a bar. See the Steering and Bushings guides."}], "c": {"level": "medium", "n": 3, "note": "Common E36 front-end diagnoses from Turner and owner write-ups."}}, "aftercare": ["Re-check the bracket nuts after the first 100 miles.", "If it squeaks, wrap or re-lube the bushing contact patch. That is almost always the cause.", "Alignment isn''t needed for the bar alone, but get one if you changed springs or dampers at the same time."], "disagreements": [{"topic": "Does a bigger front bar fix understeer?", "pos": "Turner says the E36 wants a large front bar and a modest rear. Eibach''s own notes say a front-only upgrade sharpens low-speed turn-in but pushes the car into understeer sooner near the limit.", "call": "Both can be true. For a street car, a larger front bar with a smaller rear bar is the common setup. If you drive hard, treat the rear bar setting as the thing to tune."}, {"topic": "Grease or Teflon tape on the bushings", "pos": "Some makers supply grease fittings. MotoIQ''s tester says he''s had grease squeezed out and squeaks come back, and now wraps the bar in tape.", "call": "Tape, if your bushings aren''t pre-lined. It costs nothing and stays quiet longer."}, {"topic": "Stock bar size", "pos": "MotoIQ measured the stock front bar at about 23 mm. Other sellers quote different stiffness comparisons without giving a diameter.", "call": "Use about 23 mm as the baseline and treat any percentage from a seller as relative to their own measurement."}], "sources": ["MotoIQ — Project E36 M3 Part 5 (removal, stock bar size, Hotchkis bar, Teflon tape tip)", "Turner Motorsport — E36 M3 front/rear sway bar kits (30/24 set, adjustment holes, link compatibility)", "BimmerWorld — H&R E36 M3 front sway bar (28 mm, Teflon-lined bushings)", "BimmerWorld — Eibach E36 M3 front sway bar (26 mm, listed as discontinued)", "Ground Control — E36 sway bar directions (link length and preload set last)", "Bentley E36 list as posted on Club Cobra (bar bracket 16 ft-lb, M3 link to strut 44 ft-lb)", "Pelican Parts — E36 front sway bar bushing replacement (16 ft-lb brackets, 31 ft-lb links)", "Doug''s Domain — E36 swaybar service (59 Nm link nut per TIS)", "Garagistic — E36 bolt torque guide (M10 link nut 31 ft-lb)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-sway-rear', '{"id": "e36-sway-rear", "title": "Rear sway bar upgrade", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same bolt-in bars fit other 1992–1999 E36 six-cylinders", "category": "Suspension", "kind": "upgrade", "heroId": "e36-swayr-hero", "heroCap": "The rear bar bolts to two tabs on the rear subframe, and those tabs are the E36''s weak point. Inspect them before you load them with a bigger bar.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$250–450", "risk": "A cracked subframe tab under a stiffer bar · welding near the fuel tank", "why": "The rear bar balances whatever you did at the front. It''s a straightforward bolt-in swap, but a stiffer bar loads two small subframe tabs that crack on E36s. Check them first and reinforce them if you can.", "note": "Turner and Ground Control both say to reinforce the rear bar mounts at the same time as a bigger bar. Reinforcing means welding."}, "lifespan": {"title": "When to expect it", "headline": ["No wear interval for the bar", "The mounting tabs are the thing to watch"], "earliest": "Subframe tab cracks show up on cars with a stiff bar, hard use, or just age and rust", "detail": "A cracked tab shows up as a clunk or the bar shifting side to side under load. On a car that has had a bigger bar and no reinforcement, look at the tabs at every oil change.", "factors": ["A stiffer rear bar", "Track or autocross use", "Rust around the tab welds"], "inspect": ["Look at both tabs with a flashlight and a mirror", "Push the bar by hand and watch for movement at the tab"], "confidence": {"level": "medium", "n": 3, "note": "Reinforcement is recommended by Turner and Ground Control; no failure rates published."}}, "should": {"yesIf": ["You''ve fitted a larger front bar and want the balance to follow", "The car is lowered and feels loose or tail-happy at the limit", "Your stock rear bushings or links are worn", "You''re willing to inspect, and if needed reinforce, the rear tabs"], "codes": [], "notes": ["Rear stiffness is easy to overdo. A bigger rear bar brings the tail around sooner, so most street setups stay modest and use the softer hole."], "confidence": {"level": "medium", "n": 3, "note": "Turner, Hotchkis and Ground Control all warn against an oversized rear bar."}}, "variants": {"questions": [{"question": "Which bar are you fitting?", "hint": "All three bolt in. They differ in size, adjustment and what each maker says about reinforcement.", "options": [{"id": "rturner", "label": "Turner 24 mm", "when": "Solid bar, two adjustment holes", "brand": true}, {"id": "rhotchkis", "label": "Hotchkis 25.4 mm", "when": "Adjustable, hollow", "brand": true}, {"id": "rother", "label": "A different bar", "when": "Ground Control, H&R, or another maker"}]}, {"question": "What shape are the rear subframe bar tabs in?", "hint": "Look at the two tabs the bar bolts to. If you can''t see them clearly, answer \"not sure\" and the guide shows you what to look for.", "options": [{"id": "tabsok", "label": "Already reinforced or clearly fine", "when": "No cracks, or a plate is already welded on"}, {"id": "tabsunknown", "label": "Not sure / stock", "when": "Standard tabs; I''ll check them"}, {"id": "tabsbad", "label": "Cracked or bent", "when": "I can see damage"}]}]}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar (your choice)", "price": "$200–400", "note": "Check it includes bushings and brackets", "only": ["rother"]}, {"tier": "aftermarket", "name": "Turner 24 mm rear sway bar", "price": "See Turner", "note": "Solid, two holes. Sold alone or in a 30/24 set. Turner says to fit their rear reinforcement kit at the same time.", "only": ["rturner"], "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-131-bmw-sway-bar/m-1016-turner-motorsport"}]}, {"tier": "aftermarket", "name": "Hotchkis rear bar, 25.4 mm", "price": "See retailer", "note": "Two holes. Roughly 115% or 140% of stock stiffness in the tested kit. Confirm availability.", "only": ["rhotchkis"]}, {"tier": "oe", "name": "Rear sway bar link", "pn": "33551126932 (alt 33551124375)", "price": "$20–35 each", "note": "Lemförder. Replace if there''s play; adjustable links are recommended for lowered cars."}, {"tier": "aftermarket", "name": "Rear sway bar tab reinforcement", "price": "$60–150", "note": "A weld-on reinforcement kit for the subframe tabs. Needs welding.", "only": ["tabsunknown", "tabsbad"]}], "aftermarket": [{"name": "Turner 24 mm rear bar", "note": "Solid, two positions. Turner starts the rear on soft.", "price": "See Turner", "signal": "Often paired with the 30 mm front", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E36-M3-Parts/c-131-bmw-sway-bar/m-1016-turner-motorsport"}]}, {"name": "Hotchkis rear bar", "note": "25.4 mm, two holes (about 115% and 140% of stock in the tested kit).", "price": "See retailer"}, {"name": "Ground Control rear bar", "note": "Their sheet has you weld reinforcements on the stock bracket in four places and set link length for about 1/8 in of bar-to-axle clearance.", "price": "See Ground Control", "links": [{"store": "Ground Control", "url": "https://groundcontrolstore.com/pages/e36-sway-bar-directions"}]}], "tools": [{"name": "Floor jack and four jack stands", "note": "Rated for the car", "price": "$150+"}, {"name": "Socket set and combination wrenches", "note": "Mostly 13 to 17 mm", "price": "$40"}, {"name": "Torque wrench", "note": "For brackets and links", "price": "$40–70"}, {"name": "Flashlight and inspection mirror", "note": "For the subframe tabs", "price": "$10"}, {"name": "Welder (or a shop)", "note": "Only if you''re reinforcing the tabs", "price": "Shop labor"}], "before": ["Decide up front whether you''ll reinforce the tabs. If you will, do it before the bar goes on.", "Have the car lowered or sprung before you set rear link length.", "Compare old and new bars on the floor before you start."], "steps": [{"title": "Lift the rear and take the wheels off", "blocks": [{"t": "text", "b": "Chock the front wheels, lift the rear, and put the car on stands under the frame rails. Remove both rear wheels."}, {"t": "warn", "b": "Put the stands where the car is strong. Not on the bar, the exhaust or the subframe tabs."}]}, {"title": "Look at the tabs before anything else", "caution": true, "blocks": [{"t": "text", "b": "Find the two tabs on the rear subframe that the bar bolts to. Clean off dirt and look for cracks around the weld and at the bolt holes, and for a tab that has bent."}, {"t": "ill", "id": "e36-swayr-hero", "cap": "The two subframe tabs that carry the bar. A crack at the weld is the usual failure."}, {"t": "note", "b": "If a plate has already been welded on and looks sound, you''re done with the inspection. If you see cracks or a bent tab, fix them first. A stiffer bar will make it worse."}]}, {"title": "Undo the links, then the brackets", "blocks": [{"t": "text", "b": "Take the link nuts off at the bar end. Hold the stud with a wrench while you turn the nut, or the ball stud just spins."}, {"t": "text", "b": "Take out the two bolts holding each bracket and lower the bar. Check what blocks it from coming out on your car. Exhaust sections and rear braces are the usual suspects. Support the exhaust before unhooking anything."}]}, {"title": "Have the tabs repaired or reinforced", "caution": true, "blocks": [{"t": "text", "b": "A cracked or bent tab needs welding, ideally with a reinforcement plate. Bring the subframe to a shop if you aren''t confident welding."}, {"t": "warn", "b": "The fuel tank and lines sit above the rear subframe. Whoever welds must protect them and have a fire extinguisher on hand."}, {"t": "text", "b": "Ground Control''s instructions weld a reinforcement onto the stock bracket in four places. Turner sells a rear reinforcement kit and recommends fitting it with any rear bar."}], "only": ["tabsunknown", "tabsbad"]}, {"title": "Put the bushings on the new bar", "blocks": [{"t": "text", "b": "Slide the bushings onto the bar in the same position as the old ones. Wrap the contact area with Teflon tape or use the maker''s grease so it doesn''t squeak."}, {"t": "text", "b": "If a bracket binds on the bushing, shim it with washers. Use the same number of washers on each side."}]}, {"title": "Fit the bar and tighten the brackets", "blocks": [{"t": "text", "b": "Raise the bar into place and fit the brackets. Tighten the pinch bolts last, after the bar is where you want it."}, {"t": "torque", "label": "Rear bar clamp bolts", "nm": 22, "c": {"level": "single", "n": 1, "note": "Doug''s Domain E36 swaybar service gives 22 Nm (16 ft-lb). Check your bar''s sheet too."}, "note": "16 ft-lb"}]}, {"title": "Choose the adjustment position", "blocks": [{"t": "text", "b": "Start on the soft hole at the rear. Turner suggests stiff in front and soft at the rear. Change one hole at a time and drive it before you go stiffer."}], "only": ["rturner", "rhotchkis"]}, {"title": "Connect the links and set preload", "caution": true, "blocks": [{"t": "text", "b": "Fit the links, finger-tight. They should go on without forcing the bar. If they don''t, use adjustable links."}, {"t": "text", "b": "Ground Control''s sheet asks for about 1/8 in between the bar and the axle when you set link length, then tightens the link at the bar last, with the car on the ground."}, {"t": "text", "b": "Do the final tightening with the car at ride height."}, {"t": "torque", "label": "Rear link nuts", "nm": 41, "c": {"level": "single", "n": 2, "note": "Pelican says 30 ft-lb at every rear link connection. Doug''s Domain says the spec is 44 ft-lb."}, "note": "30 ft-lb, or up to 44", "alt": [59]}]}, {"title": "Lower the car and test", "blocks": [{"t": "text", "b": "Put the wheels on, lower the car, bounce it to settle, and check for rubbing at the exhaust and axle. Take a short drive and listen for clunks."}]}], "alsoReplace": [{"name": "Rear sway bar links", "why": "Cheap, and worn rubber is a common cause of rear clunks."}, {"name": "Rear shock mounts", "why": "The rear shock mount reinforcement is the other half of the same weak area. See the RSM guide."}, {"name": "Adjustable rear links", "why": "Needed to set preload after lowering."}], "check": {"tab": "Tabs or bushings?", "title": "What''s the noise?", "illId": "e36-swayr-hero", "illCap": "Rear clunks come from the links, the bushings, or a cracked tab.", "rows": [{"see": "Clunk over bumps from the rear", "means": "Worn sway bar link.", "do": "Pry on each link; replace if loose."}, {"see": "Bar moves side to side when pushed", "means": "Worn bushings or a cracked tab.", "do": "Inspect the tabs, then replace bushings."}, {"see": "Visible crack at a tab weld", "means": "Subframe tab failure.", "do": "Have it welded and reinforced before fitting any bar."}], "c": {"level": "medium", "n": 3, "note": "Common rear-end checks from Turner and Ground Control."}}, "aftercare": ["Look at the tabs again after a month of driving, then at every oil change.", "Listen for squeaks. If one appears, wrap or re-lube the bushing contact patch.", "Get an alignment if you changed springs or dampers in the same visit."], "disagreements": [{"topic": "Reinforce or just bolt on", "pos": "Turner and Ground Control both say to reinforce the tabs when fitting a larger bar. Some owners fit a bar to an unreinforced car and see no problem.", "call": "Inspect first. Reinforce if there''s any crack, or if the car will see track use."}, {"topic": "How big a rear bar", "pos": "Turner''s set pairs a 30 mm front with a 24 mm rear. Other makers go larger.", "call": "Go modest at the rear and start on the soft hole."}], "sources": ["Turner Motorsport — E36 M3 sway bar kits (24 mm rear, reinforcement recommendation)", "Ground Control — E36 sway bar directions (reinforcement welds, bushing shims, 1/8 in clearance)", "MotoIQ — Project E36 M3 Part 5 (20 mm stock rear bar, Hotchkis rear bar percentages)", "Pelican Parts — E36 rear sway bar drop link replacement (30 ft-lb)", "Doug''s Domain — E36 swaybar service (rear clamps 22 Nm, link spec 44 ft-lb)"], "embeds": []}'::jsonb);
